window.JASTROW_CHUNKS[43]={"17200":{"h":"מגרפתיה","r":"M00224","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַגְרוֹפִיתָא\">מַגְרוֹפִיתָא</a></div>","alt":[]},"17201":{"h":"מַגְרֶרֶת","r":"M00225","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (גָּרַר I, v. <a href=\"#\" data-headword=\"גָּרַד\">גָּרַד</a>) <i>strigil</i>. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 19</span> <span dir=\"rtl\">אין מתגררין במגו׳</span> ed. Zuck. (Var. <span dir=\"rtl\">מגרדין במגרדת</span>); <span class=\"citation\">Sabb. 147ᵇ</span> <span dir=\"rtl\">אין גוררין במגרר׳</span>, v. <a href=\"#\" data-headword=\"גָּרַר I\"><span dir=\"rtl\">גָּרַר</span> I</a>.—Pl. <span dir=\"rtl\">(<span dir=\"rtl\">מַגְרֵדוֹת</span>) <span dir=\"rtl\">מַגְרֵרוֹת</span></span>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 12</span> <span dir=\"rtl\">מגרר׳</span> ed. Zuck.; <span class=\"citation\">Kel. XII, 6</span> <span dir=\"rtl\">(<span dir=\"rtl\">מגרד׳</span>) <span dir=\"rtl\">מגריד׳</span></span>.</div>","alt":["(מְגוֹרֶרֶת","מַגְרֵדָה","מַגְרֶדֶת)"]},"17202":{"h":"מַגְרַרְתָּא","r":"M00226","html":"<div class=\"sense\"> <span class=\"citation\">Sabb. 147ᵇ</span> (Ms. M. margin: <a href=\"#\" data-headword=\"מַגְרְדָא\">מגרדא</a>; Rashi Ms. <a href=\"#\" data-headword=\"מַגְרְדָא\">מַגְרַדְתָּא</a>).</div>","alt":[]},"17203":{"h":"מִגְרָשׁ","r":"M00227","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>open space outside of a place</i>. <span class=\"citation\">Gen. R. s. 21</span>, end (ref. to <span class=\"citation\">Gen. III, 24</span>) <span dir=\"rtl\">למִגְרָשָׁהּ של עדן וכ׳</span> he drove him out to the open outskirts of the garden of Eden. <span class=\"citation\">Macc. 12ᵃ</span>, a. e. <span dir=\"rtl\">אין עושין שדה מ׳ וכ׳</span></div>","alt":[]},"17204":{"h":"מְגֶרֶת","r":"M00228","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹגֵרָה\">מוֹגֵרָה</a></div>","alt":[]},"17205":{"h":"מגרת","r":"M00229","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Hos. XI, 4</span>, v. <span dir=\"rtl\">מִגְדָּא II</span></div>","alt":[]},"17206":{"h":"מִדְּ־","r":"M00230","html":"<div class=\"sense\">, a prefix, = <span dir=\"rtl\">מִן דְּ־</span>, </div><div class=\"sense\"><b>1)</b> <i>than that</i>. <span class=\"citation\">Targ. O. Ex. XIV, 12</span> <span dir=\"rtl\">מִדְּנִימוּת</span> (ed. Amst. <span dir=\"rtl\">מֵדִנְמוּת</span>, corr. acc.); a. e.</div><div class=\"sense\"><b>—2)</b> <i>from the time that; from the fact that; since, because</i>. <span class=\"citation\">Targ. Gen. XLVIII, 15</span>. <span class=\"citation\">Targ. I Sam. I, 12</span>. <span class=\"citation\">Targ. O. Ex. XIV, 11</span>; a. fr.—<span class=\"citation\">Ber. 2ᵇ</span> <span dir=\"rtl\">מִדְּקָתָנִי … שמע מינה וכ׳</span> from the fact that the Boraitha says … we conclude that &amp;c. <span class=\"citation\">Ib. 15ᵇ</span> … <span dir=\"rtl\">מדקתני סיפא … מכלל</span> since the second clause reads, ‘R. Judah says &amp;c.’, we must conclude that the first clause does not express R. Judah’s opinion.—<span class=\"citation\">Gitt. 19ᵇ</span> <span dir=\"rtl\">מִדְּהָא הואי וכ׳</span> since one (of the papers found) was undoubtedly there (before the letter of divorce was thrown there), the other was surely there, too, and the letter of divorce may have been carried off by mice. <span class=\"citation\">B. Mets. 83ᵇ</span> <span dir=\"rtl\">מִדְּחָצִיף כולי האי</span> since he is so bold.—<span dir=\"rtl\">מדאורייתא</span>, <span dir=\"rtl\">מדרבנן</span>, v. <a href=\"#\" data-headword=\"אוֹרַיְיתָא\">אוֹרַיְיתָא</a>.—<span class=\"citation\">Gitt. 37ᵃ</span>, a. fr. <span dir=\"rtl\">מִדְּרַבִּי וכ׳</span> as concluded from what R … said; a. v. fr.</div>","alt":[]},"17207":{"h":"מַדָּא","r":"M00231","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> h. <a href=\"#\" data-headword=\"מִדְּ־\">מַד</a>; <a href=\"#\" data-headword=\"מָדַד\">מדד</a>) <i>the priest’s cloak</i>. <span class=\"citation\">Ber. 28ᵃ</span>; v. <a href=\"#\" data-headword=\"לְבֵשׁ\">לְבַשׁ</a>.</div>","alt":[]},"17208":{"h":"מָדָאָה","r":"M00232","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָדָיָא\">מָדָיָא</a></div>","alt":[]},"17209":{"h":"מַדָּאנָא","r":"M00233","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַדָּנָא\">מַדָּנָא</a></div>","alt":[]},"17210":{"h":"מַדָּאתָא","r":"M00234","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. P. Sm. 2011) = <a href=\"#\" data-headword=\"מִנְדָּה\">מִנְדָּה</a>, <i>tribute, tax, fine</i>. <span class=\"citation\">Targ. Prov. XII, 24</span> למ׳ Ar. s. v. <a href=\"#\" data-headword=\"כַּרְגָּא\">כרגא</a> (ed. <span dir=\"rtl\">למִסָּא</span>).</div>","alt":[]},"17211":{"h":"מֵדְבָא","r":"M00235","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵידְבָא\">מֵידְבָא</a></div>","alt":[]},"17212":{"h":"*מַדְבּוּרָא","r":"M00236","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּבַר\">דְּבַר</a>) <i>guide</i>; <span dir=\"rtl\">מ׳ דנורא</span> <i>torch</i> or <i>torch-carrier</i> directing the work of night laborers.—Pl. <a href=\"#\" data-headword=\"*מַדְבּוּרָא\">מַדְבּוּרֵי</a>. <span class=\"citation\">M. Kat. 12ᵇ</span> Ms. M. a. Ar. (v. Rabb. D. S. a. l. note; ed. <span dir=\"rtl\">מְדוּכְרֵי</span>, Alf. <a href=\"#\" data-headword=\"מַדְכּוּרָא\">מַדְכּוּרָא</a>).</div>","alt":[]},"17213":{"h":"מַדְבַּח","r":"M00237","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"דְּבַח I\">דְּבַח</a>) = h. <a href=\"#\" data-headword=\"מִזְבֵּחַ\">מִזְבֵּחַ</a>, <i>altar</i>. <span class=\"citation\">Targ. Josh. XXII, 10</span>. <span class=\"citation\">Targ. Gen. XII, 8</span>; a. fr.—<span class=\"citation\">Zeb. 54ᵃ</span> רב מתרגם באחסנתיה יתבני מ׳ Rab translated (<span dir=\"rtl\">ובן כתפיו שכן</span>, <span class=\"citation\">Deut. XXXIII, 12</span>) on his possession shall the altar be built; a. e.—Pl. <span dir=\"rtl\">מַדְבְּחִין</span>, <a href=\"#\" data-headword=\"מַטְבָּחַיָּיא\">מַדְבָּחַיָּיא</a>; fem. <span dir=\"rtl\">מַדְבְּחָתָא</span>. <span class=\"citation\">Targ. O. Num. XXIII, 1</span>; <span class=\"citation\">4</span>; a. e.—<span class=\"citation\">Targ. Ps. LXXXIV, 4</span>.—<span dir=\"rtl\"><span dir=\"rtl\">משקי בי</span> (<span dir=\"rtl\">בית</span>) <span dir=\"rtl\">מדבחייא</span></span> liquids used on the altar (wine, oil), contrad. to <span dir=\"rtl\">משקי בי מטבחייא</span> liquids of the slaughtering place (blood, water). <span class=\"citation\">Pes. 17ᵃ</span> (ref. to <span class=\"citation\">Eduy. VIII, 4</span>); <span class=\"citation\">Tosef. Kel. B. Mets. V, 7</span> (ed. Zuck. <span dir=\"rtl\">מט׳</span>).</div>","alt":["מַדְבְּחָא"]},"17214":{"h":"מדבך","r":"M00238","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִדְבָּךְ\">נִדְבָּךְ</a> a. <a href=\"#\" data-headword=\"מִרְבּךְ\"><a href=\"#\" data-headword=\"מִרְבּךְ\">מִרְבָּךְ</a>.</a></div>","alt":[]},"17215":{"h":"מַדְבַּק","r":"M00239","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּבֵק\">דְּבַק</a>) <i>junction, welding</i>. <span class=\"citation\">Targ. I Kings VII, 29</span>; <span class=\"citation\">36</span> (h. text <span dir=\"rtl\">ליות</span>).—Pl. constr. <span dir=\"rtl\">מַדְבְּקֵי</span>; <span dir=\"rtl\">מ׳ ידין</span> <i>arm-pits</i>. <span class=\"citation\">Targ. Jer. XXXVIII, 12</span>. <span class=\"citation\">Targ. Ez. XIII, 18</span> ed. Lag. (Var. <span dir=\"rtl\">מרב׳</span>; ed. Wil. <span dir=\"rtl\">מַרְפְּקֵי</span>).</div>","alt":[]},"17216":{"h":"מְדַבֵּר","r":"M00240","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דָּבַר\">דָּבַר</a>) </div><div class=\"sense\"><b>1)</b> <i>speaker</i>.—Pl. <span dir=\"rtl\">מְדַבְּרִים</span>. <span class=\"citation\">Ber. 63ᵇ</span>, a. e. <span dir=\"rtl\">ראש המ׳ וכ׳</span> the first among the speakers on all occasions (attribute of R. Judah).–</div><div class=\"sense\"><b>2)</b> <i>the anterior part of the tongue</i>. <span class=\"citation\">Bekh. VI, 8</span>; <span class=\"citation\">Tosef. ib. IV, 11</span>; <span class=\"citation\">Kidd. 25ᵃ</span></div>","alt":[]},"17217":{"h":"מִדְבָּר","r":"M00241","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"דְּבַר\">דְּבַר</a>) <i>pasture-ground, desert</i>. <span class=\"citation\">Gen. R. s. 31</span>, end. <span class=\"citation\">Cant. R. to IV, 4</span> (play on <span dir=\"rtl\">מדברך</span> <span class=\"citation\">ib. 3</span>) <span dir=\"rtl\">אע&quot;פ שהוא מ׳וכ׳</span> although the Temple is a desert, you are bound to observe the sacredness of its precincts now that it is ruined &amp;c.; a. fr.—<span dir=\"rtl\">מֵתֵי מ׳</span> the generation that died in the wilderness. <span class=\"citation\">B. Bath. 73ᵇ</span> bot.; a. fr.—<span class=\"citation\">Tosef. Macc. III</span> (<span class=\"citation\">II), 2</span>; <span class=\"citation\">Macc. 9ᵇ</span>; Y. ib. II, 31ᵈ top <span dir=\"rtl\">בצר במ׳</span> (b. h.) <i>Bezer in the Wilderness</i>, on the eastern side of the Jordan.—<span class=\"citation\">Tosef. Men. IX, 13</span> <span dir=\"rtl\">כבשים ממ׳</span>, read: <span dir=\"rtl\">ממִדְבַּר חברון</span> from the pasture-ground of Hebron; v. <span class=\"citation\">Men. 87ᵃ</span>; <span class=\"citation\">Sot. 34ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"מִדַּבְּרוֹת\">מִדְבָּרוֹת</a>. <span class=\"citation\">Ber. IX, 2</span>. <span class=\"citation\">Ib. 54ᵇ</span> <span dir=\"rtl\">הולכי מ׳</span> those travelling in the deserts; a. e.</div>","alt":[]},"17218":{"h":"מַדְבְּרָא","r":"M00242","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. Ex. III, 1</span>; a. fr.—<span class=\"citation\">B. Bath. 73ᵇ</span>; <span class=\"citation\">74ᵇ</span> <span dir=\"rtl\">אזלינן במ׳</span> we were travelling in the desert; a. fr.—<span class=\"citation\">Cant. R. to IV, 4</span> (ref. to <span dir=\"rtl\">מדברך</span>, <span class=\"citation\">ib. 3</span>) <span dir=\"rtl\">מִדְבָּרֵךְ יאי מַדְבַּרְתֵּךְ יאיא</span> thy <i>midbar</i> is beautiful, this means thy waste (the ruined Temple) is beautiful, v. preceding.; [Comment.: <i>thy speech</i>.]—Pl. <span dir=\"rtl\">מַדְבְּרַיָּא</span>, f. <a href=\"#\" data-headword=\"מַדְבְּרָן\">מַדְבְּרָן</a>. <span class=\"citation\">Targ. Ps. LXXV, 7</span>. <span class=\"citation\">Targ. Is. LI, 3</span>. <span class=\"citation\">Targ. Cant. II, 14</span>.</div>","alt":["מַדְבַּרְתָּא"]},"17219":{"h":"מְדַבְּרָא","r":"M00243","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּבַר\">דְּבַר</a>) <i>leader</i>. <span class=\"citation\">Targ. Prov. XI, 14</span> (Levita <a href=\"#\" data-headword=\"מְדַבְּרָנָא\">מְרַבְּרָנָא</a>; h. text <span dir=\"rtl\">תחבלות</span>, cmp. <a href=\"#\" data-headword=\"מְדַבְּרָנוּתָא\">מְדַבְּרָנוּתָא</a>).—Targ. II Esth. IV, 1 Var. ed. Lag. (ed. <a href=\"#\" data-headword=\"מְדַבְּרָנָא\">מדברנא</a>).—Pl. constr. <a href=\"#\" data-headword=\"מִדְבָּרִי\">מְדַבְּרֵי</a>. <span class=\"citation\">Targ. Cant. I, 8</span>.</div>","alt":[]},"17220":{"h":"מִדַּבְּרוֹת","r":"M00244","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">דבר</span>) </div><div class=\"sense\"><b>1)</b> <i>conduct, manners</i>. <span class=\"citation\">Koh. R. to III, 18</span> (ref. to <span dir=\"rtl\">דברת</span>, ib.) <span dir=\"rtl\">מ׳ שהצדיקים מִדַּבְּרִים</span> the way the righteous conduct themselves.</div><div class=\"sense\"><b>—2)</b>  (b. h.) <i>conversation, talk</i>. Ib. <span dir=\"rtl\">מ׳ שהרשעים מדברים בהם</span> the conversations which the wicked hold. <span class=\"citation\">Snh. 67ᵇ</span>, a. fr. <span dir=\"rtl\">כלה מִדַּבְּרוֹתֶיךָ</span>, v. <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>; <span class=\"citation\">ib. 38ᵇ</span>, <span dir=\"rtl\">כלך למדברותיך אצל וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">כלך אצל</span>); <span class=\"citation\">Ḥag. 14ᵃ</span> <span dir=\"rtl\">כלך מדברותיך אצל</span> = <span dir=\"rtl\">כלה מד׳ ולך וכ׳</span>, v. <a href=\"#\" data-headword=\"כַּלֵּךְ\">כַּלֵּךְ</a>.</div>","alt":[]},"17221":{"h":"מִדְבָּרִי","r":"M00245","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מִדְבָּר\">מִדְבָּר</a>) <i>belonging to the desert</i>. <span class=\"citation\">Erub. 83ᵃ</span>, a. e. <span dir=\"rtl\">סאה מ׳</span> the S’ah of the Israelites in the desert, containing six desert Kab, or five Jerusalem Kab.—Pl. <span dir=\"rtl\">מִדְבָּרִיִּים</span>, <span dir=\"rtl\">מִדְבָּרִיִּין</span>; <span dir=\"rtl\">מִדְבָּרִיּוֹת</span>. <span class=\"citation\">Men. VII, 1</span>, a. e., v. <a href=\"#\" data-headword=\"סְאָה\">סְאָה</a>.—Esp. <span dir=\"rtl\">מדבריות</span> <i>pasture-animals</i>. <span class=\"citation\">Bets. V, 7</span> (<span class=\"citation\">40ᵃ</span>), opp. <a href=\"#\" data-headword=\"בַּיָיתוֹת\">בַּיָּיתוֹת</a>; Tosef. ib. IV, 11.</div>","alt":["מִדְבָּרִית"]},"17222":{"h":"מַדְבְּרָן","r":"M00246","html":"<div class=\"sense\"> f. pl., v. <a href=\"#\" data-headword=\"מַדְבְּרָא\">מַדְבְּרָא</a></div>","alt":[]},"17223":{"h":"מְדַבְּרָנָא","r":"M00247","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מְדַבְּרָא\">מְדַבְּרָא</a>, <i>leader</i>. Targ. II Esth. IV, 1. <span class=\"citation\">Targ. Prov. XI, 14</span>, v. <a href=\"#\" data-headword=\"מְדַבְּרָא\">מְדַבְּרָא</a>.—<span class=\"citation\">Snh. 14ᵃ</span> <span dir=\"rtl\">מ׳ דאומתיה</span> (Ms. K. <a href=\"#\" data-headword=\"דַּבְּרָן\">דַּבְּרָנָא</a>, v. <a href=\"#\" data-headword=\"דַּבְּרָן\">דַּבְּרָן</a>) leader of his people; <span class=\"citation\">Keth. 17ᵃ</span></div>","alt":[]},"17224":{"h":"מְדַבְּרָנוּתָא","r":"M00248","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְדַבְּרָנָא\">preced.</a>) <i>command, strategy; scheme</i>(b. h. . <span class=\"citation\">Targ. Prov. I, 5</span>; <span class=\"citation\">XX, 18</span>; <span class=\"citation\">XXIV, 6</span>. <span class=\"citation\">Ib. XII, 5</span>.</div>","alt":["מַדְבְּרָ׳"]},"17225":{"h":"מַדְבַּרְתָּא","r":"M00249","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַדְבְּרָא\">מַדְבְּרָא</a></div>","alt":[]},"17226":{"h":"מַדְבַשְׁתָּא","r":"M00250","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"דְּבֶשְׁתָּא\">דְּבֶשְׁתָּא</a></div>","alt":[]},"17227":{"h":"מָדַד","r":"M00251","html":"<div class=\"sense\"> (b. h.) [<i>to stretch</i>,] <i>to measure</i>. <span class=\"citation\">Sabb. 149ᵇ</span> sq. (play on <span dir=\"rtl\">מ̇ד̇ה̇ב̇ה</span>, <span class=\"citation\">Is. XIV, 4</span>) the nation that said <span dir=\"rtl\">מְ֗ד̇וד̇</span>, <span dir=\"rtl\">וה̇ב̇א</span> measure (the area of thy land) and bring (tribute); <span class=\"citation\">Lev. R. s. 15</span>, end (Ar.: <span dir=\"rtl\">מוֹד והָבָה</span> measure and give). <span class=\"citation\">Erub. V, 4</span> אין מוֹדְדִין וכ׳ Sabbath distances must be measured only with a rope of &amp;c. Ib. 5 <span dir=\"rtl\">אין מודדין אלא מן המומחה</span> the measuring must be done only by the best experts. <span class=\"citation\">Y. Succ. I, 51ᵈ</span> <span dir=\"rtl\">אם יָמוֹד מן וכ׳</span> if he measures from &amp;c. <span class=\"citation\">Maas. Sh. V, 9</span> <span dir=\"rtl\">עשור שאני עתיד לָמוֹֹד</span> one tenth (as tithe) which I shall measure off (when I come home); a. fr.—<span class=\"citation\">Sot. I, 7</span> <span dir=\"rtl\">במדה שאדם מוֹדֵד בה מוֹדְדִין לו</span> the measure with which man measures will be measured out to him, i.e. as man deals, he will be dealt with, v. <a href=\"#\" data-headword=\"אַכְרַעְתָּא\">אַכְרַעְתָּא</a>; <span class=\"citation\">Tosef. ib. III, 1</span> <span dir=\"rtl\">מ׳ בסאה</span> he measured by the S’ah (committed great wrong). <span class=\"citation\">Ber. IX, 5</span>, v. next w.—<span class=\"citation\">Ib. 30ᵇ</span> <span dir=\"rtl\">לעולם יָמוֹד אדם וכ׳</span> man must always measure himself (examine the disposition of his mind; cmp. <a href=\"#\" data-headword=\"אָמַד\">אָמַד</a></div><div class=\"sense\"><b>Nif. נִמְדַּד</b> <div class=\"sense\"><i>to be measured</i>. <span class=\"citation\">B. Bath. VII, 1</span> <span dir=\"rtl\">אינן נִמְדָּדִין עמה</span> are not included in the measure. <span class=\"citation\">Arakh. VII, 1</span> <span dir=\"rtl\">נִמְדָּדִים עמה</span> are included &amp;c.; a. fr. </div></div><div class=\"sense\"><b>Pi. מִדֵּד</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מַדְבַשְׁתָּא\">same</a>, <i>to stretch</i>. <span class=\"citation\">Gen. R. s. 3</span>; <span class=\"citation\">Midr. Till. to Ps. XXIV</span>, a. e. <span dir=\"rtl\">מְמַדֵּד</span>, v. <a href=\"#\" data-headword=\"מָתַח\">מָתַח</a>.—[<span class=\"citation\">Cant. R. to VIII, 11</span> <span dir=\"rtl\">ממדדין</span>, v. <a href=\"#\" data-headword=\"דדי\">דָּדָה</a>.]</div></div>","alt":[]},"17228":{"h":"מִדָּה","r":"M00252","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מָדַד\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>dimension, measure, proportion</i>. <span class=\"citation\">Sabb. 150ᵃ</span> (play on <span dir=\"rtl\">מ̇ד̇ה̇ב̇ה</span>, v. <a href=\"#\" data-headword=\"מָדַד\">preced.</a>) <span dir=\"rtl\">מ̇אד̇ מ̇אד̇ ה̇ב̇א בלא מ̇&#x27;</span> bring much, very much, without measure. <span class=\"citation\">Peah VIII, 6</span> <span dir=\"rtl\">מ׳ זו</span> this proportion. <span class=\"citation\">Gen. R. s. 64</span>; Esth. R. introd. (ref. to <a href=\"#\" data-headword=\"מִנְדָּה\">מנדה</a>, <span class=\"citation\">Ezra IV, 13</span>) <span dir=\"rtl\">זו מִדַּת הארץ</span> that is the tax from the land as measured, i.e. the (Roman) land-tax. <span class=\"citation\">B. Bath. VII, 3</span> מ׳ בחבל וכ׳ I sell thee exact land-measure by the rope. <span class=\"citation\">Ib. 128ᵃ</span> <span dir=\"rtl\">מִדַּת ארכו</span> the length-measure of the cloak. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מדת משקלותיו</span> the measure of its (the gold-bar’s) weights, i.e. an estimate as to how many coins of a certain weight can be obtained from it. <span class=\"citation\">Ḥag. 12ᵃ</span> <span dir=\"rtl\">מדת יום ומ׳ לילה</span> the combined length of day and night. <span class=\"citation\">Yeb. 76ᵇ</span> (ref. to <span class=\"citation\">I Sam. XVII, 38</span>) <span dir=\"rtl\">מַדָּיו כמִדָּתוֹ</span> his (Saul’s) garments such as fitted his stature. <span class=\"citation\">Mikv. X, 5</span>; <span class=\"citation\">Ḥull. 73ᵃ</span> <span dir=\"rtl\">עד מקום</span> (<a href=\"#\" data-headword=\"ה\">ה</a>)<a href=\"#\" data-headword=\"מ׳\">מ׳</a> as far as the designed length of the handle (excluding the portion which it is intended to cut off).—<span class=\"citation\">Kidd. 42ᵇ</span>; <span class=\"citation\">B. Mets. 56ᵇ</span>, a. e. <span dir=\"rtl\">דבר שבמ׳ ושבמשקל וכ׳</span> objects which are sold by measure, by weight or by the piece. <span class=\"citation\">B. Bath. 89ᵇ</span> <span dir=\"rtl\">לעולם … מ׳ חסירה וכ׳</span> one must never keep in one’s house too small or too large a measure (smaller or larger than the legal size); a. fr.—Pl. <span dir=\"rtl\">מִדּוֹת</span>, <span dir=\"rtl\">מִידּוֹת</span>. <span class=\"citation\">Ib. 88ᵇ</span> <span dir=\"rtl\">עונשן של מ׳</span> the divine punishment for fraudulent measures. <span class=\"citation\">Tosef. B. Mets. VI, 14</span> <span dir=\"rtl\">לא היו ממונין … אלא על המ׳</span> they (the <i>agoranomoi</i> in Jerusalem) were appointed not for the regulation of market prices but for the superintendence of the measures; <span class=\"citation\">B. Bath. 89ᵃ</span>, v. <a href=\"#\" data-headword=\"אֲגַרְדְּמִיס\">אֲגַרְדְּמִיס</a>; a. fr.—<span class=\"citation\">Men. 18ᵃ</span> <span dir=\"rtl\">למצות מִידּוֹתַי</span>, v. <a href=\"#\" data-headword=\"מָצָה\">מָצָה</a>.—Whence: <i>Middoth</i> (measurements of the Temple), name of a treatise of the Mishnah, of the order of Kodashim.</div><div class=\"sense\"><b>—2)</b> <i>dealing; reward</i> or <i>punishment; dispensation</i>.—מ׳ כנגד מ׳ <i>retaliation, adequate punishment</i> or <i>reward</i>. <span class=\"citation\">Sot. I, 7</span>, v. <a href=\"#\" data-headword=\"מָדַד\">preced.</a> <span class=\"citation\">Ib. 9ᵃ</span> <span dir=\"rtl\">לכמ׳</span> the verse is to intimate the God dispenses adequate punishments. <span class=\"citation\">Ib. 8ᵇ</span> (ref. to <span class=\"citation\">ib. I, 7</span>) <span dir=\"rtl\">אע&quot;ג דמ׳ בטילה במ׳ לא בטיל</span> although retribution (by the Jewish court) has ceased, the adequate divine punishment has not ceased. Lam. R. introd. (R. Alex. 2) (expl. <span dir=\"rtl\">יען וביען</span>, <span class=\"citation\">Lev. XXVI, 43</span>) <span dir=\"rtl\">מ׳ כנגד מ׳</span> punishment corresponding to deed. <span class=\"citation\">Ned. 32ᵃ</span>. <span class=\"citation\">Snh. 90ᵃ</span> <span dir=\"rtl\">כל מִידּוֹתָיו של הקב&quot;ה מ׳ כנגד מ׳</span> all retributions of the Lord are in correspondence with man’s doings. <span class=\"citation\">Ber. 48ᵇ</span> ‘whatever the Lord thy God has given thee’ <span dir=\"rtl\">דיינך בכל … בין מ׳ טובה ובין מִדַּת פורענות</span> (not <a href=\"#\" data-headword=\"מִדָּה\">מדה</a>) he is thy judge in whatever sentence he decrees upon thee, whether it be a good or an evil dispensation. <span class=\"citation\">Ib. IX, 5</span>, v. <a href=\"#\" data-headword=\"מְאֹד\">מְאֹד</a>. <span class=\"citation\">Sabb. 97ᵃ</span>. <span class=\"citation\">Ib. 151ᵇ</span> <span dir=\"rtl\">לעולם … על מ׳ זו</span> at all times let one pray to be spared this fate (poverty); a. fr.—<i>Pl.</i> as ab. <span class=\"citation\">Snh. 90ᵃ</span>, v. supra. <span class=\"citation\">Yoma 87ᵇ</span> <span dir=\"rtl\">המעביר על מִדּוֹתָיו וכ׳</span> he who passes over his retaliations (who forbears to retaliate), his failings will be passed over (be forgiven); <span class=\"citation\">Meg. 28ᵃ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא עמדתי על מִידּוֹתַי</span> I never insisted on retaliation; <span class=\"citation\">Kidd. 71ᵃ</span> <span dir=\"rtl\">ואינו מעמד על מדותיו</span> (Rashi: <a href=\"#\" data-headword=\"מַעֲמִיד\">מעמיד</a>); a. fr.—3) <i>manner, ways, character, nature, condition</i>. <span class=\"citation\">Ber. 40ᵃ</span> <span dir=\"rtl\">לא כמדת הקב&quot;ה וכ׳</span> the nature of divine (intellectual) affairs is not like the nature of human (material) affairs. <span class=\"citation\">Ib. 11ᵇ</span> <span dir=\"rtl\">להזכיר מדת יום וכ׳</span> to mention the nature of the day (light) at night. Tanḥ. Balak 3 <span dir=\"rtl\">מה מִדָּתוֹ</span> what is the nature of his power. <span class=\"citation\">B. Mets. 33ᵃ</span> <span dir=\"rtl\">מ׳ ואינה מ׳</span> it is a (meritorious) way (of studying) and is not, i.e. you might to better; <span class=\"citation\">Y. Hor. III, 48ᶜ</span> top <span dir=\"rtl\">מ׳ שאינה מ׳</span>; a. fr.—Pl. as ab. <span class=\"citation\">Ab. V, 10</span> <span dir=\"rtl\">ארבע מ׳ באדם</span> there are four different dispositions of men (as to treating one’s fellowman); <span class=\"citation\">ib. 11</span> <span dir=\"rtl\">ארבע מ׳ בדעות</span> four characters (temperaments); <span class=\"citation\">ib. 12</span> <span dir=\"rtl\">ארבע מ׳ בתלמידים</span> four natures of students (with regard to receptive and retentive faculties). <span class=\"citation\">Y. Snh. XI, 30ᵃ</span> bot. <span dir=\"rtl\">כל שבע מ׳ וכ׳</span> all the seven characteristic features of righteous men which the scholars have defined have been realized in Rabbi. <span class=\"citation\">Ned. 20ᵇ</span> <span dir=\"rtl\">בני תשע מ׳</span> children conceived under nine (abnormal mental) conditions. <span class=\"citation\">R. Hash. 17ᵇ</span>, a. fr. <span dir=\"rtl\">שלש עשרה מ׳</span> the thirteen divine attributes (<span class=\"citation\">Ex. XXXIV, 6</span>, sq.). <span class=\"citation\">Ned. 32ᵃ</span>, v. <a href=\"#\" data-headword=\"פָּרַז\">פָּרַז</a>; a. fr.—<span dir=\"rtl\">מדת הדין</span> a) <i>justice</i>. <span class=\"citation\">Tosef. Yeb. IX, 3</span>. a. e., v. <a href=\"#\" data-headword=\"לְקָא\">לָקָה</a>.—Esp. <i>the divine attribute of justice</i>, opp. <span dir=\"rtl\">מ׳ הרחמים</span>, v. <a href=\"#\" data-headword=\"דִּין II\"><span dir=\"rtl\">דִּין</span> II</a>.—b) <i>common sense, logical argument</i>. <span class=\"citation\">Yoma 43ᵇ</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"כָּךְ\">כך</a> (<span dir=\"rtl\">היא</span>) <span dir=\"rtl\">מ׳ הדין נותנת</span></span> common sense dictates this; <span class=\"citation\">Shebu. 14ᵃ</span>. <span class=\"citation\">Y. Maas. Sh. II, 53ᶜ</span> top <span dir=\"rtl\"><span dir=\"rtl\">תחומין עשו</span> (<span dir=\"rtl\">כמ׳</span>) <span dir=\"rtl\">למ׳ הדין</span></span> they regulated the laws of Sabbath limits according to common sense (not by textual interpretation).—c) <i>decision in money matters, civil law</i> (contrad. to ritual law). <span class=\"citation\">Y. Gitt. V, 46ᶜ</span> bot. <span dir=\"rtl\">אף למ׳ הדין הכן</span> the same principle holds good for civil law (collection of claims, v. <a href=\"#\" data-headword=\"כַּפְרָנוּת\">כַּפְרָנוּת</a>); <span class=\"citation\">Y. Shebi. X, 39ᶜ</span> bot. <span class=\"citation\">Ib.</span> (last line) <span dir=\"rtl\">ולמידין מ׳ הדין וכ׳</span> do we apply the rules of Prosbol (v. <a href=\"#\" data-headword=\"פְּרוֹזְבֹּול\">פְּרוֹזְבּוּל</a>) to ordinary claims? <span class=\"citation\">Y. B. Kam. V, beg. 4ᵈ</span> <span dir=\"rtl\">לא הילכו במ׳ הדין אחר הרוב</span> (strike out <span dir=\"rtl\">בממון</span>) in civil law we are not guided by probabilities (v. <a href=\"#\" data-headword=\"דּוֹב\">דוֹב</a>; cmp. Bab. <span class=\"citation\">B. Kam. 27ᵇ</span>). Y. Ber. II, 5ᵃ bot. <span dir=\"rtl\">ולמ׳ הד׳</span> but civil law (questions of possession).</div><div class=\"sense\"><b>—4)</b> <i>principle, standard, consistency</i>. <span class=\"citation\">Men. III, 4</span> <span dir=\"rtl\">כמדת ר׳ וכ׳</span> following the principle of R. &amp;c.; <span class=\"citation\">Pes. 77ᵇ</span>; Y. ib. VII, 34ᶜ top. <span class=\"citation\">Shek. IV, 6</span> <span dir=\"rtl\">אינה היא המ׳</span> (comment. <span dir=\"rtl\">אינה מן המ׳</span>) this is not consistent (with a previous rule). <span class=\"citation\">Ib. 7</span> <span dir=\"rtl\">השוה את מִדָּתוֹ</span> (Y. ed. <span dir=\"rtl\">מִדּוֹתָיו</span>) he makes his standards even (is consistent). <span class=\"citation\">Pes. I, 7</span> <span dir=\"rtl\">אינה היא המ׳</span> this is not the right argument. <span class=\"citation\">Ib. 15ᵇ</span> <span dir=\"rtl\">אמאי אינה היא המ׳ מ׳ ומ׳ היא</span> why do you say, it is no argument? it is surely a correct argument. <span class=\"citation\">Y. Ḥag. III, 77ᵈ</span> ‘Menahem went out’ means <span dir=\"rtl\">ממ׳ למ׳ יצא</span> he went over from one principle to another (joined the opposition; Bab. <span class=\"citation\">ib. 16ᵇ</span> <span dir=\"rtl\">יצא לתרבות רעה</span>).—Esp. <span dir=\"rtl\">מִדּוֹת</span> <i>rules of interpretation</i>. Sifra introd., ch. I, end <span dir=\"rtl\">הלל … שבע מ׳ וכ׳</span> Hillel the Elder explained seven rules &amp;c.; <span class=\"citation\">Ab. d’R. N. ch. XXXVII</span>; <span class=\"citation\">Tosef. Snh. VII, 11</span>. Sifra introd., beg. (R. Yishm. said) <span dir=\"rtl\">בשלש עשרה מ׳ וכ׳</span> the Torah is interpreted by means of thirteen rules. [Appendix to treat. B’rakhoth. <span dir=\"rtl\">ל&quot;ב מ׳ של ר׳ יוסו וכ׳</span> the thirty two rules of R. José the Galilean.]—<span class=\"citation\">Lev. R. s. 3</span>, beg. <span dir=\"rtl\">הלכות ומ׳</span> decisions and interpretations (by which the decisions were reached), v. <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילְתָּא</a>.—<span class=\"citation\">Gitt. 67ᵃ</span> <span dir=\"rtl\">מִידּוֹתַי תרומה מתרומות מִידּוֹתָיו וכ׳</span> my rules of interpretation are the selection from selections of rules by R. Akiba.—<span class=\"citation\">Ber. 33ᵇ</span> <span dir=\"rtl\">שעושה מדותיו של הקב&quot;ה רחמים וכ׳</span> he makes compassion the standard (or reason) of the divine laws, while they are decrees (the reasons for which it behooves not man to discuss); Y. ib. V, 9ᶜ <span dir=\"rtl\">כקורא תיגר על מ׳ וכ׳</span> because it sounds as if he were finding fault with the ways of the Lord (as if the Lord were partial); <span dir=\"rtl\">כנותן קיצבה למ׳ וכ׳</span> as though he were setting limits to the attributes of the Lord.</div>","alt":["מִידָּה"]},"17229":{"h":"מִדָּה ²","r":"M00253","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מִדָּה\">same</a>. <span class=\"citation\">Targ. Ps. LVI, 5</span>; <span class=\"citation\">11</span> <span dir=\"rtl\">מידַּת דינא</span>, <span dir=\"rtl\">מ׳ רחמין</span>, v. <a href=\"#\" data-headword=\"מִדָּה\">preced.</a> <span class=\"citation\">Targ. Lam. I, 1</span>; a. e.—<span class=\"citation\">Snh. 38ᵇ</span> <span dir=\"rtl\">אידי ואידי חדא מ׳ הוא</span> the two dimensions are alike.—[</div><div class=\"sense\"><b>2)</b> <i>tribute.</i> <span class=\"citation\">Ezra IV, 20</span>, a. e., v. <a href=\"#\" data-headword=\"מִנְדָּה\">מִנְדָּה</a>.]</div>","alt":["מִידָּה"]},"17230":{"h":"מִדְּהָא","r":"M00254","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִדְּ־\">מִדְּ־</a></div>","alt":[]},"17231":{"h":"מדהא","r":"M00255","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Esth. I, 2</span> <span dir=\"rtl\">ית מ׳ דבבל</span> ed. Lag. (ed. Amst. <span dir=\"rtl\">מדאה ית דבבל</span>) read <span dir=\"rtl\">מָדָאָה ית מְדִינְתָּא דבבל</span>.</div>","alt":[]},"17232":{"h":"מַדְוָא","r":"M00256","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דָּוֵי\">דְּוֵי</a>) <i>affliction</i>. <span class=\"citation\">Targ. Esth. VI, 1</span> <span dir=\"rtl\">מַדְוָנָא</span> our affliction.</div>","alt":[]},"17233":{"h":"מְדַוַּאר","r":"M00257","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּר I\"><span dir=\"rtl\">דּוּר</span> I</a> ch.</div>","alt":[]},"17234":{"h":"מְדוּבְלָל","r":"M00258","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּבְלוּל\">דַּבְלוּל</a></div>","alt":[]},"17235":{"h":"מדוברי","r":"M00259","html":"<div class=\"sense\">, <span class=\"citation\">M. Kat. 12ᵇ</span> some ed., v. <a href=\"#\" data-headword=\"*מַדְבּוּרָא\">מַדְבּוּרָא</a> a. <a href=\"#\" data-headword=\"*מְדוּכְרָא\"><a href=\"#\" data-headword=\"*מְדוּכְרָא\">מְדוּכְרָא</a>.</a></div>","alt":[]},"17236":{"h":"מַדְוֶה","r":"M00260","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>flux</i>. <span class=\"citation\">Macc. 14ᵇ</span>; <span class=\"citation\">Nidd. 41ᵇ</span> <span dir=\"rtl\">עד שיצא מ׳ וכ׳</span> until the flux is discharged through &amp;c. <span class=\"citation\">Ib. 54ᵇ</span> <span dir=\"rtl\">מַדְוָהּ כמותה</span> what flows from her is subject to the same laws as her body. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מַדְוָהּ מטמא</span> (not <span dir=\"rtl\">מטמאה</span>).</div>","alt":[]},"17237":{"h":"מדוורתא","r":"M00261","html":"<div class=\"sense\">, <span class=\"citation\">Yoma 23ᵃ</span> Ar. s. v. <span dir=\"rtl\">דר</span><sup>3</sup>, v. <a href=\"#\" data-headword=\"מַדְרָא\">מַדְרָא</a>.</div>","alt":[]},"17238":{"h":"מדוי","r":"M00262","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 91</span> <span dir=\"rtl\">במ׳ דמכסא</span> (ed. Wil. <span dir=\"rtl\">במדיו</span>), v. <a href=\"#\" data-headword=\"מִידֵי\">מִידֵּי</a>.—Y. Kidd. IV, 65ᵈ top <span dir=\"rtl\">מדוי חולה</span>, read: <a href=\"#\" data-headword=\"מָדַיי\">מָדַיי</a>.</div>","alt":[]},"17239":{"h":"מַדְוֵי","r":"M00263","html":"<div class=\"sense\">, v. <span dir=\"rtl\">מַרְוָא I</span></div>","alt":["מַדְוְיָא","מ׳ חיוורא"]},"17240":{"h":"מָדוֹךְ","r":"M00264","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּךְ\">דּוּךְ</a>) <i>pestle</i>. <span class=\"citation\">Bets. I, 7</span>; <span class=\"citation\">Tosef. ib. I, 18</span>. <span class=\"citation\">Ib. 17</span>; a. e.</div>","alt":[]},"17241":{"h":"מְדוֹכָא","r":"M00265","html":"<div class=\"sense\"> m. ch. = <a href=\"#\" data-headword=\"מְדוֹכָה\">next w.</a> <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳<sup>3</sup>) <span dir=\"rtl\">הד מ׳ מטלקא</span> a wooden mortar that had been thrown away (broken).</div>","alt":[]},"17242":{"h":"מְדוֹכָה","r":"M00266","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>mortar</i>. <span class=\"citation\">Tosef. Bets. I, 17</span>. <span class=\"citation\">Yoma 75ᵃ</span>, v. <a href=\"#\" data-headword=\"דּוּךְ I\"><span dir=\"rtl\">דּוּךְ</span> I</a>. <span class=\"citation\">Kel. XXIII, 2</span> <span dir=\"rtl\">מ׳ המדית</span> a Median mortar (on the protruding handles of which the pounders ride when at work); [Maim., (ed. Dehrenb. <a href=\"#\" data-headword=\"מדיבה\">מדיבה</a>, corr. acc.): a sort of <i>saddle</i>, v. infra]. <span class=\"citation\">Sabb. 81ᵃ</span> <span dir=\"rtl\">כהכרע מ׳ קטנה כ׳</span> (v. Tosaf. a. l.) as large as the leg of a small spice mortar; Y. ib. VIII, end, 11ᶜ</div><div class=\"sense\"><b>—2)</b> <i>a mortar-shaped seat</i>. <span class=\"citation\">Yeb. 16ᵃ</span>; Y. ib. 3ᵃ bot. <span class=\"citation\">Kel. XXIII, 2</span>, v. supra.</div>","alt":[]},"17243":{"h":"מְדוֹכְיָא","r":"M00267","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"מָדוֹךְ\">מָדוֹךְ</a>. <span class=\"citation\">Sot. 22ᵃ</span> <span dir=\"rtl\">פרוש מ׳ … דמשפע כי מ׳</span> (he is called) the ‘pestle-Pharisee’ because he is bent sideways like a pestle (in the mortar).</div>","alt":[]},"17244":{"h":"*מְדוּכְרָא","r":"M00268","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּכַר I\">דְּכַר</a>) <i>marker; mark</i>.—Pl. <span dir=\"rtl\">מְדוּכְרֵי</span>, v. <a href=\"#\" data-headword=\"*מַדְבּוּרָא\">מַדְבּוּרָא</a>.</div>","alt":[]},"17245":{"h":"מְדוּכְתָּא","r":"M00269","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"מְדוֹכָה\">מְדוֹכָה</a>. <span class=\"citation\">Targ. O. Num. XI, 8</span> (Targ. Y. II <a href=\"#\" data-headword=\"מְזוֹכִיתָא\">מְזוֹכָתָא</a>).—Y. Bets. I, 60ᵈ top. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> bot. <a href=\"#\" data-headword=\"מְדוּכְתָּא\">מְדוּכְתָּח</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מדוכתיה</span> (corr. acc.).—[<span class=\"citation\">Lam. R. to I, 3</span>; <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">כנישתא מ׳</span>, v. <a href=\"#\" data-headword=\"מָרָדְתָּא\">מָרָדְתָּא</a>.]</div>","alt":[]},"17246":{"h":"מִדוֹל","r":"M00270","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (apocopate infin. of <a href=\"#\" data-headword=\"דְּלֵי\">דְּלֵי</a>) <i>the act of drawing water</i>. <span class=\"citation\">Targ. Y. Ex. II, 19</span>, v. <a href=\"#\" data-headword=\"דְּלִיָּה\">דְּלִיָּה</a>.</div>","alt":[]},"17247":{"h":"מדוני","r":"M00271","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵרוֹנִי\">מֵרוֹנִי</a></div>","alt":[]},"17248":{"h":"מְדוּקְרָן","r":"M00272","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹקְרָן\">דּוֹקְרָן</a></div>","alt":[]},"17249":{"h":"מָדוֹר","r":"M00273","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דּוּר I) </div><div class=\"sense\"><b>1)</b> <i>dwelling</i>.—<span dir=\"rtl\">מְ׳ עמים</span> (<a href=\"#\" data-headword=\"עכ\">עכ&quot;ום</a>, <span dir=\"rtl\">מ׳ כותים</span>) <i>a dwelling that has been occupied by gentiles</i> (in Palestine, which is unclean until examined and found free of corpses). <span class=\"citation\">Tosef. Ohol. XVIII, 10</span> <span dir=\"rtl\">כיצר בודקין מ׳ הע׳</span> how is a vacated gentile dwelling examined?—<span class=\"citation\">Ib. 6</span> כותיים עושים מ׳ הע׳ Samaritan inmates make a dwelling subject to the law of <i>m’dor ha‘ammim.</i> Ohol. XVIII, 9; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>story, compartment</i>. <span class=\"citation\">R. Hash. 24ᵇ</span> <span dir=\"rtl\">מ׳ העליון</span> the upper story of the heavens; <span dir=\"rtl\">מ׳ התחתון</span> the lower story (sphere of the heavenly bodies). <span class=\"citation\">Nidd. 31ᵃ</span> <span dir=\"rtl\">מ׳ התחתון</span> the lowest compartment of the womb. <span class=\"citation\">Pirké d’R. El. ch. XXIII</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מְכוֹרוֹת\">מְדוֹרוֹת</a>, <span dir=\"rtl\">מְדוֹרִין</span>. Ohol. XVIII, 7 <span dir=\"rtl\">מ׳ הכותים</span>; <span class=\"citation\">Pes. 9ᵃ</span> <span dir=\"rtl\">מ׳ הכושים</span> (v. <a href=\"#\" data-headword=\"כּוּשִׁי\">כּוּשִׁי</a>); a. e.—<span class=\"citation\">Tosef. Mikv. VI, 1</span> <span dir=\"rtl\">מְדֹרוֹתֶיהָ</span> (R. S. to <span class=\"citation\">Mikv. VIII, 1</span> <span dir=\"rtl\">מְדוֹרֶיהָ</span>) the dwellings therein.—[<span class=\"citation\">Tosef. Maas. Sh. I, 5</span> <span dir=\"rtl\">מטבע מדור</span>, v. <a href=\"#\" data-headword=\"מָרוֹד\">מָרוֹד</a>.]—[<span class=\"citation\">Midr. Prov. ch. VI</span>; <span class=\"citation\">Yalk. ib. 939</span> <span dir=\"rtl\">מדורי</span>, v. <a href=\"#\" data-headword=\"מְדוּרָה\">מְדוּרָה</a>.]</div>","alt":[]},"17250":{"h":"מָדוֹר ²","r":"M00274","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. LXXVI, 3</span>. <span class=\"citation\">Targ. Gen. XXX, 20</span>; a. fr.—Pl. <span dir=\"rtl\">מְדוֹרִין</span>, <span dir=\"rtl\">מְדוֹרַיָּא</span>. <span class=\"citation\">Ib. VI, 16</span> (compartments of the ark); <span class=\"citation\">Targ. O. ib. 14</span>. <span class=\"citation\">Targ. I Chr. IV, 41</span>. <span class=\"citation\">Targ. Job XXXVII, 8</span>; a. e.—<span class=\"citation\">Ib. XXXVIII, 40</span> <a href=\"#\" data-headword=\"מְדוּרְתָּא\">מְדוֹרָתָא</a>.—[<span dir=\"rtl\">מדורי</span>, <span class=\"citation\">Bekh. 44ᵇ</span>, v. <a href=\"#\" data-headword=\"מִדְרָא\">מִדְרָא</a>.]</div>","alt":["מְדוֹרָא"]},"17251":{"h":"מְדוּרָא","r":"M00275","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"מְדוּרָה\">next w.</a> <span class=\"citation\">Targ. Is. XXX, 33</span> <span dir=\"rtl\">מ׳ דאשתא</span> (ed. Lag. <span dir=\"rtl\">מדורה אישתא</span>, corr. acc.). V. <a href=\"#\" data-headword=\"מְדוּרְתָּא\">מְדוּרְתָּא</a></div>","alt":[]},"17252":{"h":"מְדוּרָה","r":"M00276","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>row, pile of wood, fire</i>. <span class=\"citation\">Tam. I, 1</span> <span dir=\"rtl\">ומ׳ היתה שם</span> and there was an open fire place there. <span class=\"citation\">Bets. II, 5</span>; a. e.—Pl. constr. <span dir=\"rtl\">מְדוּרֵי</span>. <span class=\"citation\">Midr. Prov. ch. VI</span>; <span class=\"citation\">Yalk. ib. 939</span> <span dir=\"rtl\">י&quot;ד מ׳ גיהנם</span> the fourteen pyres of Gehenna.</div>","alt":[]},"17253":{"h":"מְדוּרְתָּא","r":"M00277","html":"<div class=\"sense\"> <span class=\"citation\">Bets. 32ᵇ</span>; <span class=\"citation\">Erub. 101ᵃ</span></div>","alt":[]},"17254":{"h":"*מְדוּשָּׁא","r":"M00278","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְדוּשָּׁה\">next w.</a>) <i>treading</i>; (Arab.) <i>polishing</i>.—<span dir=\"rtl\">חומרתא דמ׳</span>. <span class=\"citation\">Erub. 69ᵃ</span> (Ms. O. <span dir=\"rtl\">מר׳</span>); <span class=\"citation\">M. Kat. 12ᵇ</span>, v. <a href=\"#\" data-headword=\"חוּמַרְתָּא\">חוּמַרְתָּא</a>.</div>","alt":[]},"17255":{"h":"מְדוּשָּׁה","r":"M00279","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>that which is trodden</i> or <i>threshed</i>. <span class=\"citation\">Midr. Till. to Ps. CXIX, 25</span>.—Pl. <span dir=\"rtl\">מְדוּשִּׁים</span>. Ib. (<span class=\"citation\">Gen. R. s. 69</span> <a href=\"#\" data-headword=\"דַּיִשׁ\">דַּיִּשׁ</a>, q. v.).</div>","alt":[]},"17256":{"h":"מָדַי","r":"M00280","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Media.</i> <span class=\"citation\">Shek. III, 4</span> <span dir=\"rtl\">לשום מ׳</span> on behalf of the Median Jews. <span class=\"citation\">B. Kam. IX, 5</span> <span dir=\"rtl\"><span dir=\"rtl\">יוליכנו אחריו</span> (<a href=\"#\" data-headword=\"אֶפִּיטְרוֹפּוֹס\">אפי׳</a>) <a href=\"#\" data-headword=\"לִימּוּדִים\">למ׳</a></span> he must carry it (the unlawful property) after him even as far as Media. <span class=\"citation\">Kidd. 71ᵇ</span> מ׳ חולה Media is sick (doubtful as to purity of descent), v. <a href=\"#\" data-headword=\"גֹּוסֵס\">גּוֹסֵס</a>; <span class=\"citation\">Gen. R. s. 37</span>, end; <span class=\"citation\">Y. Yeb. I, end, 3ᵇ</span>; Y. Kidd. IV, 65ᵈ top <a href=\"#\" data-headword=\"מדוי\">מדוי</a> (read <span dir=\"rtl\">מדיי</span>). <span class=\"citation\">Esth. R. to I, 3</span> <span dir=\"rtl\">תשעה במ׳</span> nine portions (of beauty) has Media; (different in <span class=\"citation\">Kidd. 49ᵇ</span>). <span class=\"citation\">Ab. d’R. N. ch. XXVIII</span> <span dir=\"rtl\">עושרה של מ׳</span> (ed. Schechter <a href=\"#\" data-headword=\"רומי\">רומי</a>) the wealth of Media (Rome); a. fr.</div>","alt":["מָדַיי"]},"17257":{"h":"מָדִי","r":"M00281","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָדַי\">preced.</a>) <i>Median</i>. <span class=\"citation\">Sabb. II, 1</span>, a. e., v. <a href=\"#\" data-headword=\"נָחוּם\">נָחוּם</a>. <span class=\"citation\">Yoma 11ᵇ</span> <span dir=\"rtl\">שער המ׳</span> a Median gate (archway). <span class=\"citation\">Esth. R. to I, 22</span> <span dir=\"rtl\">לשון מ׳</span> the Median language; a. e.—<i>Fem</i>. <span dir=\"rtl\">מָדִית</span>, <a href=\"#\" data-headword=\"מָדִי\">מָדִיִּית</a>. Ib. <span class=\"citation\">Kel. XXIII, 2</span>, v. <a href=\"#\" data-headword=\"מְדוֹכָה\">מְדוֹכָה</a>; a. e.—Pl. <span dir=\"rtl\">מָדִיּוֹת</span>. <span class=\"citation\">Esth. R. to I, 11</span>. <span class=\"citation\">Sabb. VI, 6</span>, v. <a href=\"#\" data-headword=\"פָּרַף\">פָּרַף</a>. Y. ib. XII, 13ᶜ bot.; ib. IX, end, 12ᵇ חטים מ׳ Median wheat-grains; a. e.</div>","alt":["מָדִיִּי"]},"17258":{"h":"מָדָיָא","r":"M00282","html":"<div class=\"sense\"> <span class=\"citation\">Dan. VI, 1</span>.—Pl. <span dir=\"rtl\">מָדָאֵי</span>. <span class=\"citation\">Targ. Esth. X, 2</span>. [<span class=\"citation\">Y. Ab. Zar. II, 41ᶜ</span> top <a href=\"#\" data-headword=\"מָדַיי\">מדייא</a>, v. <a href=\"#\" data-headword=\"מַרְיָיא\">מָרָיָיה</a>.]</div>","alt":["מָדָאָה"]},"17259":{"h":"מדיבה","r":"M00283","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְדוֹכָה\">מְדוֹכָה</a></div>","alt":[]},"17260":{"h":"מְדִידָה","r":"M00284","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָדַד\">מָדַד</a>) <i>measuring</i>. <span class=\"citation\">B. Mets. 61ᵇ</span> (ref. to <span dir=\"rtl\">במדה</span>, <span class=\"citation\">Lev. XIX, 35</span>) <span dir=\"rtl\">זו מְדִידַת קרקע</span> this refers to land-measuring. Pesik. Vayhi, p. 7ᵃ (ref. to <span class=\"citation\">Ex. XXVI, 6</span> a. <span class=\"citation\">11</span>) <span dir=\"rtl\">אחד למ׳ וכ׳</span> one <span dir=\"rtl\">וחברת</span> refers to the measuring (fitting), the other to anointing (the tabernacle after it is put up). <span class=\"citation\">Y. Sot. IX, 23ᶜ</span> bot.; <span class=\"citation\">Snh. 14ᵇ</span>, v. <a href=\"#\" data-headword=\"עִיסּוּק\">עִיסּוּק</a>.—<span class=\"citation\">Sot. 45ᵃ</span>, v. <a href=\"#\" data-headword=\"עֶגְלָה\">עֶגְלָה</a>; a. e.</div>","alt":[]},"17261":{"h":"מדיונים","r":"M00285","html":"<div class=\"sense\">, Pesik. Ekhah, p. 122ᵇ, v. <a href=\"#\" data-headword=\"מֶרְיוֹן\">מֶרְיוֹן</a></div>","alt":[]},"17262":{"h":"מדיח","r":"M00286","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XIV, 14</span> ed. Wil., v. <a href=\"#\" data-headword=\"מְרַח II\"><span dir=\"rtl\">מְרַח</span> II</a>.</div>","alt":[]},"17263":{"h":"מָדַיי","r":"M00287","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָדַי\">מָדַי</a>, <a href=\"#\" data-headword=\"מָדִי\">מָדִי</a>, <a href=\"#\" data-headword=\"מָדָיָא\"><a href=\"#\" data-headword=\"מָדָיָא\">מָדָיָא</a>.</a></div>","alt":["מָדִיִּי","מָדָיָיא"]},"17264":{"h":"מִדְיָינָא","r":"M00288","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְדָנָא\">מְדָנָא</a></div>","alt":[]},"17265":{"h":"מְדִיל־","r":"M00289","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְדִל\">מְדִל</a></div>","alt":[]},"17266":{"h":"מַדֵּין","r":"M00290","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַדֵּן\">מַדֵּן</a></div>","alt":[]},"17267":{"h":"מָדִין","r":"M00291","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דֵּן\">דֵּן</a></div>","alt":[]},"17268":{"h":"מִדְיָן I","r":"M00292","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (b. h.) <i>Midian</i>, a nomadic tribe. <span class=\"citation\">Targ. Ex. II, 16</span>; a. fr.—<span class=\"citation\">Num. R. s. 20</span>, v. <a href=\"#\" data-headword=\"חָבַר\">חָבַר</a>; <span class=\"citation\">Snh. 105ᵃ</span>; a. fr.—Denom. <span dir=\"rtl\">מִדְיָנִי</span>, pl. <span dir=\"rtl\">מִדְיָנִים</span>. Num. R. l. c.; Tanḥ. Balak 3; a. fr.</div>","alt":[]},"17269":{"h":"מִדְיָן II","r":"M00293","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>strife</i>.—Pl. <span dir=\"rtl\">מִדְיָנִים</span>, <span dir=\"rtl\">מִדְיָנִין</span>. <span class=\"citation\">Hor. 10ᵇ</span> <span dir=\"rtl\">שהטיל מ׳ בין וכ׳</span> he (Lot) cast strife between Israel and Ammon; <span class=\"citation\">Naz. 23ᵇ</span> (corr. acc.).</div>","alt":[]},"17270":{"h":"מְדִינָא","r":"M00294","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְדִינְתָּא\">מְדִינְתָּא</a></div>","alt":[]},"17271":{"h":"מְדִינָה","r":"M00295","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [<i>jurisdiction</i>,] <i>district, country.</i> <span class=\"citation\">Maas. Sh. III, 4</span> (contrad. to Jerusalem). <span class=\"citation\">R. Hash. IV, 3</span>; <span class=\"citation\">Succ. III, 12</span> (contrad. to the Sanctuary); a. fr.—In gen. <i>province; large town, capital</i>. <span class=\"citation\">Pes. 51ᵃ</span> <span dir=\"rtl\">כל המ׳</span> all the people of the place. <span class=\"citation\">Gen. R. s. 50</span>, end, v. <a href=\"#\" data-headword=\"עִירוֹנִי\">עִירוֹנִי</a>. <span class=\"citation\">Esth. R. to I, 1</span> <span dir=\"rtl\">כל מקום שנ׳ … עיר מ׳ מ׳ אפרכיה</span> wherever <i>ʿir</i> is used in the Scriptures, it means a capital, wherever <i>m’dinah</i> is used, it means an hyparchia (province); a. fr.</div>","alt":[]},"17272":{"h":"מָדִינְחָא","r":"M00296","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּנַח\">דְּנַח</a>) <i>East</i>. <span class=\"citation\">Targ. Y. II, Gen. XV, 19</span>. <span class=\"citation\">Targ. Job I, 3</span> (h. text <span dir=\"rtl\">קדם</span>); a. fr.—Y. Gitt. II, 44ᵇ top <span dir=\"rtl\">בני מ׳</span> (= h. <span dir=\"rtl\">בני קדם</span>) nomads. <span class=\"citation\">Gen. R. s. 37</span>, end (translating <span dir=\"rtl\">הר הקדם</span>, <span class=\"citation\">Gen. X, 30</span>) <span dir=\"rtl\">טורי מ׳</span> the mountains of the East.—Constr. <a href=\"#\" data-headword=\"מַדְנַח\">מַדְנַח</a>. <span class=\"citation\">Targ. Num. XXXIV, 11</span>; a. e.—<span class=\"citation\">Y. B. Bath. II, 13ᶜ</span> top <span dir=\"rtl\">ממַדְנִיחֵיה</span> on the east-side of him.</div>","alt":["מַדִּי׳","מְדִנְחָא"]},"17273":{"h":"מְדִינְתָּא","r":"M00297","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. Is. X, 13</span> (ed. Lag. <a href=\"#\" data-headword=\"מְדִינָה\">מדינה</a>). Targ. II Esth. VIII, 9.—<span class=\"citation\">Targ. Prov. XVI, 32</span> (h. text <a href=\"#\" data-headword=\"*עַיִר\">עיר</a>). <span class=\"citation\">Targ. Y. II, Num. XXIV, 24</span> מ׳ רבתא Constantinople (or Rome); a. e.—<span class=\"citation\">Taan. 19ᵇ</span>, v. <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בַּצּוֹרְתָא</a>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> beg. <span dir=\"rtl\">תרע פילי דהאי מ׳</span> the gate of that city; a. fr.—Pl. <a href=\"#\" data-headword=\"מְדִינָא\">מְדִינָן</a>, <a href=\"#\" data-headword=\"מְדִינְתָּא\">מְדִינָתָא</a>. Targ. II Esth. l. c. <span class=\"citation\">Targ. I Kings XX, 14</span>. Targ. II Esth. IV, 11; a. fr.</div>","alt":["(… תָּה)","מְדִינָא"]},"17274":{"h":"מְדֵירָא","r":"M00298","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דְּרֵי I) = h. <a href=\"#\" data-headword=\"מִזְרֶה\">מִזְרֶה</a>, <i>winnowing fan</i>. <span class=\"citation\">Targ. Is. XXX, 24</span> (ed. Lag. <i>pl.</i>).—<i>Pl.</i> <span dir=\"rtl\">מְדֵירַיָּא</span>. <span class=\"citation\">Targ. Jer. XV, 7</span>.</div>","alt":[]},"17275":{"h":"מַדְכּוּרָא","r":"M00299","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּכַר I\">דְּכַר</a>) <i>marker, mark</i>.—Pl. <a href=\"#\" data-headword=\"מַדְכּוּרָא\">מַדְכּוּרֵי</a>, v. <a href=\"#\" data-headword=\"*מַדְבּוּרָא\">מַדְבּוּרָא</a>.</div>","alt":[]},"17276":{"h":"מַדְכוֹתָא","r":"M00300","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּכֵי\">דְּכֵי</a>) <i>cleansing, house-cleaning</i>. Targ. II Esth. III, 8.</div>","alt":[]},"17277":{"h":"*מַדְכַנְתָּא","r":"M00301","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּכַן\">דְּכַן</a>) <i>clean fat</i> (permitted to eat). <span class=\"citation\">Bekh. 30ᵃ</span> Var. in Ar., v. <a href=\"#\" data-headword=\"מַר III\"><span dir=\"rtl\">מַר</span> III</a>.</div>","alt":[]},"17278":{"h":"מֵדַל","r":"M00302","html":"<div class=\"sense\">, part. <i>Hif.</i> of <a href=\"#\" data-headword=\"דָּלַל\">דָּלַל</a>.</div>","alt":[]},"17279":{"h":"מְדִל","r":"M00303","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (compound of <a href=\"#\" data-headword=\"מָא\">מָא</a>, <span dir=\"rtl\">דִּ־</span>, a. <a href=\"#\" data-headword=\"ל\">ל</a>) <i>belonging, property</i>. <span class=\"citation\">Y. Keth. VI, 30ᵈ</span> bot. <span dir=\"rtl\">ר׳ … אתפקיד גביה מדל דיתמין</span> orphan’s money was given in trust of R …; <span class=\"citation\">Y. Gitt. V, 46ᵈ</span> bot. (insert <span dir=\"rtl\">גביה</span>); <span class=\"citation\">Y. Shek. IV, 48ᵃ</span> bot. <span class=\"citation\">Y. Ned. IX, 41ᶜ</span> <span dir=\"rtl\">הוא ומִדְלֵיה</span> himself and whatever belonged to him. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> beg. <span dir=\"rtl\">ואפקד בידיה מְדִילֵיה</span> and gave him his belongings in charge. Ib. end <span dir=\"rtl\">כל עותרא ומ׳ הדין</span> all these riches and belongings. Ib. <span dir=\"rtl\">דחלית דלא יסבון מדלי וכ׳</span> (read <span dir=\"rtl\">מדליה</span>) I was afraid lest his relatives may take away his belongings; a. e.—V. <a href=\"#\" data-headword=\"מוֹדְלָא\">מוֹדְלָא</a>.</div>","alt":["מִדְלָא","מִידְלָא"]},"17280":{"h":"מַדְלָא I","r":"M00304","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>watchman’s lodge</i>, v. <a href=\"#\" data-headword=\"*אַמַּדְלָא\">אַמַּדְלָא</a>.</div>","alt":[]},"17281":{"h":"*מַדְלָא II","r":"M00305","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. (<a href=\"#\" data-headword=\"דְּלֵי\">דְּלֵי</a>) <span dir=\"rtl\">מַדְלַיָּיא</span> <i>drawing, resorbing</i>. <span class=\"citation\">Pes. 40ᵃ</span> <span dir=\"rtl\">כל אגב מַדְלַיְּיהוּ וכ׳</span> as long as the grains absorb liquid, they do not ferment; v. <a href=\"#\" data-headword=\"*מִזְּלָא\">מִזְּלָא</a>.</div>","alt":[]},"17282":{"h":"מדלאות","r":"M00306","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִדְלַעַת\">next w.</a></div>","alt":[]},"17283":{"h":"מִדְלַעַת","r":"M00307","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"מִקְלָעָה\">מִדְלָעוֹת</a> (denom. of <a href=\"#\" data-headword=\"דְּלַעַת\">דְּלַעַת</a>) <i>gourd-fields.</i> <span class=\"citation\">Shebi. II, 1</span> <span dir=\"rtl\">במקשאות ובמ׳</span> (ed. Y. a. Ms. M. <span dir=\"rtl\">מקש׳ ומ׳</span>; not <span dir=\"rtl\">מדלא׳</span>) in cucumber and gourd fields; ib. 2. Y. ib. II, beg. 33ᶜ בשיש לו מקשה ומדלעת R. S. a. l. c. (ed. <span dir=\"rtl\">בו … ומודלה</span>) when he himself has a field of &amp;c; a. e.—<span class=\"citation\">Erub. 104ᵃ</span> מִדְלָעִין Ms. M. (ed. <span dir=\"rtl\">דלעיו</span>), v. <a href=\"#\" data-headword=\"מִקְשָׁה\">מִקְשָׁה</a>.</div>","alt":[]},"17284":{"h":"מְדַמְכָא","r":"M00308","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּמַךְ\">דְּמַךְ</a>) <i>sleeping</i>.—<a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>(<a href=\"#\" data-headword=\"ת\">ת</a>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>resting place, bed-room</i>. <span class=\"citation\">Targ. Job XXXIII, 15</span>. <span class=\"citation\">Ib. 19</span> (Ms. <a href=\"#\" data-headword=\"מִדַּעַם\">מִידְ׳</a>). <span class=\"citation\">Targ. Y. Gen. II, 24</span> <a href=\"#\" data-headword=\"מִדַּעַם\">מִדַּ׳</a>; a. e.</div>","alt":["מִדְמְכָא"]},"17285":{"h":"מִדְּמַר","r":"M00309","html":"<div class=\"sense\"> = <span dir=\"rtl\">מן דאמר</span>, v. <a href=\"#\" data-headword=\"מַר IV\"><span dir=\"rtl\">מַר</span> I</a></div>","alt":[]},"17286":{"h":"מָדֵן","r":"M00310","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דֵּן\">דֵּן</a></div>","alt":[]},"17287":{"h":"מַדֵּן","r":"M00311","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"מַעֲדֵן I\">מעדן</a>; b. h. <span dir=\"rtl\">מעדנות</span>; <a href=\"#\" data-headword=\"עָדַן\">עָדַן</a>, <i>Hif.</i>) <i>knot</i> in reed-matting. <span class=\"citation\">Tosef. Kel. B. Mets. XI, 12</span> <span dir=\"rtl\">טפחיים בין מדין למ׳</span> (R. S. to <span class=\"citation\">Kel. XX, 7</span> <span dir=\"rtl\">מדן</span>) two handbreadths of matting between each two knots.—Pl. <span dir=\"rtl\">מַדַּנִּים</span>, <span dir=\"rtl\">מַדַּנִּין</span>, <span dir=\"rtl\">מַעֲדַנִּ׳</span>. Ib. 11 <span dir=\"rtl\">עד שלא קשר ראשי מ׳</span> (not <span dir=\"rtl\">קצר</span>; R. S. l. c. <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מע׳</a>) before he knotted the tops of the knots. Ib. VII, 11 [read:] <span dir=\"rtl\">משיקשור ראשי המ׳ שלה</span> (v. R. S. to <span class=\"citation\">Kel. XVII, 17</span>). <span class=\"citation\">Kel. XX, 7</span> <span dir=\"rtl\">מעד׳</span>. <span class=\"citation\">Succ. 13ᵇ</span>; Y. ib. II, end, 52ᶜ <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מע׳</a>.</div>","alt":["מַדֵּין"]},"17288":{"h":"מַדָּנָא","r":"M00312","html":"<div class=\"sense\">, <i>bunch</i>, <i>bouquet</i>.—Pl. constr. <span dir=\"rtl\">מַדָּנֵי</span>. <span class=\"citation\">Sabb. 33ᵇ</span> Ar. (ed. <span dir=\"rtl\">מַדָּאנֵי</span>).</div>","alt":[]},"17289":{"h":"מְדָנָא","r":"M00313","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דִּין\">דִּין</a>) <i>object of strife</i>. <span class=\"citation\">Targ. Ps. LXXX, 7</span> (Ms. a. Regia <a href=\"#\" data-headword=\"מִדְיָינָא\">מִדְיָינָא</a>).</div>","alt":[]},"17290":{"h":"מַדְנַח","r":"M00314","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָדִינְחָא\">מָדִינְחָא</a></div>","alt":["מְדִנְחָא","מַדְנִיחָא"]},"17291":{"h":"מַדָּע","r":"M00315","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>intelligence</i>. <span class=\"citation\">Macc. 23ᵃ</span>, v. <a href=\"#\" data-headword=\"יָתֵר\">יָתֵר</a>.</div>","alt":[]},"17292":{"h":"מַדַּע","r":"M00316","html":"<div class=\"sense\">, <i>knowledge, teaching; reason</i>. <span class=\"citation\">Targ. Jer. III, 15</span>. <span class=\"citation\">Targ. Prov. I, 5</span>. <span class=\"citation\">Targ. Ps. XXXIV, 1</span> (Ms. <span dir=\"rtl\">דעת׳</span>).—<span dir=\"rtl\">ידע מ׳</span> (euphem. for <span dir=\"rtl\">משתין בקיר</span>) <i>male adult</i>. <span class=\"citation\">Targ. I Sam. XXV, 22</span>; a. fr.—<i>Pl.</i> (fem. form) <a href=\"#\" data-headword=\"מַדַּע\">מַדְּעָן</a>, <a href=\"#\" data-headword=\"מַדְרוֹן\">מִדְּ׳</a> <i>objects worth knowing</i> or <i>well-known</i>, (used of persons) <i>notables</i>. <span class=\"citation\">Targ. O. Deut. I, 13</span>; <span class=\"citation\">15</span> (v. Berl. Massorah, p. 120; h. text <span dir=\"rtl\">ידעים</span>).—V. <a href=\"#\" data-headword=\"מַנְדַּע\">מַנְדָּע</a>.</div>","alt":["מַדְּעָא","מִ׳"]},"17293":{"h":"מִדַּעַם","r":"M00317","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <span dir=\"rtl\">מדע</span>, v. <a href=\"#\" data-headword=\"מַדַּע\">preced.</a>, a. enclitic <a href=\"#\" data-headword=\"מ\">מ</a> for <a href=\"#\" data-headword=\"מָא\">מא</a>) [<i>noticeable</i>,] <i>something; anything</i> (corresp. to h. <a href=\"#\" data-headword=\"מאום\">מְאוּם</a>, <a href=\"#\" data-headword=\"מְהוּמָה\">מְאוּמָה</a> or <a href=\"#\" data-headword=\"דָּבָר\">דָּבָר</a>). <span class=\"citation\">Targ. Job XXXI, 7</span>. <span class=\"citation\">Targ. Gen. XXII, 12</span> (Y. Levita <a href=\"#\" data-headword=\"מִנְדַּעַם\">מִנְדַּעַם</a>). <span class=\"citation\">Targ. Deut. XVII, 1</span>; a. fr.—<span class=\"citation\">Bekh. 51ᵇ</span> <span dir=\"rtl\">מי׳ ביש עבדת</span> (Rashi a. Tosaf.) thou didst something wrong (in giving the redemption money with the expectation of getting it refunded). <span class=\"citation\">Snh. 55ᵃ</span> <span dir=\"rtl\">אמי׳ אחרינא וכ׳</span> for doing something else (unnatural gratification) he ought not to be punished. Tanḥ. Ḥuck. 2 <span dir=\"rtl\">מן מ׳ מסאבא</span> from anything unclean. <span class=\"citation\">B. Bath. 123ᵃ</span> <span dir=\"rtl\">לא מהניא … ולא מ׳</span> (Ms. M. <a href=\"#\" data-headword=\"מִידֵי\">מידי</a>) would Joseph have been given no preference whatever?; a. e.—V. <a href=\"#\" data-headword=\"מִידֵי\">מִידֵּי</a>, <a href=\"#\" data-headword=\"מֵידַם\">מֵידַם</a>.</div>","alt":["מִידַּ׳"]},"17294":{"h":"מֹדַעַת","r":"M00318","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹדַעַת\">מוֹדַעַת</a></div>","alt":[]},"17295":{"h":"מֵדֵף","r":"M00319","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דפף</span>; v. <a href=\"#\" data-headword=\"דַּף\">דּף</a>) <i>clap-board, trap</i> for birds. <span class=\"citation\">Kel. XXIII, 5</span>.</div>","alt":[]},"17296":{"h":"מַדָּף","r":"M00320","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָדַף\">נָדַף</a>) <i>a vessel used for smoking bees out</i>, v. <a href=\"#\" data-headword=\"דְּבוֹרָה\">דְּבוֹרָה</a>. <span class=\"citation\">Kel. XVI, 7</span>.</div>","alt":[]},"17297":{"h":"מִדָּף","r":"M00321","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָדַף\">נָדַף</a>) <i>indirect contact by shaking, breathing &amp;c</i>. (cmp. <a href=\"#\" data-headword=\"מִדְרָס\">מִדְרָס</a>, <a href=\"#\" data-headword=\"הֶיסֵּט\">הֶיסֵּט</a>).—Esp. <span dir=\"rtl\">טומאת מ׳</span>, or <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>the uncleanness of an object arising from an unclean person’s indirect contact; the object thus made unclean; uncleanness of a minor degree</i>. <span class=\"citation\">Nidd. 4ᵃ</span> <span dir=\"rtl\">ומ׳</span> (<a href=\"#\" data-headword=\"טָמֵא I\">טמא</a>) <span dir=\"rtl\">נתון תחתיו</span> (<span class=\"citation\">Tosef. Toh. IV, 4</span> <a href=\"#\" data-headword=\"מִדְרָס\">מדרס</a>) and an object of minor uncleanness rests under it. Sifra M’tsorʿa, <span class=\"citation\">Zabim, ch. IV</span>, Par. 3 <span dir=\"rtl\">עושה תחתיו מ׳</span> he makes the things under him (e. g. cushions directly under his head) unclean as a <i>middaf;</i> a. e.—Pl. <span dir=\"rtl\">מִדָּפוֹת</span> <i>laws concerning middaf</i>. <span class=\"citation\">Y. Sot. V, 20ᵇ</span>. <span class=\"citation\">Y. Dem. II, 23ᵃ</span> top.—<span class=\"citation\">Y. Sabb. VII, 9ᵈ</span> bot. <span dir=\"rtl\">מהו מ׳ מגעות</span> what kind of <i>middafoth?</i> Contact.</div>","alt":[]},"17298":{"h":"מֵדַק","r":"M00322","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּקַק\">דָּקֵק</a></div>","alt":[]},"17299":{"h":"מִדְּקָא","r":"M00323","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִדְּ־\">מִדְּ־</a></div>","alt":[]},"17300":{"h":"מֶדֶר","r":"M00324","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <span dir=\"rtl\">מרד</span>, v. <a href=\"#\" data-headword=\"מִרְדָּא\">מִרְדָּא</a>) [<i>fallings</i>, v. <a href=\"#\" data-headword=\"גָּלָל\">גָּלָל</a>,] <i>ordure</i>, a material used for vessels. Sifra M’tsorʿa, Neg., Par. 6, ch. IV. [R. S. to <span class=\"citation\">Neg. XII, 6</span> quotes <span dir=\"rtl\">מרד</span>, ref. to <a href=\"#\" data-headword=\"מַרְדָּא I\">מרדא</a> <span class=\"citation\">Ab. Zar. 75ᵇ</span>.]</div>","alt":[]},"17301":{"h":"מָדַר","r":"M00325","html":"<div class=\"sense\">, <i>Hif.</i> <a href=\"#\" data-headword=\"קָדַר I\">הִמְדִּיר</a> (denom. of <a href=\"#\" data-headword=\"מַדְרוֹן\">מַדְרוֹן</a>) <i>to slant, to incline</i>. <span class=\"citation\">B. Bath. 22ᵇ</span> במַמְדִּיר את וכ׳ Ar. a. Ms. F. (Ms. M. <span dir=\"rtl\">בממרי׳</span>; ed. <span dir=\"rtl\">במדיר</span>. Ms. H. <span dir=\"rtl\">במְרַדֵּד</span>; Ms. O. <span dir=\"rtl\">בממרדיר</span>, v. Rabb. D. S. a. l. note) when he inclines the sill of his wall (so that none can stand or lean on it).</div>","alt":[]},"17302":{"h":"מִדְרָא","r":"M00326","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">מִדְרֵי</span> (transpos. of <a href=\"#\" data-headword=\"מַרְדָּא I\">מרדא</a>; <a href=\"#\" data-headword=\"יָרַד\">יָרַד</a>; cmp. <a href=\"#\" data-headword=\"מַדְרוֹן\">מַדְרוֹן</a>) <i>water-courses, gutters</i>. <span class=\"citation\">Sabb. 145ᵇ</span> <span dir=\"rtl\">הני מ׳ דבבל</span> (Ms. M. <a href=\"#\" data-headword=\"מְשָׁכָא\">בי מ׳</a>; Ms. O. <span dir=\"rtl\">בי מרדי</span>) the drains of Babylonia; <span class=\"citation\">Bekh. 44ᵇ</span> <span dir=\"rtl\">מדורי</span> (corr. acc.).</div>","alt":[]},"17303":{"h":"מַדְרָא","r":"M00327","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <a href=\"#\" data-headword=\"מַרְדָּא I\">מרדא</a>, <a href=\"#\" data-headword=\"רְדֵי\">רְדֵי</a>; cmp. <a href=\"#\" data-headword=\"מִדְרָא\">preced.</a>) <i>chastising whip</i>. <span class=\"citation\">Yoma 23ᵃ</span> (Ms. L. <span dir=\"rtl\">מרתעא</span>; Ar. s. v. <span dir=\"rtl\">דר</span><sup>3</sup>: <a href=\"#\" data-headword=\"מדוורתא\">מדוורתא</a>; Ms. O. <span dir=\"rtl\">מתעורתא</span>, v. Rabb. D. S. a. l. note 8), v. <a href=\"#\" data-headword=\"פְּקִיעַ I\"><span dir=\"rtl\">פְּקִיעַ</span> I</a>.</div>","alt":[]},"17304":{"h":"מַדְרֵגָה","r":"M00328","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>embankment, acclivity.</i> <span class=\"citation\">Kil. VI, 2</span> <span dir=\"rtl\">אחת בארץ ואחת במ׳</span> one row on level ground and one on the embankment. Y. ib. 30ᶜ top <span dir=\"rtl\">שיפוע המ׳ כלמטן</span> (not <span dir=\"rtl\">שופע</span>) the slope of the embankment is considered as if on a level with the lower ground; <span class=\"citation\">Y. Sabb. XI, 13ᵃ</span> bot.; a. fr.—Pl. <span dir=\"rtl\">מַדְרֵגוֹת</span>, <a href=\"#\" data-headword=\"מַדְרֵגָה\">מַדְרֵי׳</a>. <span class=\"citation\">Tosef. Peah I, 9</span>. <span class=\"citation\">Shebi. II, 8</span>; <span class=\"citation\">Tosef. ib. III, 4</span>, v. <a href=\"#\" data-headword=\"גַּיְא\">גַיְא</a>.</div><div class=\"sense\"><b>—2)</b> <i>step, rank</i>. <span class=\"citation\">Kidd. 40ᵇ</span></div>","alt":["מַדְרֵי׳"]},"17305":{"h":"מָדֹר","r":"M00329","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">מִדֹרוֹת</span>, v. <a href=\"#\" data-headword=\"מָדוֹר\">מָדוֹר</a>.</div>","alt":[]},"17306":{"h":"מַדְרוֹכִיתָא","r":"M00330","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> pr. n. (<span dir=\"rtl\">דרך</span>) <i>Madrokhitha</i>, name of a peak. <span class=\"citation\">Targ. I Sam. XIV, 4</span> (h. text <a href=\"#\" data-headword=\"סְנֶה\">סֶנֶה</a>).</div>","alt":[]},"17307":{"h":"מַדְרוֹן","r":"M00331","html":"<div class=\"sense\"> (in Y. Dial.) <a href=\"#\" data-headword=\"מוּנְדְּרוֹן\">מוּנְדְּרָן</a>, <a href=\"#\" data-headword=\"מִנְדְּרוֹן\">מִנְדְּרָן</a> m. (v. <a href=\"#\" data-headword=\"מִדְרָא\">מִדְרָא</a> a. <a href=\"#\" data-headword=\"נְדַר II\"><span dir=\"rtl\">נְדַר</span> II</a>) <i>sloping</i>; <span dir=\"rtl\">מקום מ׳</span> <i>declivity</i>. <span class=\"citation\">Pes. 42ᵃ</span>, opp. <a href=\"#\" data-headword=\"אֶשְׁבֹּורָן\">אֶשְׁבּוֹרָן</a>. <span class=\"citation\">B. Mets. 82ᵇ</span>, sq.—<span class=\"citation\">Y. Sabb. XI, 13ᵃ</span> bot. <span dir=\"rtl\">בשהיה המקום מונ׳</span> when the place was sloping; Y. Erub. X, 26ᵃ bot. <a href=\"#\" data-headword=\"מוּנְיָיק\">מנ׳</a>; Y. B. Bath. I, end, 13ᵃ <a href=\"#\" data-headword=\"מִנְדְּרוֹן\">מִנְדְּרוֹן</a>. <span class=\"citation\">Y. Erub. I, 18ᶜ</span> top <span dir=\"rtl\">היה מונ׳ וכ׳</span> (sub. <a href=\"#\" data-headword=\"מקום\">מקום</a>) if there was a declivity in the middle of the alley. Y. Sot. IX, 23ᶜ bot. <a href=\"#\" data-headword=\"מוּנְיָיק\">מנ׳</a>.—<span class=\"citation\">Tosef. Mikv. IV, 10</span> (expl. <a href=\"#\" data-headword=\"חַרְדְּלִית\">חַרְדְּלִית</a>) <span dir=\"rtl\">מי גשמים הבאין מד׳</span> (Maim. to <span class=\"citation\">Mikv. V, 6</span> <span dir=\"rtl\">מן חמ׳</span>) rain water that runs down a declivity.</div>","alt":["מִדְּ׳"]},"17308":{"h":"מִדְרוֹן","r":"M00332","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Mic. I, 4</span> (ed. Wil. <a href=\"#\" data-headword=\"מִדְרוֹן\">מוד׳</a>; h. text <a href=\"#\" data-headword=\"מוֹרָד I\">מוֹרָד</a>). <span class=\"citation\">Targ. Ps. LXXXIII, 14</span> (ed. Lag. <a href=\"#\" data-headword=\"מִדְרוֹן\">מוד׳</a>). V. <a href=\"#\" data-headword=\"נְדַר II\"><span dir=\"rtl\">נְדַר</span> II</a></div>","alt":["מוֹדְ׳"]},"17309":{"h":"מַדְרֵיגָה","r":"M00333","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַדְרֵגָה\">מַדְרֵגָה</a></div>","alt":[]},"17310":{"h":"מִדְרָס","r":"M00334","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דָּרַס\">דָּרַס</a>) </div><div class=\"sense\"><b>1)</b> <i>treading, place trodden upon</i>, in gen. <i>basis, seat</i>, esp. <i>midras</i>, levitical uncleanness arising from a gonorrhoeist’s immediate contact by treading, leaning against &amp;c. <span class=\"citation\">Nidd. VI, 3</span> <span dir=\"rtl\">כל המיטמא</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<a href=\"#\" data-headword=\"מ׳\">מ׳</a> whatever can be made unclean as a <i>midras</i>; expl. <span class=\"citation\">ib. 49ᵇ</span> <span dir=\"rtl\">כל דחזי למ׳</span> whatever is fit to be used as a seat, couch &amp;c. <span class=\"citation\">Kel. XXIV, 1</span>. <span class=\"citation\">Par. X, 1</span>; a. v. fr.—In gen. = <span dir=\"rtl\">אב הטומאה</span>, <i>uncleanness of the first degree</i>. <span class=\"citation\">Ḥag. II, 7</span>; a. fr.—Pl. <span dir=\"rtl\">מִדְרָסוֹת</span> <i>cases of midras</i>. <span class=\"citation\">Ḥull. 35ᵃ</span>. <span class=\"citation\">Sabb. 59ᵃ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  a sort of <i>shoe</i> or <i>heel</i>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 14</span> התקינו למנעול או למ׳ R. S. to <span class=\"citation\">Kel. XII, 5</span> (ed. <span dir=\"rtl\">למחרים</span>, corr. acc.) if he made the nail for a shoe or a <i>midras</i></div>","alt":[]},"17311":{"h":"מדרעא","r":"M00335","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְדְּעָא\">מַרְדְּעָא</a></div>","alt":[]},"17312":{"h":"מדרקא","r":"M00336","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרְדְּקָא\">מוּרְדְּקָא</a></div>","alt":[]},"17313":{"h":"מִדְרָשׁ","r":"M00337","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>textual interpretation; study</i>. <span class=\"citation\">Keth. IV, 6</span> <span dir=\"rtl\">זה מ׳ דרש וכ׳</span> the following interpretation did R … teach &amp;c.; <span class=\"citation\">Shek. VI, 6</span>.—<span class=\"citation\">Y. Yeb. XV, 14ᵈ</span> <span dir=\"rtl\">עבדין כתובה מ׳</span>, v. <a href=\"#\" data-headword=\"כְּתוּבָּה\">כְּתוּבָּה</a>; a. fr.—<span class=\"citation\">Ab. I, 17</span> <span dir=\"rtl\">לא המ׳ הוא העיקר וכ׳</span> not study is the main thing, but practice is. <span class=\"citation\">Kidd. 49ᵃ</span> bot. <span dir=\"rtl\">משנה … אומר מ׳</span> by Mishnah …, R. Judah says, we understand textual interpretation (as Sifra, Sifré &amp;c.), contrad. to <a href=\"#\" data-headword=\"הִלְכוּת\">הלכות</a>. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">מאי תורה מִדְרַשׁ תורה</span> (R. Johanan means) by Torah the interpretation of the Torah text; a. fr.—<span dir=\"rtl\">בֵּית הַמִּ׳</span> (abbr. <span dir=\"rtl\">בה&quot;מ</span>) <i>school, college</i>. <span class=\"citation\">Meg. 27ᵃ</span> <span dir=\"rtl\">בה&quot;כ מותר לעשותו בה&quot;מ</span> you may change a synagogue into a school house; a. fr.—Pl. <span dir=\"rtl\">מִדְרָשׁוֹת</span>. <span class=\"citation\">Ker. 13ᵇ</span>. Y. Ter. VIII, 45ᵇ top; (ib. I, 40ᵈ <span dir=\"rtl\">מקריות</span>). <span class=\"citation\">Gen. R. s. 42</span> <span dir=\"rtl\">בתי מ׳</span> school houses; a. fr.—Esp. <i>Midrash, homiletic book</i>. <span dir=\"rtl\">מִדְרַשּׁ רבה</span> <i>Midrash Rabbah, homilies on the Pentateuch</i> (<i>and the five M’gilloth</i>) (beginning with <span dir=\"rtl\">ר׳ הושעיא רבה</span>).—<span dir=\"rtl\">מ׳ חזית</span> (from its beginning <a href=\"#\" data-headword=\"חָזִית\">חָזִיתָ</a>, <span class=\"citation\">Prov. XXII, 29</span>) = <span dir=\"rtl\">מ׳ שיר השירים</span> <i>Canticum Rabbah</i>; <span dir=\"rtl\">מ׳ אסתר</span> <i>Midrash Esther</i> or <i>Esther Rabbah</i> &amp;c.—<span dir=\"rtl\">מ׳ שמואל</span> a Midrash to the Books of Samuel; <span dir=\"rtl\">מ׳ תִּלִּים</span>, also <span dir=\"rtl\">שׁוֹחֵר טוֹב</span> (from its beginning, <span class=\"citation\">Prov. XI, 27</span>) a Midrash to the Psalms.—מ׳ תַּנְחוּמָא <i>Midrash Tanḥuma</i>, to the Pentateuch.—<i>Pl</i>. <span dir=\"rtl\">מִדְרָשִׁים</span> <i>Midrashim</i>, esp. <span dir=\"rtl\">רַבּוֹת</span> <i>Rabboth</i> (a plural of <a href=\"#\" data-headword=\"רַבָּה I\">רַבָּה</a> by false analogy).</div>","alt":[]},"17314":{"h":"מִדְרָשָׁא","r":"M00338","html":"<div class=\"sense\"> <span class=\"citation\">Lev. R. s. 9</span> <span dir=\"rtl\">תתנא מ׳</span> (read: <span dir=\"rtl\">אתעני</span>; <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">איעני דרשה</span>) the lecture was delayed.—<a href=\"#\" data-headword=\"מְשָׁכָא\">בי מ׳</a> (in Targ. frequ. only <a href=\"#\" data-headword=\"מ׳\">מ׳</a>) = h. <span dir=\"rtl\">בית המדרש</span>, v. <a href=\"#\" data-headword=\"מִדְרָשׁ\">preced.</a> <span class=\"citation\">Targ. Y. Gen. IX, 27</span>. <span class=\"citation\">Ib. XXV, 27</span>; a. fr.—<span class=\"citation\">Ab. Zar. 74ᵇ</span>; <span class=\"citation\">Erub. 60ᵃ</span>, v. <a href=\"#\" data-headword=\"צָוַוח\">צְוַוח</a>. <span class=\"citation\">Y. Yoma III, 40ᶜ</span> bot., v. <a href=\"#\" data-headword=\"חֲדַת\">חֲדַת</a>. <span class=\"citation\">Pes. 33ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">מִדְרָשִׁין</span>, <span dir=\"rtl\">מִדְרָשַׁיָּא</span>, <a href=\"#\" data-headword=\"מִדְרָשָׁא\">מֶדְ׳</a>. <span class=\"citation\">Targ. Jud. V, 24</span>. <span class=\"citation\">Targ. Ps. LXXX, 11</span>; a. e.</div>","alt":["מֶדְ׳"]},"17315":{"h":"מדרתא","r":"M00339","html":"<div class=\"sense\">, <span dir=\"rtl\">כנישתא מ׳</span>, v. <a href=\"#\" data-headword=\"מָרָדְתָּא\">מָרָדְתָּא</a></div>","alt":[]},"17316":{"h":"מָה","r":"M00340","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>something; anything</i>. <span class=\"citation\">Num. R. s. 14</span>; Tanḥ. Ḥayé 3, v. <a href=\"#\" data-headword=\"בְּלִימָה\">בְּלִימָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>what? which?</i> <span class=\"citation\">Ḥull. 89ᵃ</span> (play on <span dir=\"rtl\">הא̇מ̇נ̇ם א̇ל̇ם̇</span>, <span class=\"citation\">Ps. LVIII, 2</span>) <span dir=\"rtl\">מה א̇ומ̇נ̇תו … כא̇ל̇ם̇</span> which is the best policy for man in this world? Let him act as if he were mute (keep silence). <span class=\"citation\">B. Mets. 63ᵃ</span>, a. e. <span dir=\"rtl\">מה לו הן מה לי דמיהן</span> what are they to me and what their equivalent, i.e. what difference does it make whether the purchased objects or their equivalent be delivered?; <span class=\"citation\">Y. Yoma V, 43ᵃ</span> bot. <span dir=\"rtl\">מה ביניהן ומה בין דמיהן</span>. <span class=\"citation\">B. Bath. 32ᵇ</span>; <span class=\"citation\">31ᵃ</span> <span dir=\"rtl\"><span dir=\"rtl\">מה</span> (<a href=\"#\" data-headword=\"לֵי\">לי</a>) <span dir=\"rtl\">לו לשקר</span></span> what motive could he have to tell a lie? Ib., a. e. <span dir=\"rtl\">מה לי לשקר במקום עדים וכ׳</span> we do not apply the principle that we believe a defendant because he has no motive to lie, where witnesses are on hand; a. v. fr.—<span dir=\"rtl\">מה … אף</span> what …?, even so, i.e. <i>as … so</i>. <span class=\"citation\">Gitt. 23ᵇ</span> <span dir=\"rtl\">מה אתם … אף וכ׳</span> as <i>you</i> (<span class=\"citation\">Num. XVIII, 28</span>) refers to Israelites, so must your delegate be an Israelite. <span class=\"citation\">Sabb. 133ᵇ</span> <span dir=\"rtl\">מה הוא … אף וכ׳</span> as He is gracious and merciful, so be thou &amp;c.; a. fr.—<span dir=\"rtl\">מה … לא כל שכן</span>, v. <a href=\"#\" data-headword=\"כָּל\">כָּל</a>.—<span dir=\"rtl\">מה … אינו דין</span>, v. <a href=\"#\" data-headword=\"דִּין II\"><span dir=\"rtl\">דִּין</span> II</a>.—<span dir=\"rtl\">מה ל־ … שכן … תאמר</span> what has this to do with …? In this case …, whereas &amp;c., i.e. <i>it is different with</i> … <i>because</i> &amp;c. <span class=\"citation\">Kidd. 4ᵇ</span> <span dir=\"rtl\">מה ליבמה שכן … תאמר וכ׳</span> the case of a Y’bamah is different, because she can neither be acquired by means of a document, whereas this (an ordinary woman) &amp;c.; a. fr.—<span dir=\"rtl\">מָה נַפְשְׁךָ</span> (in Babli mostly: <span dir=\"rtl\">מִמָּה נפשך</span>; abbr. <span dir=\"rtl\">ממ&quot;נ</span>) whatever be thy opinion (from whatever opinion thou start), i.e. <i>whichever side you take, at all events</i>. <span class=\"citation\">Y. Ber. I, 2ᵇ</span> <span dir=\"rtl\">מ׳ נ׳ אם וכ׳</span> at all events (he has offended); if it was day-time when the first stars (on Friday evening) were visible, it was day-time when the first stars (on Sabbath evening) were visible &amp;c.; <span class=\"citation\">Sabb. 35ᵇ</span> <span dir=\"rtl\">חייכ חטאת ממ&quot;נ</span> must bring a sin-offering at all events (whether you consider twilight a part of the day or a part of the night). <span class=\"citation\">Ib. 34ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">מה נפשך אי וכ׳</span> whichever side you take, if twilight is day &amp;c. <span class=\"citation\">Erub. 10ᵃ</span> <span dir=\"rtl\">גדולה … למה לי ממ&quot;נ אי וכ׳</span> what reason was there for saying ‘large …’? In either case (it is incorrect), if it be to permit the use of the larger court &amp;c. <span class=\"citation\">Ḥull. 29ᵃ</span> <span dir=\"rtl\">ממ&quot;נ אי מחצה וכ׳</span> in either case (the slaughtering is ritually correct); if you adopt the opinion that an exact half is to be considered as if it were the larger portion &amp;c.; a. v. fr.—<span class=\"citation\">Ib. 78ᵇ</span> <span dir=\"rtl\">מה אם נפשך</span>, v. <a href=\"#\" data-headword=\"נֶפֶשׁ\">נֶפֶשׁ</a>.—<a href=\"#\" data-headword=\"בָּמָה\">בַּמֶּה</a> a) <i>wherewith?</i> <span class=\"citation\">B. Bath. 10ᵇ</span> <span dir=\"rtl\">במה תרום וכ׳</span> whereby can the horn of Israel be lifted up? <span class=\"citation\">Sabb. II, 1</span>; a. fr.—b) <i>in what case?</i> <span dir=\"rtl\">במה דברים אמורים</span> (abbr. <span dir=\"rtl\">בד&quot;א</span>), v. <a href=\"#\" data-headword=\"אָמַר I\"><span dir=\"rtl\">אָמַר</span> I</a>.—לָמָּה <i>wherefore?</i> <span class=\"citation\">Ber. 3ᵃ</span> <span dir=\"rtl\">תחלת … סימנא למה לי</span> what need is there for a sign for the beginning of the first watch? <span class=\"citation\">M. Kat. 28ᵃ</span> <span dir=\"rtl\">ל׳ נסמכה וכ׳</span> why is the account of the death of Miriam attached to &amp;c.?; a. fr.—לַמֶּה <i>to what?, whereto?</i> <span class=\"citation\">Kidd. 40ᵇ</span> <span dir=\"rtl\">ל׳ צדיקים נמשלים</span> what are the righteous to be compared to?—<span dir=\"rtl\">ל׳ הדבר דומה</span>, v. <a href=\"#\" data-headword=\"דָּמָה\">דָּמָה</a>; a. fr.—V. <a href=\"#\" data-headword=\"לָמָה\">לָמָה</a>.</div><div class=\"sense\"><b>—3)</b>  (relat.) <i>which, what</i>. <span class=\"citation\">Pes. 88ᵇ</span> <span dir=\"rtl\">מה שקנה עבד וכ׳</span> whatever the slave acquires belongs to the master. <span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\">כל מה שאמרו וכ׳</span> for whatever act the scholars designated the time ‘up to midnight’ &amp;c.; a. v. fr.</div>","alt":["מַה"]},"17317":{"h":"מָה ²","r":"M00341","html":"<div class=\"sense\"> ch. <a href=\"#\" data-headword=\"מָה\">same</a> (v. <a href=\"#\" data-headword=\"מָא\">מָא</a>). <span class=\"citation\">Targ. II Sam. XVIII, 23</span>. <span class=\"citation\">Targ. Ex. XXXIII, 21</span>; a. v. fr.—<span class=\"citation\">Snh. 65ᵇ</span>; <span class=\"citation\">Gen. R. s. 11</span>, v. <a href=\"#\" data-headword=\"גּוּבְרָא\">גּוּבְרָא</a>. <span class=\"citation\">Y. Ned. VI, end, 40ᵃ</span> <span dir=\"rtl\">מה שבקית תמן</span> what (prominent men) I left there (in Palestine); <span class=\"citation\">Y. Snh. I, 19ᵃ</span> top (corr. acc.) [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה מודע לי</span>, read <span dir=\"rtl\">מאן</span>.]—<span class=\"citation\">Y. Gitt. I, 43ᵈ</span> <span dir=\"rtl\">מה אנן קיימין</span> what do we stand at, i.e. what is the case before us? <span class=\"citation\">Y. Dem. I, 21ᵈ</span> bot. <span dir=\"rtl\">מה אפשר דר׳ וכ׳</span> what? is it possible that &amp;c.? i.e. it is impossible that &amp;c.; <span class=\"citation\">ib.</span> <span dir=\"rtl\">מה ר׳ ז׳ מיכול וכ׳</span> it is impossible that R. Z. should eat &amp;c. <span class=\"citation\">Y. Sabb. XIV, 14ᶜ</span> <span dir=\"rtl\">מה ביניהון</span> wherein do they differ?, v. <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a>. <span class=\"citation\">Ḥull. 34ᵃ</span>, a. e. <span dir=\"rtl\">מה נפשך</span>, v. <a href=\"#\" data-headword=\"מָה\">preced.</a>; a. v. fr.—<a href=\"#\" data-headword=\"מָהִיא\">מָהִיא</a> = <span dir=\"rtl\">מה היא</span>, how is it? Y. Sabb. l. c.</div>","alt":["מַה"]},"17318":{"h":"מָהָא","r":"M00342","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָהָה\">מָהָה</a></div>","alt":[]},"17319":{"h":"מהגינות","r":"M00343","html":"<div class=\"sense\">, <span class=\"citation\">Y. Keth. I, 25ᵇ</span> top, v. <a href=\"#\" data-headword=\"הָגַן\">הָגַן</a>. [Comment. take our w. as a geographical designation of coins; v. Zuckermann Talm. Münzen, p. 15.]</div>","alt":[]},"17320":{"h":"מַהֲדוֹרָא","r":"M00344","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲדַר\">הֲדַר</a>) <i>review, revision</i>. <span class=\"citation\">B. Bath. 157ᵇ</span> <span dir=\"rtl\">מ׳ קמא דר׳ וכ׳</span> (in) the first revision (of the Talmudic traditions) by R. Ashi he told us (v. Rabb. D. S. a. l. note 3). [In later literature <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>edition</i>.]</div>","alt":[]},"17321":{"h":"מַהֲדוּרָא","r":"M00345","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲדַר\">הֲדַר</a>) <i>peddler</i>.—Pl. <span dir=\"rtl\">מַהֲדוּרֵי</span>. <span class=\"citation\">Ber. 51ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּלְמְתָא\">כַּלְמְתָא</a>.</div>","alt":[]},"17322":{"h":"מָהָה","r":"M00346","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">מִיהָה</span>, <a href=\"#\" data-headword=\"מִיהָא\">מִיהֵא</a> (v. <a href=\"#\" data-headword=\"מָחָה\">מָחָה</a>) <i>to dissolve, dilute;</i> (of clothes) <i>to make threadbare and ragged</i>.—Part. pass. <span dir=\"rtl\">מְהוּהֶא</span>, f. <span dir=\"rtl\">מְהוּהָא</span>, <a href=\"#\" data-headword=\"מְהוּמָה\">מְהוּהָה</a>. <span class=\"citation\">Toh. IX, 9</span> <span dir=\"rtl\">מטלות מהוהה</span> ed. Dehr. (oth. ed. … <span dir=\"rtl\">הא</span>) a tattered (scorched) piece of cloth; <span class=\"citation\">Nidd. 56ᵃ</span> <span dir=\"rtl\">מטלית המהוהא</span>; <span class=\"citation\">ib. 4ᵃ</span> <span dir=\"rtl\">המהומה׳</span> (corr. acc.). <span class=\"citation\">Kel. XXIV, 17</span> <span dir=\"rtl\">מהוהה שטלייה וכ׳</span> a threadbare shred patched on a sound one (<a href=\"#\" data-headword=\"בְּרִיָּיה\">בְּרִיָּיה</a>, v. <a href=\"#\" data-headword=\"בָּרִי\">בָּרִיא</a>).</div><div class=\"sense\"><b>Nif. נִמְהָה  נִמְהָא</b> <div class=\"sense\"><i>to be tattered, fall to pieces</i>. Ib. XXVII, 12 ed. Dehr. <a href=\"#\" data-headword=\"מָהָה\">נמהא</a>, Mish. ed. <a href=\"#\" data-headword=\"מָהָה\">נמהה</a>; Talm. ed. <a href=\"#\" data-headword=\"מחי\">נמחה</a>).</div></div><div class=\"sense\"><b>Hif. הִמְהָה  הִמְהָא</b> <div class=\"sense\"><i>to dissolve; to crumble, sift.</i> <span class=\"citation\">Maas. Sh. V, 1</span> מַמְהֶה ושופך Ar. (ed. pr. <span dir=\"rtl\">מַמְהֶא</span>; ed. <span dir=\"rtl\">ממחה</span>) he dissolves (the lime) and pours it over the spot; <span class=\"citation\">B. Kam. 69ᵃ</span> ממהה Ms. R. (ed. … <span dir=\"rtl\">חה</span>). <span class=\"citation\">Zeb. 54ᵃ</span> מביא סיד … וממהא וכ׳ Ar. (ed. <span dir=\"rtl\">וממחה</span>) takes lime, molten lead and pitch and mixes them and pours &amp;c. Ohol. XVIII, 4 <span dir=\"rtl\">וממהה</span> ed. Dehr. (Ar. <span dir=\"rtl\">וממהא</span>, ed. … <span dir=\"rtl\">חה</span>) and crumbles (and sifts the earth).</div></div>","alt":["מָהָא"]},"17323":{"h":"מָהוּ","r":"M00347","html":"<div class=\"sense\"> (= <span dir=\"rtl\">מה הו</span>) <i>what is it? how is it?</i> Targ. II Esth. I, 2 (3); a. e.—<span class=\"citation\">Kidd. 33ᵇ</span> <span dir=\"rtl\">מ׳ שיעמוד וכ׳</span> how is it, i.e. must his father stand up before him? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ לעמוד וכ׳</span> must one stand up &amp;c.?—<span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span> <span dir=\"rtl\">מ׳ בורקי</span> what does <i>bor’kay</i> mean?—<span class=\"citation\">Ḥull. 46ᵃ</span> <span dir=\"rtl\">מתלקט מ׳</span> how is it if the liver is &amp;c., v. <a href=\"#\" data-headword=\"לָקַט\">לָקַט</a>; a. v. fr.—<span dir=\"rtl\">מ׳ דתימא</span> what is it you might think?, i.e. you might be under the impression. <span class=\"citation\">Arakh. 21ᵇ</span> <span dir=\"rtl\">מ׳ ד׳ בטולי וכ׳</span> you might assume that he annulled (the protest), therefore we are given to understand &amp;c., v. <a href=\"#\" data-headword=\"פְּשִׁיטָא\">פְּשִׁיטָא</a>; a. fr.</div>","alt":[]},"17324":{"h":"מְהוֹבִית","r":"M00348","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹאֲבִיתָא\">מוֹהֲבִיתָא</a></div>","alt":["מְהוּבְתָּא"]},"17325":{"h":"מהוכיא","r":"M00349","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָחוֹךְ II\"><span dir=\"rtl\">מָחוֹךְ</span> II</a></div>","alt":[]},"17326":{"h":"מָהוֹלָא","r":"M00350","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מְהַל I) <i>circumciser</i>. <span class=\"citation\">Sabb. 156ᵃ</span>.—Pl. <span dir=\"rtl\">מְהוֹלָאֵי</span>. <span class=\"citation\">Ib. 135ᵃ</span></div>","alt":["מוֹהֲלָא"]},"17327":{"h":"מְהוּלָא I","r":"M00351","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"מְהוּלְתָּא I\"><span dir=\"rtl\">מְהוּלְתָּא</span> II</a>. <span class=\"citation\">Keth. 8ᵃ</span> <a href=\"#\" data-headword=\"מְשָׁכָא\">בי מ׳</a> a festival of circumcision.</div>","alt":[]},"17328":{"h":"מְהוּלָא II","r":"M00352","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְהַל\">נְהַל</a>) <i>sieve.</i> <i>—</i> Pl. <span dir=\"rtl\">מְהוּלַיָּיא</span>. Y. M. Kat. I, 81ᵇ top <span dir=\"rtl\">הורי באילין מ׳ וכ׳</span> permitted to make sieves during the festive week for the use on the Festival.</div>","alt":[]},"17329":{"h":"מְהוּלְתָּא I","r":"M00353","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מְהוּלָא II\">same</a>. <span class=\"citation\">Gen. R. s. 81</span>, v. <a href=\"#\" data-headword=\"חֲרַשׁ\">חֲרַשׁ</a>; Tanḥ. Vayishl. 8, v. <a href=\"#\" data-headword=\"טְרַשׁ II\"><span dir=\"rtl\">טְרַשׁ</span> II</a>.—<span class=\"citation\">Bets. 29ᵇ</span> <span dir=\"rtl\">אגבא דמ׳</span> on an inverted sieve.—Pl. <a href=\"#\" data-headword=\"מְהוּלְתָּא\">מְהוּלָתָא</a>. Ib. <span class=\"citation\">M. Kat. 11ᵃ</span> <span dir=\"rtl\">למיגדל מ׳</span> to plait sieves (during the festive week), v. <a href=\"#\" data-headword=\"מְהוּלָא II\">preced.</a></div>","alt":[]},"17330":{"h":"מְהוּלְתָּא","r":"M00354","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מְהַל I) <i>circumcision; foreskin</i>. <span class=\"citation\">Targ. Ex. IV, 25</span>, sq. (O. ed. Berl. <a href=\"#\" data-headword=\"מֻהְלְתָא\">מֻהְלְתָא</a>). <span class=\"citation\">Targ. Y. Gen. XLV, 4</span>; a. e.</div>","alt":["מָ׳ II"]},"17331":{"h":"מְהוּמָה","r":"M00355","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>commotion, trouble.</i> <span class=\"citation\">Ab. V, 8</span> <span dir=\"rtl\">רעב של מ׳</span> a famine in consequence of (war) trouble. <span class=\"citation\">Koh. R. to XII, 12</span> <span dir=\"rtl\">מֵהֵמָּה מ׳ שכל … מ׳ הוא וכ׳</span> for <i>mehemmah</i> (ib.) read <i>m’hummah</i>, for whosoever brings more than the twenty four Biblical books to his house, brings trouble &amp;c.; a. e. [<span class=\"citation\">Nidd. 4ᵃ</span> <span dir=\"rtl\">המהומה׳</span>, v. <a href=\"#\" data-headword=\"מָהָה\">מָהָה</a>.]</div>","alt":["מְהוּמָּה"]},"17332":{"h":"מְהוּמְתָּא","r":"M00356","html":"<div class=\"sense\"> . <span class=\"citation\">Targ. Esth. I, 10</span>.</div>","alt":[]},"17333":{"h":"מָהַט","r":"M00357","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָחַט\">מָחַט</a></div>","alt":[]},"17334":{"h":"מָהִיא","r":"M00358","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָה\">מָה</a> ch.</div>","alt":[]},"17335":{"h":"מְהִיבָא","r":"M00359","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹהֲבָא\">מוֹהֲבָא</a></div>","alt":["(מהיכא)"]},"17336":{"h":"מֵהֵיכָא","r":"M00360","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֵיכָא\">הֵיכָא</a></div>","alt":[]},"17337":{"h":"מְהִילָא","r":"M00361","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מְהַל I) <i>circumcision</i>. <span dir=\"rtl\">בר מ׳</span> fit for circumcision. <span class=\"citation\">Yeb. 71ᵃ</span></div>","alt":[]},"17338":{"h":"מְהִימַן","r":"M00362","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֵימַן\">הֵימַן</a></div>","alt":[]},"17339":{"h":"מָהִיר I","r":"M00363","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>quick</i>, v. <a href=\"#\" data-headword=\"מָהִר\">מָהִר</a>.</div>","alt":[]},"17340":{"h":"מָהִיר II","r":"M00364","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>mahir</i>, a fabulous animal of gigantic dimensions. <span class=\"citation\">Y. Ab. Zar. I, 39ᵈ</span> bot. [read:] <span dir=\"rtl\">מהו מותר לגדל א&quot;ר בא כגון מ׳ שהוא וכ׳</span> is it permitted to raise animals (in Palestine)? Says R. Ba, Even an animal like <i>mahir</i> &amp;c.; <span class=\"citation\">Y. Pes. IV, 30ᵈ</span> bot. (corr. acc.); <span class=\"citation\">Y. B. Kam. VII, end, 6ᵃ</span> (out of place).</div>","alt":[]},"17341":{"h":"מְהִירוּת","r":"M00365","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מָהִיר I) <i>quickness, speed</i>. <span class=\"citation\">Gen. R. s. 10</span>, oppos. <a href=\"#\" data-headword=\"מְתִינוּת\">מתינות</a>.</div>","alt":[]},"17342":{"h":"מהַל","r":"M00366","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"מוּל\">מוּל</a>) <i>to circumcise</i>. <span class=\"citation\">Y. Yeb. VIII, 8ᵈ</span> top <span dir=\"rtl\">על מנת למוֹהֲלָן</span> with the condition that he will circumcise them. Ib. bot. <span dir=\"rtl\">את מוֹהֲלוֹ בע&quot;כ</span> thou must circumcise him (the slave) even against his will. <span class=\"citation\">Gen. R. s. 46</span>. <span class=\"citation\">Cant. R. to I, 12</span>; a. fr.—Part. pass. <span dir=\"rtl\">מָהוּל</span>. <span class=\"citation\">Yeb. 71ᵃ</span> v. <a href=\"#\" data-headword=\"גִּבְעוֹנִי\">גִּבְעוֹנִי</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\"><span dir=\"rtl\">נולד</span> (<span dir=\"rtl\">כשהוא</span>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a></span> born without a prepuce; a. fr.</div>","alt":[]},"17343":{"h":"מְהַל I","r":"M00367","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מהַל\">same</a>. <span class=\"citation\">Yeb. 71ᵇ</span> <span dir=\"rtl\">ובמדבר מ&quot;ט לא מָהוּל</span> and why did they not practice circumcision in the desert? <span class=\"citation\">Ib. 72ᵃ</span> <span dir=\"rtl\">לא מַהֲלִינָן ביה</span> we do not perform the operation on it (a cloudy day &amp;c.). <span class=\"citation\">Sabb. 134ᵃ</span> ולִימְהֲלֵיה Ms. M. (ed. <span dir=\"rtl\">ולִימְהֲלוּהָ</span>, v. Rabb. D. S. a. l. note) and then one (they) shall circumcise him. <span class=\"citation\">Ib. 136ᵃ</span> <span dir=\"rtl\">מִימְהַל היכי מַהֲלִינָן ליה</span> how dare we circumcise him (on the Sabbath)? Ib. <span dir=\"rtl\">נִימְהֲלֵיה ממ&quot;נ</span> let us circumcise him at all events (v. <a href=\"#\" data-headword=\"מָה\">מָה</a> h.); a. fr.—Part. <span dir=\"rtl\">מָהֵיל</span>. Ib.; a. fr.</div><div class=\"sense\"><b>—2)</b>  (neut. verb) <i>to be circumcised</i>. <span class=\"citation\">Snh. 39ᵃ</span> <span dir=\"rtl\">אנן דמהלינן וכ׳</span> we who are circumcised cannot become like you; <span dir=\"rtl\">אתון מַהֲלִיתוּ וכ׳</span> (Ms. M. <span dir=\"rtl\">מיהלן</span>, read <span dir=\"rtl\">מְהִילוּ</span>) have yourselves circumcised and be like us.</div>","alt":[]},"17344":{"h":"מְהַל II","r":"M00368","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מָהָה\">מהה</a>, a. <span dir=\"rtl\">מחל</span>; cmp. <span class=\"citation\">Is. I, 22</span>), <i>Af</i>. <span dir=\"rtl\">אַמְהֵיל</span> <i>to attenuate, dilute</i>. Pesik. Ekhah, p. 122ᵇ (ref. to Is. l. c.) <span dir=\"rtl\">הַמְהֵיל ליה</span> dilute it (the wine); <span class=\"citation\">Yalk. Is. 258</span> <span dir=\"rtl\">אַמְהֵיל</span>.—V. <a href=\"#\" data-headword=\"מוֹהַל\">מוֹהַל</a>.</div>","alt":[]},"17345":{"h":"מְהַלֵיךְ","r":"M00369","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַהֲלַךְ\">מַהֲלַךְ</a></div>","alt":[]},"17346":{"h":"מַהֲלָךְ","r":"M00370","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>way, journey, diurnal distance</i>. <span class=\"citation\">Ḥag. 13ᵃ</span> <span dir=\"rtl\">מ׳ חמש וכ׳</span> a journeying distance of five hundred years; <span class=\"citation\">Pes. 94ᵇ</span>; <span class=\"citation\">Y. Ber. I, 2ᶜ</span> bot.; a. fr.</div>","alt":[]},"17347":{"h":"מַהֲלַךְ","r":"M00371","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jonah III, 3</span>, sq. <span class=\"citation\">Targ. Y. Ex. XII, 31</span>.</div>","alt":["(מְהַלֵיךְ)"]},"17348":{"h":"מֻהְלְתָא","r":"M00372","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְהוּלְתָּא I\"><span dir=\"rtl\">מְהוּלְתָּא</span> II</a></div>","alt":[]},"17349":{"h":"מַהֲמוֹרוֹת","r":"M00373","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>debris, mounds</i> used as burying places for executed criminals. <span class=\"citation\">Y. M. Kat. I, 80ᶜ</span> bot. <span dir=\"rtl\">בראשונה … במ׳</span> in former days they buried them (the convicts) in mounds (while later on special places were provided for them; v. <span class=\"citation\">Snh. VI, 5</span>); Y. Snh. VI, 23ᵈ bot. <span dir=\"rtl\">במח׳</span> (correct the entire passage in accordance with Y. M. Kat. l. c.).</div>","alt":["מַחֲ׳"]},"17350":{"h":"מַהֲמוֹרִין","r":"M00374","html":"<div class=\"sense\"> m. ch. <a href=\"#\" data-headword=\"מַהֲמוֹרוֹת\">same</a>. <span class=\"citation\">Targ. Ps. CXL, 11</span> Regia (ed. <span dir=\"rtl\">מַחְמְרִין</span>).</div>","alt":[]},"17351":{"h":"מַהָן","r":"M00375","html":"<div class=\"sense\"> = <span dir=\"rtl\">מַאן הָן</span>. <span class=\"citation\">Y. Shebi. IV, 35ᵃ</span> bot. <span dir=\"rtl\">מ׳ מודע וכ׳</span> (<span class=\"citation\">Y. Snh. III, 21ᵇ</span> <span dir=\"rtl\">מאן</span>) who told thee &amp;c.?—[<span class=\"citation\">Y. Erub. V, end 23ᵃ</span>, read <span dir=\"rtl\">אחורי הגנין מַהוּ</span>.]</div>","alt":[]},"17352":{"h":"מַהְפֶּיכְתָּא","r":"M00376","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲפֵכְתָּא\">הֲפֵכְתָּא</a></div>","alt":[]},"17353":{"h":"מְהַפְּכָנָא","r":"M00377","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲפַךְ\">הֲפַךְ</a>) <i>perverse</i>. <span class=\"citation\">Targ. Prov. XVI, 28</span>.</div>","alt":[]},"17354":{"h":"מְהַפְכָנוּתָא","r":"M00378","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נֶהְפְּכָנוּתָא\">נֶהְפְּכָנוּתָא</a></div>","alt":[]},"17355":{"h":"מָהַר","r":"M00379","html":"<div class=\"sense\"><i>to exchange, buy</i>. Denom. <a href=\"#\" data-headword=\"מוֹהַר\">מוֹהַר</a>.</div><div class=\"sense\"><b>Pi. מִהֵר</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָלַף\">חָלַף</a>) </div><div class=\"sense\"><b>1)</b> <i>to hurry, be speedy</i>. <span class=\"citation\">Sabb. 97ᵃ</span> <span dir=\"rtl\">מְמַהֶרֶת לבוא וכ׳</span> comes quicker than &amp;c. <span class=\"citation\">B. Kam. 93ᵃ</span> <span dir=\"rtl\">מְמַהֲרִין לצועק וכ׳</span> he who cries for revenge will sooner be punished than he who is cried against. <span class=\"citation\">Sifré Deut. 277</span> מְמַהֵר אני ליפרע ע&quot;י עני I (the Lord) will sooner take revenge when a poor man is wronged than when a rich man is; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to expedite</i>. <span class=\"citation\">Kidd. 31ᵇ</span> <span dir=\"rtl\">מַהֲרוּנִי</span> expedite me (on my journey).</div></div>","alt":[]},"17356":{"h":"מֹהַר","r":"M00380","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹהַר\">מוֹהַר</a></div>","alt":[]},"17357":{"h":"מָהִר","r":"M00381","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מֹהַר\">preced. art.</a>) <i>quick, ready.</i> <span class=\"citation\">Ab. V, 12</span> <span dir=\"rtl\">מ׳ לשמוע ומ׳ לאבד</span> quick of perception and quick to forget. <span class=\"citation\">Ex. R. s. 11</span>, beg.; a. e.</div>","alt":["מָהִיר"]},"17358":{"h":"מְהֵרָה","r":"M00382","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מָהִר\">preced.</a>) <i>speed;</i> בִּמְ׳ <i>speedily</i>, <i>easily.</i> <span class=\"citation\">Ab. V, 20</span> <span dir=\"rtl\">במ׳ בימינו</span> soon, in our life-time. <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">מ׳ הפר וכ׳</span> soon destroy their counsel. <span class=\"citation\">Ned. 20ᵃ</span> <span dir=\"rtl\">לא במ׳ הוא חוטא</span> will not easily be led to sin; a. e.</div>","alt":[]},"17359":{"h":"מוֹאָב","r":"M00383","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (b. h.) <i>Moab</i>, son of Lot; <i>the Moabite people</i>. <span class=\"citation\">Gen. R. s. 51</span>, end <span dir=\"rtl\">בזכות מ׳ מי אב</span> through the merits of Moab, that is <i>mi ab</i>, of him who is called father (Abraham). <span class=\"citation\">Num. R. s. 20</span> נתחברו מ׳ עם מדין Moab and Midian formed an alliance; a. fr.—<span class=\"citation\">Targ. Y. Num. XXV, 15</span>. <span class=\"citation\">Targ. Gen. XIX, 37</span>; a. fr.</div>","alt":[]},"17360":{"h":"מואבא","r":"M00384","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹאֲבאָה\">next w.</a></div>","alt":[]},"17361":{"h":"מוֹאֲבאָה","r":"M00385","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. O. Num. XXII, 3</span> (Y. <a href=\"#\" data-headword=\"מואבא\">מואבא</a>, read: … <a href=\"#\" data-headword=\"אִי II\">אֵי</a>); a. e.—Pl. <span dir=\"rtl\">מוֹאֲבָאֵי</span>, <span dir=\"rtl\">מוֹאָ׳</span>. <span class=\"citation\">Targ. Gen. XIX, 37</span>. <span class=\"citation\">Targ. Deut. XXIII, 4</span>; a. e.—<i>Fem</i>. <a href=\"#\" data-headword=\"מוֹאֲבִיתָא\">מוֹאֲבִיתָא</a>. <span class=\"citation\">Targ. Ruth IV, 5</span>; a. e.</div>","alt":[]},"17362":{"h":"מוֹאָבִי","r":"M00386","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Moabite</i>. <span class=\"citation\">Yeb. VIII, 3</span> <span dir=\"rtl\">עמוני ומ׳ אסורים וכ׳</span> marriage with an Ammonite or a Moabite is forbidden and the prohibition continues forever (with reference to their descendants; <span class=\"citation\">Deut. XXIII, 4</span>); a. fr.—Pl. <a href=\"#\" data-headword=\"מוֹאָבִי\">מוֹאָבִים</a>, <span dir=\"rtl\">מוֹאָבִיִּים</span>, <span dir=\"rtl\">מוֹאָבִיִּין</span>. <span class=\"citation\">Num. R. s. 20</span>. <span class=\"citation\">Gen. R. s. 74</span>; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"מוֹאָבִי\">מוֹאָבִית</a>. <span class=\"citation\">Yeb. 69ᵃ</span>, a. e. (ref. to Deut. l. c.) <span dir=\"rtl\">מואבי ולא מ׳</span> a male Moabite is excluded from intermarriage but not a female.</div>","alt":[]},"17363":{"h":"מוֹאֲבִיתָא","r":"M00387","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹאֲבאָה\">מוֹאֲבָאָה</a></div>","alt":[]},"17364":{"h":"מוֹאדְנָוָון","r":"M00388","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹדָנָא\">מוֹדָנָא</a></div>","alt":["מוֹאדְנִין","מוֹאַדְנִין"]},"17365":{"h":"מוּבָאת","r":"M00389","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (part. Hof. of <a href=\"#\" data-headword=\"בּוֹא\">בּוֹא</a>; cmp. <span class=\"citation\">Ex. XXVII, 7</span>) <i>wedged into, exact size of.</i> <span class=\"citation\">Neg. VI, 6</span> <span dir=\"rtl\">כעדשה מ׳</span> (Ar. <a href=\"#\" data-headword=\"מוּבָת\">מובת</a>) exactly the size of a lentil; Tosef. ib. II, 10 quot. in R. S. to Neg. l. c. (ed. Zuck. <span dir=\"rtl\">מְכוּוֶּנֶת</span>, v. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>).</div>","alt":[]},"17366":{"h":"מוֹבְדָנָא","r":"M00390","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יוּבְדָּנָא\">יוּבְדָנָא</a></div>","alt":[]},"17367":{"h":"מובילותא","r":"M00391","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹבִילְתָּא\">next w.</a></div>","alt":["מובילי׳"]},"17368":{"h":"מוֹבִילְתָּא","r":"M00392","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְבַל\">יְבַל</a>) <i>load</i>. <span class=\"citation\">Gen. R. s. 80</span> <span dir=\"rtl\">טעין מוֹבִילְתֵּיה</span> carrying his load (to market). <span class=\"citation\">Gen. R. s. 70</span> <span dir=\"rtl\">ואם הוות מוֹבִילְתֵּיה וכ׳</span> (not <span dir=\"rtl\">מובילו׳</span>, <a href=\"#\" data-headword=\"מובילותא\">מובילי׳</a>) and if his load was worth two &amp;c., v. <a href=\"#\" data-headword=\"פּוֹלָר\">פּוֹלָר</a>.</div>","alt":[]},"17369":{"h":"מוּבָל","r":"M00393","html":"<div class=\"sense\"> c. <a href=\"#\" data-headword=\"מוֹבִילְתָּא\">same</a>. <span class=\"citation\">Y. Ḥall. IV, end, 60ᵇ</span>; Y. Dem. III, 23ᵇ bot. <span dir=\"rtl\">מי׳</span> (corr. acc.). <span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot. <span dir=\"rtl\">יהב גולתה מרום מוּבְלֵה</span> he put his cloak over his load. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a>, beg. <span dir=\"rtl\">מ׳ דקיסין</span> a load of wood; a. fr.—Pl. <span dir=\"rtl\">מוּבְלֵי</span>. Ib. introd. (R. Joh. 1), v. <a href=\"#\" data-headword=\"טְעוּנָא\">טְעוּנָא</a></div>","alt":["מוּבְלָא"]},"17370":{"h":"מוּבָת","r":"M00394","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּבָאת\">מוּבָאת</a></div>","alt":[]},"17371":{"h":"מוּג","r":"M00395","html":"<div class=\"sense\"> h. <a href=\"#\" data-headword=\"מוּג\">מוּג</a>, <i>to melt</i>.</div><div class=\"sense\"><b>Af. אָמֵיג</b> <div class=\"sense\"><i>to cause to flow, to make sore</i>. <span class=\"citation\">Gen. R. s. 41</span> (ref. to <span dir=\"rtl\">מוגיך</span>, <span class=\"citation\">Is. LI, 23</span>) <span dir=\"rtl\">אילן דמְמִיגִין מכתך</span> (Ar. <span dir=\"rtl\">דמְמַגְיַין מחתך</span>, fr. <a href=\"#\" data-headword=\"מְגֵי\">מגי</a>), v. <a href=\"#\" data-headword=\"לַחְלַח\">לַחְלַח</a>; ib. s. 69; <span class=\"citation\">Yalk. Is. 337</span> <span dir=\"rtl\">אילין דמגיין ביך</span> (some ed. <span dir=\"rtl\">מוניך … דמניין</span>, corr. acc.).—V. <a href=\"#\" data-headword=\"מוּגְלָא\">מוּגְלָא</a>.</div></div><div class=\"sense\"><b>*. אִתְמוֹגֵג</b> <div class=\"sense\"> (v. Syr. <span dir=\"rtl\">מגיא</span>, P. Sm. 2001) <i>to be languid, to act like a languid person</i>. <span class=\"citation\">Ab. Zar. 70ᵇ</span> בעלמא הוא דקאִיתְמוֹגֵג Ms. M. Var. (not <span dir=\"rtl\">איתמוגגי</span>; strike out <span dir=\"rtl\">בעלמא הוא דקמתמוגג</span> as a tautography) he may say, I was only a little lazy (and stretched myself so as to reach over to the neighbor’s roof; Rashi a. l. quotes a Var. <span dir=\"rtl\">מתמוגג אני</span> h.).</div></div>","alt":[]},"17372":{"h":"מוֹג","r":"M00396","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָגַג\">מָגַג</a>) a <i>melting substance, wax</i> (?). <span class=\"citation\">Pesik. R. s. 33</span> (play on <span dir=\"rtl\">אלמוג׳</span>, <span class=\"citation\">II Chr. II, 7</span>) <span dir=\"rtl\">היו כמ׳ הזה</span> the hard blocks became soft like <i>mog</i>, v. <a href=\"#\" data-headword=\"שָׁמִיר\">שָׁמִיר</a>.</div>","alt":[]},"17373":{"h":"מוּגְדְּלָא","r":"M00397","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִגְדַּל\">מִגְדַּל</a></div>","alt":[]},"17374":{"h":"מוגורות","r":"M00398","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹגֵרָה\">מוֹגֵרָה</a></div>","alt":["מוֹגֵירָה"]},"17375":{"h":"מוּגְלָא","r":"M00399","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מוּג\">מוּג</a>; cmp. <a href=\"#\" data-headword=\"מוֹהַל\">מוֹהַל</a>) <i>pus, tenacious matter</i>. <span class=\"citation\">Ḥull. 48ᵃ</span> <span dir=\"rtl\">מליא מ׳</span> if the abscess in the kidneys is full of matter, opp. <span dir=\"rtl\">מים זכים</span>. <span class=\"citation\">Ib. 55ᵇ</span>. <span class=\"citation\">Yeb. 75ᵇ</span> <span dir=\"rtl\">ונפק מיניה כחוט דמ׳ וכ׳</span> (Ar. <span dir=\"rtl\">ונפק מיניה מ׳</span>) and there came out of the wound something like a thread of pus, and yet he begot children afterwards.</div>","alt":[]},"17376":{"h":"*מוּגְלְסָא","r":"M00400","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלַל\">גְּלַל</a> with format. <a href=\"#\" data-headword=\"ס\">ס</a>; cmp. <a href=\"#\" data-headword=\"גִּלָּה\">גִּלָּה</a>, <a href=\"#\" data-headword=\"סְגַלְגַּל\">סְגַלְגַּל</a>) <i>pivot, hinge</i>.—Pl. <span dir=\"rtl\">מוּגְלְסַיָּא</span>. <span class=\"citation\">Targ. I Kings VII, 50</span> (h. text <span dir=\"rtl\">פֹּתוֹת</span>).</div>","alt":[]},"17377":{"h":"מוּגְמָר","r":"M00401","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"גּוּמְרָא\">גּוּמְרָא</a>, a. <a href=\"#\" data-headword=\"גָּמַר I\"><span dir=\"rtl\">גָּמַר</span> I</a>) <i>spices put on coals</i>, offered after dinner, <i>perfume</i>. <span class=\"citation\">Ber. VI, 6</span>. Y. ib. 10ᵈ <span dir=\"rtl\">מ׳ כיון שהעלה עשן וכ׳</span> as soon as the smoke rises from the burning spices &amp;c.; a. fr.—<span class=\"citation\">Sabb. 18ᵃ</span> <span dir=\"rtl\">מניחין מו׳</span>; Y. ib. I, 4ᵃ top <span dir=\"rtl\">נותנין מג׳</span>, v. <a href=\"#\" data-headword=\"גָּמַר I\"><span dir=\"rtl\">גָּמַר</span> I</a>.—Pl. <span dir=\"rtl\">מוּגְמָרוֹת</span>. <span class=\"citation\">Ber. 43ᵃ</span></div>","alt":["מָגְמָר"]},"17378":{"h":"מוגמרין","r":"M00402","html":"<div class=\"sense\">, <span class=\"citation\">Y. Keth. IX, 33ᵇ</span> bot. <span dir=\"rtl\">דין מ׳</span>, v. <a href=\"#\" data-headword=\"דִּיאֲטַגְמָא\">דִּיאֲטַגְמָא</a></div>","alt":[]},"17379":{"h":"מוֹגֵרָה","r":"M00403","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אָגַר I) <i>storage, stored up provision, magazine</i>.—Pl. <span dir=\"rtl\">מוֹגֵרוֹת</span>. <span class=\"citation\">Tosef. Dem. I, 10</span> he who buys <span dir=\"rtl\">מן המוֹגֵירוֹת בצידון</span> ed. Zuck. (Var. <span dir=\"rtl\">מְגֵר׳</span>, <a href=\"#\" data-headword=\"מגרת\">מגרת</a>) from the stores in Zidon; Y. ib. I, 22ᵃ bot. <a href=\"#\" data-headword=\"מְגוֹרֶת\">מְגוֹרֶת</a>. Tosef. l. c. <span dir=\"rtl\">מוגורות בצור</span> ed. Zuck. (Var. <span dir=\"rtl\">מוגירות</span>, <span dir=\"rtl\">מְגוֹרוֹת</span>; Y. l. c. <a href=\"#\" data-headword=\"מְגוֹרֶת\">מגורת</a>), opp. <a href=\"#\" data-headword=\"חַמֶּרֶת\">חַמֶּרֶת</a>.</div>","alt":["מוֹגֶרֶת"]},"17380":{"h":"מוּגְרֶמֶת","r":"M00404","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גָּרַם\">גָּרַם</a></div>","alt":[]},"17381":{"h":"מוֹגֶרֶת","r":"M00405","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹגֵרָה\">מוֹגֵרָה</a></div>","alt":[]},"17382":{"h":"מוּד","r":"M00406","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מָדַד\">מָדַד</a>) [<i>to stretch one’s self</i>,] <i>to swim</i>. <span class=\"citation\">Gitt. 67ᵇ</span> <span dir=\"rtl\">ולֵימוּד</span> and let him swim.</div>","alt":[]},"17383":{"h":"מודגראות","r":"M00407","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ps. 656</span>, v. <a href=\"#\" data-headword=\"כְּרִיסוֹ\">כְּרִיסוֹ</a></div>","alt":[]},"17384":{"h":"מוֹדְיָא","r":"M00408","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (modius) <i>modius</i>, a Roman dry measure, corresp. to <a href=\"#\" data-headword=\"סְאָה\">סְאָה</a>. <span class=\"citation\">Gitt. 57ᵃ</span>.—Pl. <span dir=\"rtl\">מוֹדְיוֹת</span>. Ib. Y. Maasr. IV, 51ᵇ bot. <span dir=\"rtl\">מוֹדָייוֹת</span>. <span class=\"citation\">Num. R. s. 4</span>, beg. <span dir=\"rtl\">מוֹדְיָאוֹת</span>.</div>","alt":["מוֹדְיָיה"]},"17385":{"h":"מוֹדְיָא ²","r":"M00409","html":"<div class=\"sense\"> ch. m. <a href=\"#\" data-headword=\"מוֹדְיָא\">same</a>. <span class=\"citation\">Esth. R. to I, 4</span> <span dir=\"rtl\">חד מ׳ דדינרין</span> a modius of denars; Y. Pes. lV, end, 31ᶜ <span dir=\"rtl\">מודיי</span> (read <span dir=\"rtl\">מודיי׳</span>). Ib. III, 30ᵃ top, v. <a href=\"#\" data-headword=\"טִיטַרְטוֹן\">טִיטַרְטוֹן</a>. <span class=\"citation\">Erub. 83ᵃ</span>, v. <a href=\"#\" data-headword=\"*נָאוּסָא\">נָאוּסָא</a>.—Pl. <span dir=\"rtl\">מוֹדְיֵי</span>. <span class=\"citation\">Y. B. Kam. IX, 6ᵈ</span>, sq. [<span dir=\"rtl\">מודיי</span>, frequ. in Talm. Y. for <span dir=\"rtl\">מוֹדִין</span>, v. <a href=\"#\" data-headword=\"יְדִי\">יְדִי</a>.]</div>","alt":["מוֹדְיָיה"]},"17386":{"h":"מוֹדִים","r":"M00410","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Modim</i>, the last but third section of the Prayer of Benedictions, so called from its beginning <span dir=\"rtl\">מ׳ אנחנו</span> (we offer thanks). <span class=\"citation\">Ber. V, 3</span> (a reader who says) <span dir=\"rtl\">מ׳ מ׳ וכ׳</span> <i>modim</i> twice must be silenced; <span class=\"citation\">Meg. IV, 9</span> (<span class=\"citation\">25ᵃ</span>). <span class=\"citation\">Y. Ber. II, 5ᵃ</span> bot. <span dir=\"rtl\">כד הוה מטי מ׳</span> when it comes to <i>modim</i>; a. e.</div>","alt":[]},"17387":{"h":"מוֹדִיעַ","r":"M00411","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָדַע\">יָדַע</a>) <i>mark, mnemotechnical sign</i>.—Pl. <a href=\"#\" data-headword=\"מוֹדִיעִים\">מוֹדִיעִים</a>, <a href=\"#\" data-headword=\"מוֹדִיעִים\">מוֹדִיעִין</a>. <span class=\"citation\">Erub. 54ᵇ</span> bot. (play on <span dir=\"rtl\">מודע</span>, <span class=\"citation\">Prov. VII, 4</span>) <span dir=\"rtl\">עשה מ׳ לתורה</span> ed. Sonc. (ed. <a href=\"#\" data-headword=\"מוֹדָעִים\">מודעים</a>, v. Rabb. D. S. a. l. note 8) make mnemonical symbols for the study of the Law; <span class=\"citation\">Yalk. Prov. 940</span>; <span class=\"citation\">Yalk. Jer. 315</span>.</div>","alt":[]},"17388":{"h":"מוֹדִיעִים","r":"M00412","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"מוֹדָעִים\">מוֹדָעִים</a></div>","alt":["מוֹדִיעִית"]},"17389":{"h":"מוֹדְלָא","r":"M00413","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"מְדִל\">מִדְלָא</a>. <span class=\"citation\">Targ. Prov. XXIX, 3</span> Ms.; <span class=\"citation\">ib. XXVIII, 8</span> <a href=\"#\" data-headword=\"מִדַּעַם\">מיד׳</a>; <span class=\"citation\">ib. VI, 31</span> מיד׳ Ar. (ed. everywhere <span dir=\"rtl\">מַוָּל׳</span>; h. text <a href=\"#\" data-headword=\"הַוָּן\">הוֹן</a>).</div>","alt":[]},"17390":{"h":"מוּדְלֶה","r":"M00414","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מוּדְלֶה\">מוּדְלָה</a> f. </div><div class=\"sense\"><b>1)</b>  part. <i>Hof</i>. of <a href=\"#\" data-headword=\"דָּלָה\">דָּלָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>gourd-field</i>, v. <a href=\"#\" data-headword=\"מִדְלַעַת\">מִדְלַעַת</a>.</div>","alt":[]},"17391":{"h":"מוּדְלִית","r":"M00415","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דָּלָה\">דָּלָה</a>) <i>hanging fruits</i>. <span class=\"citation\">B. Mets. 91ᵇ</span>, v. <a href=\"#\" data-headword=\"דָּלָה\">דָּלָה</a>.</div>","alt":[]},"17392":{"h":"מוֹדָנָא","r":"M00416","html":"<div class=\"sense\"> c. (denom. of <a href=\"#\" data-headword=\"אוֹדֶן\">אוּדְנָא</a>; v. <a href=\"#\" data-headword=\"מוֹזְנָוָון\">מוֹזְנָוָון</a>) <i>scale</i>. <span class=\"citation\">Targ. Y. Ex. I, 15</span>.—Pl. <a href=\"#\" data-headword=\"מֹאדְנִין\">מֹאדְנִין</a>. <span class=\"citation\">Targ. Koh. II, 8</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"מוֹאדְנָוָון\">מוֹאדְנִין</a>, <span dir=\"rtl\">מוֹאַדְ׳</span>). <span class=\"citation\">Targ. Y. Lev. XIX, 36</span> <a href=\"#\" data-headword=\"מוֹאדְנָוָון\">מוֹדְנָוָון</a> (not <span dir=\"rtl\">מורג׳</span>).</div>","alt":[]},"17393":{"h":"מוֹדָעָא","r":"M00417","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְדַע\">יְדַע</a>) <i>declaration</i>, esp. <i>protest</i> before witnesses against a forced or unduly influenced action. <span class=\"citation\">B. Bath. 40ᵃ</span> <span dir=\"rtl\">לא כתבינן מ׳ אלא אמאן וכ׳</span> we write a protest only against a person who does not submit to law. <span class=\"citation\">Ib. 40ᵇ</span> <span dir=\"rtl\">הויא מ׳ לחברתה</span> the order to write a deed of donation in secret is a protest annulling a subsequent disposal by deed. <span class=\"citation\">Ib. 49ᵃ</span> <span dir=\"rtl\">מ׳ היו דברינו</span> if witnesses subscribed to a deed say, We signed after the owner had entered a verbal protest before us against the deed; a. fr.</div>","alt":[]},"17394":{"h":"מוֹדָעִי","r":"M00418","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מוֹדָעִים\">next w.</a>) <i>of Modim</i>, esp. (<span dir=\"rtl\">ר׳ אלעזר</span>) <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> R. El. of Modim. <span class=\"citation\">Ab. III, 11</span>; a. fr.—<span class=\"citation\">Sabb. 55ᵇ</span>; <span class=\"citation\">B. Bath. 10ᵇ</span> <span dir=\"rtl\">עדיין אנו צריכין לַמּ׳</span> we still need the Modite (for interpretation).</div>","alt":[]},"17395":{"h":"מוֹדָעִים","r":"M00419","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Modaim, Modim, Modin</i>, the native place of the Asmonean family. [Eds. a. Mss. vary between <span dir=\"rtl\">מוֹדָע׳</span>, <a href=\"#\" data-headword=\"מוֹדִיעַ\">מוֹדִיע׳</a> a. <a href=\"#\" data-headword=\"מוֹדִיעִים\">מוֹדִיעִית</a>.] <span class=\"citation\">Kidd. 66ᵃ</span>. <span class=\"citation\">Pes. IX, 2</span>. <span class=\"citation\">Ib. 93ᵇ</span> <span dir=\"rtl\">מן המ׳ ולירושלם וכ׳</span> from M. to Jerusalem are fifteen miles. <span class=\"citation\">Ḥag. III, 5</span>; <span class=\"citation\">Tosef. ib. III, 33</span>; a. fr.—[<a href=\"#\" data-headword=\"מוֹדָעִים\">מודעים</a>, <span class=\"citation\">Erub. 54ᵇ</span>, v. <a href=\"#\" data-headword=\"מוֹדִיעַ\">מוֹדִיעַ</a>.]</div>","alt":["מוֹדָעִין"]},"17396":{"h":"מוֹדַעַת","r":"M00420","html":"<div class=\"sense\"> f. (b. h.; <i>acquaintance</i>; trnsf. (m.) <i>friend</i>. <span class=\"citation\">Y. Peah IV, beg. 18ᵃ</span> שלא יראה לעני מוֹדַעְתּוֹ וכ׳ R. S. to <span class=\"citation\">Peah IV, 1</span> (ed. <span dir=\"rtl\">מֹדַעְתּוֹ</span>) that he may not see a poor man who is his friend and cast it before him.</div>","alt":[]},"17397":{"h":"מוּדְרוֹן","r":"M00421","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַדְרוֹן\">מַדְרוֹן</a></div>","alt":[]},"17398":{"h":"מוּדְרְקָא","r":"M00422","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרְדְּקָא\">מוּרְדְּקָא</a></div>","alt":[]},"17399":{"h":"מוֹהָא","r":"M00423","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹי\">מוֹי</a></div>","alt":[]},"17400":{"h":"מוֹהֲבָא","r":"M00424","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְהַב\">יְהַב</a>) <i>gift</i>. <span class=\"citation\">Targ. Prov. XXI, 14</span>. <span class=\"citation\">Ib. VI, 35</span> (some ed. <a href=\"#\" data-headword=\"מְהִיבָא\">מהיכא</a>, read <a href=\"#\" data-headword=\"מְהִיבָא\">מהיבא</a>).—<i>Pl</i>. constr. <span dir=\"rtl\">מוֹהֲבֵי</span>. <span class=\"citation\">Targ. Y. I Deut. XVIII, 8</span> (not <span dir=\"rtl\">מותבי</span>).</div>","alt":[]},"17401":{"h":"מוֹהֲבוּתָא","r":"M00425","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מוֹהֲבָא\">same</a>. <span class=\"citation\">Targ. Prov. XVIII, 16</span>. <span class=\"citation\">Targ. Ps. XVI, 5</span> <a href=\"#\" data-headword=\"מוֹהֲבוּתָא\">מוֹהֲבִית</a> constr. (Ms. <span dir=\"rtl\">מְהוֹבִ׳</span>). <span class=\"citation\">Targ. Y. Deut. XVI, 17</span> <span dir=\"rtl\">מוהבות</span>; a. e.—Pl. <span dir=\"rtl\">מוֹהֲבִיָּתָא</span>. <span class=\"citation\">Targ. Prov. XV, 27</span> (some ed. sing.). <span class=\"citation\">Targ. Y. Deut. XVIII, 2</span> <a href=\"#\" data-headword=\"מוֹהֲבוּתָא\">מוהבותא</a> (corr. acc.).</div>","alt":["מוֹהֲבִי׳","מוֹהַבְתָּא"]},"17402":{"h":"מוֹהֶה","r":"M00426","html":"<div class=\"sense\">, a disguise of <a href=\"#\" data-headword=\"משֶׁה\">מֹשֶׁה</a>. <span class=\"citation\">Ned. I, 2</span> (<span class=\"citation\">10ᵃ</span>) <span dir=\"rtl\">נדר במ׳</span> (Mish. ed. <a href=\"#\" data-headword=\"בָּמוֹתָא\">במותא</a>, Bab. ed. <span dir=\"rtl\">נודר בסוהי</span>; corr. acc.) if one says, A vow by (that of) Mohi; Tosef. ib. I, 2 <span dir=\"rtl\">האומר מוחה ודאי מוחו</span> ed. Zuck. (Var. <span dir=\"rtl\">מוהי … מוהה</span>, <span dir=\"rtl\">מוהו</span>, a. <span dir=\"rtl\">ודאמר</span> for <a href=\"#\" data-headword=\"וַדַּאי\">ודאי</a>) read: <span dir=\"rtl\">האומר מ׳ ודאמר מ׳</span> if one says, (<i>Neder</i>) <i>Mohi</i>, or (<i>Neder</i>) <i>d’ămar Mohi</i>, the vow of M. or the vow which M. uttered; expl. Y. ib. I, 37ᵃ top [read:] <span dir=\"rtl\">בנדר דנדר מ׳ במומי דנדר משה וכ׳</span> by the vow which M. vowed, that means, by the oath which Moses vowed, as we read (<span class=\"citation\">Ex. II, 21</span>) &amp;c.; Bab. ib. 10ᵇ <span dir=\"rtl\">האומר במ׳ לא אמר כלום</span> if a person said, by Mohi, he said nothing, but if he says, by the oath which M. spoke &amp;c. Ib. 22ᵇ <span dir=\"rtl\">אי נדרת במ׳ וכ׳</span> if thou hadst vowed by M. (using the phrase <span dir=\"rtl\">נדר מ׳</span>) &amp;c.—[מוֹהִי <i>water</i>, v. <a href=\"#\" data-headword=\"מוֹי\">מוֹי</a>.]</div>","alt":["מוֹהִי"]},"17403":{"h":"מַוְהֵי","r":"M00427","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְחִי\">יְחִי</a></div>","alt":[]},"17404":{"h":"מוֹהַל","r":"M00428","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְהַל II\"><span dir=\"rtl\">מְהַל</span> II</a>) <i>a thin secretion</i>. <span class=\"citation\">Y. Naz. VII, 56ᵇ</span> <span dir=\"rtl\">המ׳ שקרש</span> the secretion (from a decaying corpse) which congealed, opp. <span dir=\"rtl\">עודהו מחוי</span> if it is still fluid. Ib. IX, 57ᵈ bot.; <span class=\"citation\">Y. B. Bath. V, beg. 15ᵃ</span>. [Mish. a. Tosef. <a href=\"#\" data-headword=\"מוֹחַל\">מוֹחַל</a>, q. v.]</div>","alt":[]},"17405":{"h":"מוֹהֵל","r":"M00429","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>circumciser</i>, v. <a href=\"#\" data-headword=\"מהַל\">מָהַל</a>.</div>","alt":[]},"17406":{"h":"מוֹהֲלָא","r":"M00430","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָהוֹלָא\">מָהוֹלָא</a></div>","alt":[]},"17407":{"h":"מוֹהַר","r":"M00431","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>exchange</i>, esp. <i>the price paid for the wife;</i> (in later practice) <i>the wife’s settlement, widowhood</i> <span dir=\"rtl\">(כתובה</span>). Mekh. Mishp., N’zikin, s. 17 (ref. to <span class=\"citation\">Ex. XXII, 15</span>) <span dir=\"rtl\">מלמד שהוא עוֹשָׂהּ עליו מ׳</span> this indicates that he (the father) imposes it upon him (the seducer) as a <i>mohar</i>; <span dir=\"rtl\">ואין מ׳ אלא כתובה וכ׳</span> and <i>mohar</i> means <i>k’thubah</i>, as we read (<span class=\"citation\">Gen. XXXIV, 12</span>) &amp;c.; <span class=\"citation\">Y. Keth. III, 27ᵈ</span> top (read <span dir=\"rtl\">אותה</span> for <span dir=\"rtl\">אותן</span>). Bab. <span class=\"citation\">Keth. 10ᵃ</span> (ref. to <span class=\"citation\">Ex. XXII, 16</span>) <span dir=\"rtl\">שיהא זה כמ׳ הבתולות וכ׳</span> that this (fine) be equal to the indemnity for outraged virginity (<span class=\"citation\">Deut. XXII, 29</span>), and the settlement of virgins be like this (indemnity, i.e. fifty Shekel silver); a. fr.—Pl. <a href=\"#\" data-headword=\"*מוֹהֲרִין\">מוֹהֲרִין</a>, constr. <span dir=\"rtl\">מוֹהֲרֵי</span>. Y. ib. III, beg. 27ᵃ [read:] <span dir=\"rtl\">אילו היה כתיב כמוֹהֲרֵי בתולות יאות</span> if it read, like the indemnities for virgins, it might be right (as you say).</div>","alt":["מֹהַר"]},"17408":{"h":"מוֹהֲרָא","r":"M00432","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XXXIV, 12</span>.—<i>Pl.</i> (with singular meaning) <a href=\"#\" data-headword=\"*מוֹהֲרִין\">מוֹהֲרִין</a>; constr. <span dir=\"rtl\">מוֹהֲרֵי</span>. Targ. O. ib. <span class=\"citation\">Targ. I Sam. XVIII, 25</span>. <span class=\"citation\">Targ. O. Ex. XXII, 16</span> (Y. <span dir=\"rtl\">מַפְרוֹנֵי</span>).</div>","alt":[]},"17409":{"h":"*מוֹהֲרִין","r":"M00433","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוֹהֲרָא\">preced.</a>) <i>exchange</i>, adaptation of a name of a <i>Persian festive season and fair</i> (cmp. <a href=\"#\" data-headword=\"אַקְנָיָיתָא\">אַקְנַיָּיתָא</a>). <span class=\"citation\">Ab. Zar. 11ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"מוֹהֲרָא\">מוֹהֲרָן</a>; ed. Ven. a. oth. <span dir=\"rtl\">מהורן</span>, v. Rabb. D. S. a. l. note); Y. ib. I, 39ᶜ <a href=\"#\" data-headword=\"מְחוֹרֵי\">מְחוֹרֵי</a> a Babylonian season.</div>","alt":[]},"17410":{"h":"*מוֹהַרְנְקֵי","r":"M00434","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> name of <i>a Persian</i> and of <i>a Babylonian festive season</i>, (v. <a href=\"#\" data-headword=\"*מוֹהֲרִין\">preced.</a> a. <a href=\"#\" data-headword=\"מוֹהַרְקֵי\">next w.</a>). <span class=\"citation\">Ab. Zar. 11ᵇ</span> (Ms. M. <span dir=\"rtl\">מוהרסנקי</span> for the Persian season; ed. Ven. a. oth. <span dir=\"rtl\">מהרנקי</span>); Y. ib. I, 39ᶜ <a href=\"#\" data-headword=\"מתירקנה\">מתירקנה</a>, a Median season (prob. a corruption of our w.). [V. Fl. to Levy Talm. Dict. p. 305<sup>2</sup>.]</div>","alt":[]},"17411":{"h":"מוֹהַרְקֵי","r":"M00435","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (used as sing., sub. <span dir=\"rtl\">שטר</span>) (<span dir=\"rtl\">הרק</span>, v. <a href=\"#\" data-headword=\"חֲרִיקָא\">חֲרִיקָא</a>) <i>surety</i>, esp. for royal taxes <a href=\"#\" data-headword=\"כַּרְגָּא\">(כַּרְגָּא</a>). <span class=\"citation\">Yeb. 46ᵃ</span>; <span class=\"citation\">B. Mets. 73ᵇ</span> <span dir=\"rtl\">מוֹהַרְקַיְיהוּ דהני וכ׳</span> (Ms. M. <span dir=\"rtl\">מוהד׳</span>) the surety for these people lies in the archive of the king, and the king has ordained that he who pays no <i>charga</i> can be made the servant of him who pays (for him).—[<span class=\"citation\">Erub. 62ᵃ</span> <span dir=\"rtl\">בריאה במ׳ ואבורגני</span> (Rabad <span dir=\"rtl\">פרהגבני</span>, v. Rabb. D. S. a. l. note 60) a lease is sound if made legal by sureties and (countersigned) by officers. Oth. explan., v. <a href=\"#\" data-headword=\"*אַבּוּרְגְּנָא\">אַבּוּרְגְּנָא</a>.]</div>","alt":[]},"17412":{"h":"מווהתין","r":"M00436","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XV, 8</span>, some ed., a. Var. ed. Lag., a corrupt. for <span dir=\"rtl\">מְרַחַקְתֵּיה</span> or <span dir=\"rtl\">תּוֹעַבְתֵּיה</span>.</div>","alt":[]},"17413":{"h":"מַוְוחֵי","r":"M00437","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְחִי\">יְחִי</a></div>","alt":[]},"17414":{"h":"מוּוָל","r":"M00438","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Toh. VIII, 7</span>, v. <a href=\"#\" data-headword=\"יָבַל I\"><span dir=\"rtl\">יָבַל</span> I</a></div>","alt":[]},"17415":{"h":"מַוְועֵי","r":"M00439","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְעָא\">יְעָא</a></div>","alt":[]},"17416":{"h":"מַוְורוֹן","r":"M00440","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μαυρός) <i>black</i>. <span class=\"citation\">Gen. R. s. 7</span> Ar. (ed. <span dir=\"rtl\">מיירן</span>), v. <a href=\"#\" data-headword=\"*אַסְפְּרוֹן\">אַסְפְּרוֹן</a>.</div>","alt":[]},"17417":{"h":"מַוְורִיאָטִינוֹס","r":"M00441","html":"<div class=\"sense\">, v. <span dir=\"rtl\">מוּרְיָטִינוֹס</span></div>","alt":[]},"17418":{"h":"מוֹזָא","r":"M00442","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זא</span>; cmp. <a href=\"#\" data-headword=\"זָאזָא\">זָאזָא</a>) </div><div class=\"sense\"><b>1)</b> <i>chaff</i>. <span class=\"citation\">Targ. Ps. I, 4</span>; a. e., v. <a href=\"#\" data-headword=\"מוֹץ ³\">מוֹצָא</a>.</div><div class=\"sense\"><b>—2)</b>  *מ׳ דשמכי <i>leaves of onions, leek</i>. <span class=\"citation\">Kidd. 52ᵇ</span> <span dir=\"rtl\">מ׳ דש׳</span> (Ar. <span dir=\"rtl\">מ׳ דירקא</span>, a gloss to <span dir=\"rtl\">מ׳ דש׳</span>; Rashi: <i>a handful</i> of onions).</div>","alt":[]},"17419":{"h":"מוזבה","r":"M00443","html":"<div class=\"sense\">, <span class=\"citation\">Y. Keth. XI, 34ᵇ</span> <span dir=\"rtl\">דמ׳ אמר וכ׳</span>, read: <span dir=\"rtl\">רימו בה ואמרו</span> (v. Asheri to <span class=\"citation\">Keth. 53ᵃ</span>).</div>","alt":[]},"17420":{"h":"מוּזָּחִין","r":"M00444","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Deut. 945</span>, v. <a href=\"#\" data-headword=\"נָזַח\">נָזַח</a></div>","alt":[]},"17421":{"h":"מוֹזִיפָא","r":"M00445","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*יָזַף\">יְזַף</a>) <i>creditor</i>. <span class=\"citation\">Targ. Ps. CIX, 11</span> Ms. (ed. <a href=\"#\" data-headword=\"מְזוֹפָא\">מְזוֹפָא</a>).</div>","alt":[]},"17422":{"h":"מוֹזִיקָא","r":"M00446","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַזִּיק ²\">מַזִּיקָא</a></div>","alt":[]},"17423":{"h":"מוֹזְלָא , I","r":"M00447","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַזָּל ²\">מַזָּלָא</a></div>","alt":[]},"17424":{"h":"מוֹזְלָא II","r":"M00448","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (אֲזַל II) <i>yarn</i>. Midr. Sam. ch. XXIII <span dir=\"rtl\">פסוק מוֹזְלָיךְ וכ׳</span> cut thy yarn and cease thy talk (a proverbial expression).</div>","alt":[]},"17425":{"h":"מוֹזְנָוָון","r":"M00449","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"מֹאזְנַיִם\">מֹאזְנַיִם</a>, <i>scales</i>. <span class=\"citation\">Targ. O. Lev. XIX, 36</span> (some ed. <a href=\"#\" data-headword=\"מֹאזְנַוָּון\">מֹאזְנַוָּון</a>). V. <a href=\"#\" data-headword=\"מוֹדָנָא\">מוֹדְנָא</a>.</div>","alt":["מוֹזְנָוָן"]},"17426":{"h":"מוֹזְנַיָּא","r":"M00450","html":"<div class=\"sense\"> m. pl. <a href=\"#\" data-headword=\"מוֹזְנָוָון\">same</a>. <span class=\"citation\">Targ. Y. II, Lev. XIX, 36</span> (ed. Amst. <a href=\"#\" data-headword=\"מוֹזְנַיָּא\">מוֹזַנְיָא</a>, corr. acc.). <span class=\"citation\">Targ. Is. XL, 12</span>; <span class=\"citation\">15</span>.</div>","alt":[]},"17427":{"h":"מוֹזְפוּ","r":"M00451","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִזְפּוּ\">מִזְפּוּ</a></div>","alt":[]},"17428":{"h":"מוֹזְפָנָא","r":"M00452","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"מוֹזִיפָא\">מוֹזִיפָא</a>. <span class=\"citation\">Targ. Prov. XXII, 7</span>.</div>","alt":[]},"17429":{"h":"מוֹחַ","r":"M00453","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"מָהָה\">מָהָה</a>) <i>marrow</i>, esp. (with or without <span dir=\"rtl\">ראש</span>) <i>brain</i>. <span class=\"citation\">Tosef. Pes. VI, 10</span>, v. <a href=\"#\" data-headword=\"קוּלִית\">קוּלִית</a>. <span class=\"citation\">Ḥull. III, 1</span> <span dir=\"rtl\">קרום של מ׳</span> the membrane which surrounds the brain, v. <span dir=\"rtl\">חַיִּיתָא IV</span>. <span class=\"citation\">Ib. 45ᵃ</span> <span dir=\"rtl\">מ׳ כל מה … מ׳</span> as to <i>moaḥ</i>, whatever is contained in the skull is considered as brain. <span class=\"citation\">Ib. 45ᵇ</span> <span dir=\"rtl\">רוב מוֹחוֹ</span> the larger part of the marrow of the spine (spinal cord); a. fr.—<span class=\"citation\">Men. 80ᵇ</span>; <span class=\"citation\">Yeb. 9ᵃ</span> <span dir=\"rtl\">אין לו מ׳ בקדקדו</span> has no brains in his head.</div>","alt":[]},"17430":{"h":"מוֹחַ ²","r":"M00454","html":"<div class=\"sense\">, <i>brain</i>; also <i>head</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 35</span> (h. text <span dir=\"rtl\">קדקד</span>).—<span class=\"citation\">Ḥull. 45ᵃ</span>, v. <a href=\"#\" data-headword=\"חַיְיתָא I\"><span dir=\"rtl\">חַיְיתָא</span> IV</a>. <span class=\"citation\">Meg. 19ᵇ</span> <span dir=\"rtl\">ומחו לה אמ׳</span> and they struck it (R. Ḥia’s opinion) on the head, i.e. opposed it (Rashi: and he (R. Ḥ.) struck it, &amp;c., i.e. modified it, read: <span dir=\"rtl\">ומחי</span>). <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">מוֹחֵיה</span>, v. <a href=\"#\" data-headword=\"פְּצַע\">פְּצַע</a>; a. fr.—Pl. <span dir=\"rtl\">מוֹחַיָּא</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 22</span> (some ed. <span dir=\"rtl\">מוֹחֲיָא</span>) <i>marrow</i> of bones.</div>","alt":["מוֹחָא"]},"17431":{"h":"מוחה","r":"M00455","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ned. I, 2</span>, v. <a href=\"#\" data-headword=\"מוֹהֶה\">מוֹהֶה</a></div>","alt":["מוחו"]},"17432":{"h":"מוֹחַל","r":"M00456","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <span dir=\"rtl\">מחח</span>, v. <a href=\"#\" data-headword=\"מוֹהַל\">מוֹהַל</a>) <i>thin secretion.</i> <span class=\"citation\">Toh. IX, 2</span> <span dir=\"rtl\">המ׳ היוצא מהן</span> the fluid which runs out of the olives (before they are pressed); <span class=\"citation\">ib. 3</span> <span dir=\"rtl\">המ׳ היוצא מהן</span> that which runs (after the oil is pressed out); ib. <span dir=\"rtl\">היוצא מן הבור</span> which comes out of the pit after the oil has been taken out; Tosef. ib. X, 3 <span dir=\"rtl\">מ׳ היוצא מעיקת בית הבד</span>. <span class=\"citation\">Makhsh. VI, 5</span> <span dir=\"rtl\">אין המ׳ יוצא מידי שמן</span>; Tosef. l. c. <span dir=\"rtl\">ידי צחצוחי שומן</span> (read: <a href=\"#\" data-headword=\"שָׁמֵן I\">שמן</a>) the secretion (of olives) cannot be excluded from the category of (must be classified with) (diluted) oil; <span class=\"citation\">Sabb. 144ᵃ</span>, v. <a href=\"#\" data-headword=\"צִחְצוּחַ\">צִחְצוּחַ</a>; a. fr.</div>","alt":[]},"17433":{"h":"מוֹחֵק","r":"M00457","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָחָק\">מָחַק</a>) <i>the flat end of the writing instrument, used for erasing</i>, v. <a href=\"#\" data-headword=\"כּוֹתֵב\">כּוֹתֵב</a>. <span class=\"citation\">Kel. XIII, 2</span>; a. e.</div>","alt":[]},"17434":{"h":"מוּט","r":"M00458","html":"<div class=\"sense\"> (b. h.) <i>to incline, waver, decline; to give way, bend</i>. Y. Snh. X, 27ᵈ bot., v. infra. Tanḥ. B’har 1 <span dir=\"rtl\">כשתָּמוּט ידם לפני וכ׳</span> when their power shall sink before Nebuchadnezzar. Tanḥ. Vayishl. 3 (ref. to <span class=\"citation\">Prov. XXV, 26</span>) <span dir=\"rtl\">כשמָט לפני וכ׳</span> when he bends (humiliates himself) before the wicked; <span class=\"citation\">Gen. R. s. 75</span> <span dir=\"rtl\">א&quot;א לצדיק לָמוּט וכ׳</span> (<span class=\"citation\">Yalk. Gen. 130</span> <span dir=\"rtl\">לִימּוֹט</span>) it is impossible to the righteous to bend &amp;c.; a. e.</div><div class=\"sense\"><b>Nif. נִמּוֹט</b> <div class=\"sense\"><i>to be shaken, bent</i>. Yalk. l. c., v. supra.</div></div><div class=\"sense\"><b>Hif. הֵמִיט</b> <div class=\"sense\"><i>to bend, to shake.</i> <span class=\"citation\">Zab. III, 3</span> <span dir=\"rtl\">כל שאינה יכולה להָמִיט באדם</span> (not <span dir=\"rtl\">בה אדם</span>) (Asheri <span dir=\"rtl\">להָסִיט</span>, v. <a href=\"#\" data-headword=\"סוּט\">סוּט</a>) a ship which has no staggering effect on man. Gen. R. l. c. <span dir=\"rtl\">מֵמִיט עצמו וכ׳</span> humbles himself.</div></div><div class=\"sense\"><b>Hithpol. הִתְמוֹטֵט</b> <div class=\"sense\">, <i>Nithpol</i>. <span dir=\"rtl\">נִתְמוֹטֵט</span> <i>to be declining; to sink</i>. Y. Snh. X, 27ᵈ bot.; <span class=\"citation\">Yalk. Is. 338</span> (ref. to <span class=\"citation\">Is. LIV, 10</span>) <span dir=\"rtl\">אם ראית זכות אבות שמָטָה … שנִתְמוֹטְטָה וכ׳</span> when thou seest the merit of the fathers decline and that of the mothers sink, go and cling to grace; <span class=\"citation\">Lev. R. s. 36</span>, end <span dir=\"rtl\">שנִתְמֹטְטָה</span>.—Y. l. c. 28ᵇ <span dir=\"rtl\">והיו מִתְמוֹטְטִין והולכין</span> they sank deeper and deeper (into poverty). <span class=\"citation\">B. Mets. 71ᵃ</span> <span dir=\"rtl\">נכסיו מתמוטטין</span> (Ms. M. <span dir=\"rtl\">מתמעטין</span>) his wealth will be reduced; <span class=\"citation\">Yalk. Ps. 665</span> <span dir=\"rtl\">מִתְמוֹטֵט</span> he will sink. B. Mets. l. c. <span dir=\"rtl\">הללו מתמ׳ וכ׳</span> (Ms. R. 2 <span dir=\"rtl\">מוֹטְטִין</span>, v. Rabb. D. S. a. l. notes 2—4) these sink and rise again &amp;c.; Yalk. l. c.</div></div>","alt":[]},"17435":{"h":"מוּט ²","r":"M00459","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. XXV, 35</span>. <span class=\"citation\">Targ. Y. Deut. XXXII, 35</span>; a. fr.</div><div class=\"sense\"><b>Af. אָמֵיט</b> <div class=\"sense\"><i>to balance, weigh</i>. Pesik. B’shall., p. 82ᵃ <span dir=\"rtl\"><span dir=\"rtl\">באמטיתא דאֲמִיטוּן</span> (<a href=\"#\" data-headword=\"מוּט ²\">אִתְּמִיט</a>) <span dir=\"rtl\">אִיתְּמֵט להון</span></span> with the balances with which they weighed, weighing was done to them; v. <a href=\"#\" data-headword=\"מוֹטָה\">מוֹטָה</a>.</div></div><div class=\"sense\"><b>Ithpe. אִתְּמִיט</b> <div class=\"sense\"><i>to be weighed</i>, v. supra (v. Bub. a. l. note 42).</div></div><div class=\"sense\"><b>Ithpol. אִתְמוֹטַט</b> <div class=\"sense\"><i>to sink, waver, be reduced</i>. <span class=\"citation\">Targ. Ps. XCIV, 18</span>; a. fr.—<span class=\"citation\">B. Mets. 71ᵃ</span> דלא מוזפי ומִתְמוֹטְטֵי Ms. R. (v. Rabb. D. S. a. l. note 4) who lend not on interest and yet become poor.</div></div>","alt":[]},"17436":{"h":"מוֹט","r":"M00460","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מוּט ²\">preced.</a>) <i>balancing pole, staff</i>. <span class=\"citation\">Bets. III, 3</span> (<span class=\"citation\">25ᵃ</span>) <span dir=\"rtl\">לא … במ׳ במוטה</span> (Y. ed. <span dir=\"rtl\">במטה</span>, v. Rabb. D. S. a. l. note 4) he must not bring it to town on a staff or on a barrow. <span class=\"citation\">Sot. 34ᵃ</span> (ref. to <span class=\"citation\">Num. XIII, 23</span>) <span dir=\"rtl\">ממשמע שנאמר במ׳ וכ׳</span> it being said ‘on a staff’, do I not know that it was carried by two persons?—Pl. <span dir=\"rtl\">מוֹטוֹת</span>. Ib., v. <a href=\"#\" data-headword=\"טוּרְטִינִי\">טוּרְטִינִי</a>. <span class=\"citation\">Tosef. Ohol. VII, 1</span>, v. <a href=\"#\" data-headword=\"נִדְבָּךְ\">נִדְבָּךְ</a>; a. e.</div>","alt":[]},"17437":{"h":"מוּטָב","r":"M00461","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָטַב\">יָטַב</a>) </div><div class=\"sense\"><b>1)</b>  (<i>it is</i>) <i>good, better</i>. Tanḥ. B’har 1 <span dir=\"rtl\">חזר בו מ׳</span> if he amends, it is good. <span class=\"citation\">Bets. 30ᵃ</span>, a. fr. <span dir=\"rtl\">מ׳ שיהיו … ואל וכ׳</span> it is better that they fail unwittingly than &amp;c. <span class=\"citation\">Snh. 7ᵃ</span> (in Chald. diction) <span dir=\"rtl\">מ׳ דליעבדו וכ׳</span> it is better that they worship the golden calf (than commit murder). <span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">מ׳ דאקום וכ׳</span> it is best that I get up and go to them myself; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>the better, the right conduct</i>. Lam. R. introd. (R. Abba 2) <span dir=\"rtl\">המאור … היה מחזירן למ׳</span> the light in it (the Law) would have led them back to the right way. <span class=\"citation\">Snh. 101ᵇ</span>; a. fr.</div>","alt":[]},"17438":{"h":"מוֹטָה","r":"M00462","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"מוֹט\">מוֹט</a>) </div><div class=\"sense\"><b>1)</b> <i>a small barrow</i>. <span class=\"citation\">Bets. III, 3</span> (<span class=\"citation\">25ᵃ</span>), v. <a href=\"#\" data-headword=\"מוֹט\">מוֹט</a>.</div><div class=\"sense\"><b>—2)</b> pl. <span dir=\"rtl\">מוֹטוֹת</span> <i>bands of a yoke; yoke</i>. Tanḥ. <span class=\"citation\">B’shall. 23</span> <span dir=\"rtl\">והיו מ׳ ומרכבות וכ׳</span></div><div class=\"sense\"><b>*3)</b> <i>balances</i>. Pesik. B’shall., p. 82ᵃ במטה דאמיטין אתמיט להון Ar. with the balance with which they weighed, weighing was done to them; [Ar.: as they made others sink, so were they made to sink (v. <a href=\"#\" data-headword=\"מוּט\">מוּט</a>); oth. opin.: <span dir=\"rtl\">במַטֶּה וכ׳</span> with the staff with which they struck, were they struck].</div>","alt":["מֹטָה"]},"17439":{"h":"מוּטָּה","r":"M00463","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [<i>bend</i>,] <i>the radial bone</i> of a bird’s wing. Tanḥ. Thazr. 8; ed. Bub. 10 (ref. to <span class=\"citation\">Is. VIII, 8</span>) <span dir=\"rtl\">המ׳ הזו וכ׳</span> the radial bone of a chicken is one sixtieth portion of its wings; [Rashi to Is. l. c. quotes <span dir=\"rtl\">מוּטּוֹת</span>, <i>pl.</i>]; <span class=\"citation\">Midr. Till. to Ps. LXXIX</span>, beg.; <span class=\"citation\">Yalk. Is. 279</span>.</div>","alt":[]},"17440":{"h":"מוּטֶּה","r":"M00464","html":"<div class=\"sense\"><i>reclining</i>, v. <a href=\"#\" data-headword=\"נטי\">נָטָה</a>.</div>","alt":[]},"17441":{"h":"מוטליא","r":"M00465","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֵמְטַלְיָא\">הֵמְטַלְיָא</a></div>","alt":[]},"17442":{"h":"מוטניא","r":"M00466","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 44</span> some ed., v. <a href=\"#\" data-headword=\"*מִלְכָי\">מִלְכָי</a></div>","alt":[]},"17443":{"h":"*מוּטַרְדֵּי","r":"M00467","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְרַד I\">טְרַד</a>) <i>business</i>(?), an adaptation of the name of <i>a Persian festive season and fair</i>. <span class=\"citation\">Ab. Zar. 11ᵇ</span> (Ms. M. <span dir=\"rtl\">מוטיררי</span>; Y. ib. I, 39ᶜ, a Median festival, <a href=\"#\" data-headword=\"ניסרדי\">ניסרדי</a>; Ar. <a href=\"#\" data-headword=\"מסרדי\">מסרדי</a>).</div>","alt":[]},"17444":{"h":"מוטרין","r":"M00468","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"מִיטְרִין\">מִיטְרִין</a>.</div>","alt":[]},"17445":{"h":"מוֹי","r":"M00469","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מַיִין\">מַיִין</a>, <i>water</i>. <span class=\"citation\">Targ. Ps. I, 3</span>; a. fr.—Targ. II Esth. III, 3 <a href=\"#\" data-headword=\"מוֹי\">מויי</a> (ed. Lag. <a href=\"#\" data-headword=\"מוֹהֶה\">מוֹהִי</a> <i>its waters</i>); <span class=\"citation\">Targ. Is. LVIII, 11</span>; <span class=\"citation\">Targ. Jer. XV, 18</span>; a. fr.—מוֹהָא <i>her</i> (<i>its</i>) <i>waters</i>. <span class=\"citation\">Ib. L, 38</span>; a. e.—<span class=\"citation\">Targ. Is. XIX, 10</span> <a href=\"#\" data-headword=\"מָחִי\">מחא</a> (Var. ed. Lag. <span dir=\"rtl\">מהא</span>) read <a href=\"#\" data-headword=\"מָהָא\">מָהָא</a> = <a href=\"#\" data-headword=\"מוֹהָא\">מוֹהָא</a>.—<span class=\"citation\">Y. Erub. X, 26ᶜ</span> <span dir=\"rtl\">דלא יתן מויי</span> that he add no water to it. <span class=\"citation\">Y. Pes. III, beg. 29ᵈ</span>; a. e.</div>","alt":["מוֹיֵי"]},"17446":{"h":"מוּךְ","r":"M00470","html":"<div class=\"sense\"> (b. h.) <i>to be crushed; to be low, sink; to be poor</i>. Tanḥ. B’har 3 <span dir=\"rtl\">על שמָךְ בעונות</span> because he sank into sins.—V. <a href=\"#\" data-headword=\"מָךְ\">מָךְ</a>.</div><div class=\"sense\"><b>Hif. הֵמִיךְ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מוֹי\">same</a>. Mekh. B’shall., Amal., s. 1 <span dir=\"rtl\">כשהוא מֵמִיךְ ידיו עתידין ישראל להָמִיךְ ול׳</span> when he (Moses) let his hands sink, (it intimated) that Israel is destined to sink in the knowledge of the words of the Law to be given through his hands; Tanḥ. <span class=\"citation\">B’shall. 27</span>.</div><div class=\"sense\"><b>—2)</b> <i>to lower, let sink</i>. Ib., v. supra.—<span class=\"citation\">Sifré Num. 90</span> <span dir=\"rtl\">כאן הקב&quot;ה ממיך ומשה מגביה וכ׳</span> here the Lord lowers (his anger) and Moses raises (is more angry), but when the golden calf was made, the Lord raised, and Moses lowered (tried to soften his anger); <span class=\"citation\">Yalk. Num. 735</span> <span dir=\"rtl\">מַמְאִיךְ</span> (fr. <a href=\"#\" data-headword=\"מָאַךְ\">מָאַךְ</a>).</div></div><div class=\"sense\"><b>Nif. נָמוֹךְ</b> <div class=\"sense\">; f. <a href=\"#\" data-headword=\"נָמוֹךְ\">נְמוּכָה</a>; pl. <span dir=\"rtl\">נְמוּכִים</span> <i>low.</i> <span class=\"citation\">Kil. IV, 7</span> <span dir=\"rtl\">נ׳ מי׳ טפחים</span> lower than ten handbreadths. <span class=\"citation\">Ruth R. to III, 3</span> <span dir=\"rtl\">בנ׳ שבעיר</span> in the lowest part of the city. Y. Maas. Sh. V, end, 56ᵈ; Y. Sot. IX, 24ᵃ bot. <span dir=\"rtl\">קול נ׳</span> in a low voice, opp. <a href=\"#\" data-headword=\"גָּבוֹהַּ\">גבוה</a>. <span class=\"citation\">Ber. 10ᵇ</span>. <span class=\"citation\">Sifré Num. 58</span>. <span class=\"citation\">Ib. 83</span>, v. <a href=\"#\" data-headword=\"נָמַךְ\">נָמַךְ</a>. <span class=\"citation\">Ab. V, 19</span> <span dir=\"rtl\">רוח נְ׳</span> a lowly spirit, v. <a href=\"#\" data-headword=\"גָּבוֹהַּ\">גָּבוֹהַּ</a>.—<span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">ההרים הנ׳</span> the lower mountains; a. fr.</div></div>","alt":[]},"17447":{"h":"מוּךְ ²","r":"M00471","html":"<div class=\"sense\"><b>1)</b> <i>to decline, sink</i>. <span class=\"citation\">Targ. Y. II, Ex. XII, 42</span>. Targ. <span class=\"citation\">Hab. III, 6</span>; a. e. (v. <a href=\"#\" data-headword=\"מְכִי\">מְכִי</a>).</div><div class=\"sense\"><b>—2)</b> <i>to become soft</i>. <span class=\"citation\">Snh. 95ᵃ</span> <span dir=\"rtl\">מָכָא ליה ארעא וכ׳</span> the ground under him became soft.</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"מוּךְ\">מוךְ</a>) <i>to lay under, make a bed</i>. <span class=\"citation\">Targ. Ps. CXXXIX, 8</span>.—<span class=\"citation\">Pes. 49ᵃ</span> <span dir=\"rtl\">בר מָךְ רבע</span> one who lays under (his cloak) and lies down (at any place, a shiftless person). <span class=\"citation\">Taan. 6ᵇ</span>; <span class=\"citation\">Ber. 59ᵃ</span> (prov.) <span dir=\"rtl\">כד מפתח בבי … מוֹךְ שקיך וגני</span> if it rains when the doors are opened (in the morning), lay down thy bag, ass-driver, and sleep (do not export, for provisions will be cheap); a. e.—Part. <a href=\"#\" data-headword=\"מְאַךְ\">מָאֵיךְ</a>, <a href=\"#\" data-headword=\"מְאַךְ\">מָיֵיךְ</a>. <span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">הוו מָיְיכֵי ליה וכ׳</span> (Rashi: <span dir=\"rtl\">מָיְיכִין</span>; Var. <a href=\"#\" data-headword=\"מַיְיתֵי\">מייתי</a>, v. Rabb. D. S. a. l. note 1) they spread for him sixty mattresses. <span class=\"citation\">Taan. 21ᵇ</span> bot. <a href=\"#\" data-headword=\"מְאַךְ\">מאיך</a> Ar. (ed. <a href=\"#\" data-headword=\"מָךְ\">מך</a>), v. <a href=\"#\" data-headword=\"בִּיסְתַּרְקָא\">בִּיסְתַּרְקָא</a>.—V. <a href=\"#\" data-headword=\"מָכָא\">מָכָא</a>.</div><div class=\"sense\"><b>Af. אָמֵיךְ  אַמֵּיךְ</b> <div class=\"sense\"><b>1)</b> <i>to lower</i>. <span class=\"citation\">Targ. Ps. CXIII, 6</span> מְמֵיךְ Ms. (ed. <a href=\"#\" data-headword=\"מְאַךְ\">מַמֵיךְ</a>, <span dir=\"rtl\">מֵמִיךְ</span>; h. text <span dir=\"rtl\">המשפילי</span>).</div><div class=\"sense\"><b>—2)</b> <i>to make soft, crush</i>. Ib. XLIV, 20 (h. text <a href=\"#\" data-headword=\"דכי\">דִּכָּה</a>).</div><div class=\"sense\"><b>—3)</b> <i>to lay under, make a bed</i>. <span class=\"citation\">Targ. Job XLI, 22</span> (h. text <span dir=\"rtl\">רפד</span>).</div></div>","alt":[]},"17448":{"h":"מוֹךְ","r":"M00472","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּךְ ²\">preced.</a> 2) <i>a soft, spongy substance, hackled wool, rag, lint</i> &amp;c. <span class=\"citation\">Sabb. VI, 5</span> <span dir=\"rtl\">מ׳ שבאזנה</span> wool in her ear (to resorb running pus); <span dir=\"rtl\">מ׳ שבסנדלה</span> in her shoes (to soften them). Ib. 134ᵇ <span dir=\"rtl\">מ׳ יבש וכ׳</span> a dry compress or dry sponge. <span class=\"citation\">Tosef. Nidd. II, 6</span> <span dir=\"rtl\">משמשות במ׳</span> insert a resorbent (to prevent conception); a. fr.—Pl. <span dir=\"rtl\">מוֹכִין</span>. <span class=\"citation\">B. Kam. X, 10</span> <span dir=\"rtl\">מ׳ שהכובס וכ׳</span> the lumps (of threads) which the washer takes out (of the trough). <span class=\"citation\">Tosef. ib. XI, 12</span>; <span class=\"citation\">13</span>. <span class=\"citation\">Neg. XI, 12</span>; a. fr.—[<span dir=\"rtl\">מוּכִּים</span>, <span dir=\"rtl\">מוּכִּין</span>, v. <a href=\"#\" data-headword=\"נָכָה\">נָכָה</a>.]</div>","alt":[]},"17449":{"h":"מוֹכִיחַ","r":"M00473","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָכַח\">יָכַח</a>) <i>evidence</i>, v. <a href=\"#\" data-headword=\"הוֹכֵיח\">הוכֵיחַ</a>.</div>","alt":[]},"17450":{"h":"מוכירין","r":"M00474","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכֵירִין\">מְכירִין</a></div>","alt":[]},"17451":{"h":"מוּכָן","r":"M00475","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a><i>Hif.</i></div>","alt":[]},"17452":{"h":"מוּכְנִי","r":"M00476","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (μηχανή) <i>machine</i> for lifting weights, <i>wheel-work.</i> <span class=\"citation\">Yoma III, 10</span> <span dir=\"rtl\">עשה מ׳ לכיור</span> made a machine for sinking the wash-basin (v. <a href=\"#\" data-headword=\"כִּיּוֹר\">כִּיּוֹר</a>) into the well; <span class=\"citation\">Tam. III, 8</span>. <span class=\"citation\">Kel. XVIII, 2</span> (ed. Dehr. <a href=\"#\" data-headword=\"מִכְנִי\">מִכְנִי</a>). <span class=\"citation\">Tosef. Par. III</span> (<span class=\"citation\">II), 9</span> <a href=\"#\" data-headword=\"מִיכְנִי\">מִיכְנִי</a>. <span class=\"citation\">Ḥull. 15ᵇ</span> <span dir=\"rtl\">השוחט במ׳</span> if one slaughters by means of a machine; a. e.</div>","alt":[]},"17453":{"h":"מוּכְנוֹי","r":"M00477","html":"<div class=\"sense\">(pl. form) <a href=\"#\" data-headword=\"מוּכְנִי\">same</a>, <i>rollers</i>. Targ. II Esth. I, 2.—V. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנוֹן</a>.</div>","alt":[]},"17454":{"h":"מוּכְנָס","r":"M00478","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>) <i>storage</i>. <span class=\"citation\">Tosef. Ab. Zar. VIII</span> (<span class=\"citation\">IX), 1</span> <span dir=\"rtl\">אלו עשויות למ׳</span> these (vessels) are made for storage; (<span class=\"citation\">Ab. Zar. 74ᵇ</span> מכניסו לקיום Ms. M.).</div>","alt":[]},"17455":{"h":"מוֹכֵס","r":"M00479","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מֶכֶס\">מֶכֶס</a>) <i>revenue farmer, publican, custom-collector</i> (considered a robber in Jewish law). <span class=\"citation\">B. Kam. 113ᵃ</span> <span dir=\"rtl\">מ׳ שאין לו קיצבה</span> a publican who is not limited by legal stipulations; <span dir=\"rtl\">מ׳ העומד מאליו</span> a self-constituted collector. <span class=\"citation\">Ab. Zar. 39ᵃ</span>; <span class=\"citation\">Bekh. 30ᵇ</span> bot. <span dir=\"rtl\">קשרי מ׳</span> the publican’s knots (seals or written receipts); a. e—Pl. <span dir=\"rtl\">מוֹכְסִין</span>. <span class=\"citation\">B. Kam. X, 2</span> <span dir=\"rtl\">נטלו מ׳ וכ׳</span> if publicans took away his ass and gave him one taken from somebody else. <span class=\"citation\">Ib. 1</span>; <span class=\"citation\">Tosef. ib. X, 22</span> <span dir=\"rtl\">תיבת מ׳</span> the treasury of the publicans. <span class=\"citation\">Ned. III, 4</span>; <span class=\"citation\">Tosef. ib. II, 2</span>, v. <a href=\"#\" data-headword=\"נָדַר\">נָדַר</a>. <span class=\"citation\">Sabb. VIII, 2</span> <span dir=\"rtl\">נייר … קשר מ׳</span> paper large enough to write on it a tax-receipt (v. supra). <span class=\"citation\">Shebu. 39ᵃ</span> <span dir=\"rtl\">אין לך … כולה מ׳</span> there is no family in which there is a publican, whose members may not all be considered as publicans (in Jewish law); a. fr.</div>","alt":[]},"17456":{"h":"מוֹכֵס ²","r":"M00480","html":"<div class=\"sense\"> <span class=\"citation\">Y. Snh. VI, 23ᶜ</span>; <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot. <span dir=\"rtl\">בריה דמעין מ׳</span> the son of Mayan the publican; <span class=\"citation\">Snh. 44ᵇ</span> <span dir=\"rtl\">בעיא מ׳</span>, v. <a href=\"#\" data-headword=\"*בָּעְיָא\">בָּעְיָא</a>.—Y. Sabb. VI, end, 8ᵈ [read:] <span dir=\"rtl\">קריב למָכְסָה והב ליה חמרא ואזיל ליה</span> he came near (was caught by) a publican, and he gave him his ass and was let off, v. <a href=\"#\" data-headword=\"דִּיפְּלָא\">דִּיפְּלָא</a>.—Pl. <span dir=\"rtl\">מוֹכְסִין</span>. <span class=\"citation\">Targ. Jud. V, 11</span> (ed. Lag. <span dir=\"rtl\">מָכְסִין</span>).—[<span dir=\"rtl\">מוכסין</span>, <span class=\"citation\">Ab. Zar. 14ᵃ</span> Ms. M., v. next w.]</div>","alt":["מוֹכְסָא","מָכְסָא"]},"17457":{"h":"מוֹכְסָסִים","r":"M00481","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> a species of <i>figs</i>. <span class=\"citation\">Bekh. 8ᵃ</span> (inferior to <span dir=\"rtl\">בנות שוח</span>). <span class=\"citation\">Ab. Zar. 14ᵃ</span> (Ms. M. <span dir=\"rtl\">מוכסין</span>; Ar. <a href=\"#\" data-headword=\"מבססין\">מבססין</a>).</div>","alt":["מוֹכְסָסִין"]},"17458":{"h":"מוֹל","r":"M00482","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> Assyr. mâla, , v. Del. Proleg. p. 132) </div><div class=\"sense\"><b>1)</b> <i>border, front, in sight of</i>. <span class=\"citation\">Ḥull. 19ᵇ</span> (expl. <span dir=\"rtl\">ממול ערפו</span>, <span class=\"citation\">Lev. V, 8</span>, <i>border of the neck</i>, the space beginning with the back of the head, opposite the face, and ending with the end of the neck, opposite the throat) <span dir=\"rtl\">מ׳ הרואה את העורף</span> the edge which sees the <i>ʿoref</i> (but not the <i>ʿoref</i> itself). Ib. <span dir=\"rtl\">וכ&quot;ת עורף … מ׳ דידיה היכא</span> if you will say, we know not where <i>ʿoref</i> itself is, how can we know where its border is?—<span class=\"citation\">Sifré Num. 59</span> <span dir=\"rtl\">עֲשֵׂה לה מ׳ פנים</span> (Ms. 3, a. <span class=\"citation\">Yalk. ib. 719</span> <span dir=\"rtl\">מ׳ ופנים</span>) give the candlestick an edge of the front (an edge and a front), i.e. a prominent central light towards which the lights on both sides are turned. Ib. 60 <span dir=\"rtl\">עָשָׂה לה מ׳ פנים</span>.</div>","alt":["מוּל I"]},"17459":{"h":"מוּל II","r":"M00483","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מוֹל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>to make an edge, to hem</i> or <i>fringe</i>. <span class=\"citation\">Tosef. Kel. B. Bath. V, 7</span> <span dir=\"rtl\">עד שעה שׁיָמוּל</span> until he hems the girdle. Ib. <span dir=\"rtl\">ומָל מרוח אחת</span> when he made a hem on one side (of the piece which he cut out of the middle of a piece of cloth).</div><div class=\"sense\"><b>—2)</b> <i>to circumcise</i>. <span class=\"citation\">Sabb. XIX, 4</span> <span dir=\"rtl\">אחד למול אחר וכ׳</span> one child which was to be circumcised after the Sabbath &amp;c.; <span dir=\"rtl\">ושכח ומָל וכ׳</span> and by mistake he circumcised &amp;c. Ib. 6 <span dir=\"rtl\">מל ולא פרע וכ׳</span> if he circumcised but failed to split the prepuce &amp;c. Ib. 5 (137ᵃ) <span dir=\"rtl\">קטן … אין מוֹלִין</span> Ms. M. (ed. <span dir=\"rtl\">מוהלין</span>) a sick infant must not be circumcised. <span class=\"citation\">Pesik. R. s. 25</span> <span dir=\"rtl\">מי מל לשמי וכ׳</span> who circumcised a son in honor of my name, unless I gave him a son?; <span class=\"citation\">Lev. R. s. 27</span> <span dir=\"rtl\">מלל</span> (corr. acc.); a. fr.—Part. pass. <a href=\"#\" data-headword=\"מוּל\">מוּל</a>, pl. <a href=\"#\" data-headword=\"מוּלִי\">מוּלִים</a>, <span dir=\"rtl\">מוּלִין</span>. <span class=\"citation\">Yalk. Jer. 285</span>.</div><div class=\"sense\"><b>Nif. נִימּוֹל  נִמּוֹל</b> <div class=\"sense\"><i>to be circumcised</i>. <span class=\"citation\">Sabb. XIX, 5</span>. <span class=\"citation\">Lev. R. s. 25</span>; <span class=\"citation\">Gen. R. s. 46</span> <span dir=\"rtl\">ומהיכן יִמּוֹל</span> on what part of the body should one be circumcised?—Y. Shebi. IV, end, 35ᶜ <span dir=\"rtl\">משיִמּוֹלוּ</span> from the time they are circumcised. Gen. R. l. c. <span dir=\"rtl\">גזר הרופא שימולו</span> the physician ordered that they must be circumcised; a. fr.—[<i>Polel</i> <span dir=\"rtl\">מוֹלֵל</span>, v. <a href=\"#\" data-headword=\"מָלַל I\">מָלַל</a>.]</div></div>","alt":[]},"17460":{"h":"מוּל","r":"M00484","html":"<div class=\"sense\"><i>Ithpol</i>. <a href=\"#\" data-headword=\"קְלַל\">אִתְמוֹלַל</a> (v. <span dir=\"rtl\">מלל</span>) <i>to become brittle, fade</i>. <span class=\"citation\">Targ. Job XIV, 2</span>. <span class=\"citation\">Ib. XXIV, 24</span> Ms. (ed. <span dir=\"rtl\">יתקטפ׳</span>). <span class=\"citation\">Targ. Ps. XC, 6</span>; a. e.</div>","alt":[]},"17461":{"h":"מוּלָא I","r":"M00485","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָלֵא I\">מלא</a>; cmp. b. h. <a href=\"#\" data-headword=\"מְלֹא\">מְלֹא</a>) <i>plenty, power</i>. <span class=\"citation\">Targ. Prov. VI, 31</span> Ms. (v. Bxt. s. v. <span dir=\"rtl\">מדל</span>; ed. <span dir=\"rtl\">מזלא</span>). <span class=\"citation\">Targ. Job XII, 6</span> first vers. <span dir=\"rtl\">דזמין אֵל מ׳ וכ׳</span> ed. Lag. (some ed. <span dir=\"rtl\">אלמולא</span> corr. acc.; in oth. ed. our w. is omitted).</div>","alt":["מוֹלָא"]},"17462":{"h":"מוּלָא II","r":"M00486","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (mulus) <i>mule</i>. Pesik. Shub., p. 162ᵃ (ref. to <span dir=\"rtl\">נחשתים</span>, <span class=\"citation\">II Chr. XXXIII, 11</span>) <span dir=\"rtl\">כמין מ׳ של נחשת</span> Ar. (ed. <a href=\"#\" data-headword=\"מולי\">מולי</a>) a sort of mule of bronze; <span class=\"citation\">Y. Snh. X, 28ᶜ</span> bot. <a href=\"#\" data-headword=\"מָלֵא I\">מילא</a>; <span class=\"citation\">Deut. R. s. 2</span> <span dir=\"rtl\">מולן</span>; <span class=\"citation\">Ruth R. to II, 14</span> <span dir=\"rtl\">מולה</span>; <span class=\"citation\">Yalk. Kings 246</span> <a href=\"#\" data-headword=\"מוּלָא I\">מולא</a>.—Pl. <span dir=\"rtl\">מוּלָאוֹת</span>. <span class=\"citation\">Sabb. 52ᵃ</span> (Ar. <i>masc</i>.).—Ch. v. <a href=\"#\" data-headword=\"מוּלְתָא\">מוּלְתָא</a>.</div>","alt":[]},"17463":{"h":"מוּלָּאֵי","r":"M00487","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַמּוּלָּאֵי\">מַמּוּלָאֵי</a></div>","alt":[]},"17464":{"h":"מולגיה","r":"M00488","html":"<div class=\"sense\">) <span class=\"citation\">Lev. R. s. 12</span>, read: <a href=\"#\" data-headword=\"מָלוּגְמָא\">מָלוּגְמָא</a>.</div>","alt":["(מולגייה","מוליגא","מוליגיה"]},"17465":{"h":"מוּלְבָּז","r":"M00489","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּנְבָּז\">מוּנְבָּז</a></div>","alt":[]},"17466":{"h":"מוֹלֵד","r":"M00490","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. b. h. <span dir=\"rtl\">מוֹלֶדֶת</span>; <a href=\"#\" data-headword=\"יָלַד\">יָלַד</a>) <i>issue, descendant</i>.—Pl. <span dir=\"rtl\">מוֹלְדִים</span>, with suffix, emphatic form <span dir=\"rtl\">מוֹלֵידָיו</span>. <span class=\"citation\">Keth. 72ᵇ</span>, v. <a href=\"#\" data-headword=\"יוֹלֵד\">יוֹלֵד</a>.</div>","alt":[]},"17467":{"h":"מוֹלָד","r":"M00491","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָלַד\">יָלַד</a>) <i>birth-time</i>. <span class=\"citation\">Sot. 11ᵇ</span> <span dir=\"rtl\">זמן מוֹלָדֵיהֶן</span> their time of giving birth; <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">מולידיהן</span> (corr. acc.).—<span dir=\"rtl\">מוֹלַד לבנה</span> (or only <a href=\"#\" data-headword=\"מ׳\">מ׳</a>) the beginning of the first quarter of the moon, <i>New-Moon</i>. <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">מ׳ הלבנה היה וכ׳</span> the New-Moon took place on a Wednesday at noon-time.—*2) <i>travail</i>. <span class=\"citation\">B. Bath. 16ᵇ</span> <span dir=\"rtl\">מִתְרַפָּה ממוֹלָדָהּ</span> (not <span dir=\"rtl\">מתרפא</span>) she is relieved of her severe throes (differ. vers. in Ms. M., v. Rabb. D. S. a. l. note).</div>","alt":[]},"17468":{"h":"מוֹלָדָא","r":"M00492","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Chr. XII, 32</span>; <span class=\"citation\">Targ. Y. I Gen. I, 14</span> <span dir=\"rtl\">מוֹלַד סיהרא</span> = h. <span dir=\"rtl\">מ׳ הלבנה</span>, v. <a href=\"#\" data-headword=\"מוֹלָד\">preced.</a></div>","alt":[]},"17469":{"h":"מוֹלֵדָא","r":"M00493","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"מְיַלֶּדֶת\">מְיַלֶּדֶת</a>, <i>midwife</i>. <span class=\"citation\">Ab. Zar. 26ᵃ</span> <span dir=\"rtl\">מ׳ יהודייתא</span></div>","alt":[]},"17470":{"h":"מוּלְוַות","r":"M00494","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּלְתָא\">מוּלְתָא</a></div>","alt":[]},"17471":{"h":"מולי","r":"M00495","html":"<div class=\"sense\"><i>mule</i>, v. <a href=\"#\" data-headword=\"מוּלָא II\"><span dir=\"rtl\">מוּלָא</span> II</a>.</div>","alt":[]},"17472":{"h":"מוּלִי","r":"M00496","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"מוּלִי\">מוּלִים</a> m. (v. <a href=\"#\" data-headword=\"מוּלָא I\">מוּלָא</a>) <i>mule-drivers</i>. <span class=\"citation\">Y. Yoma I, 38ᶜ</span>; Y. Meg. IV, end, 75ᶜ, v. <a href=\"#\" data-headword=\"חוּלְדָּה II\"><span dir=\"rtl\">חוּלְדָּה</span> II</a>.</div>","alt":[]},"17473":{"h":"מוּלְיָא","r":"M00497","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>) <i>filled up ground, mound</i>. <span class=\"citation\">B. Bath. 54ᵃ</span> <span dir=\"rtl\">שקל מ׳ ושדא וכ׳</span> if one takes earth from the mound and throws it on the low ground; <span dir=\"rtl\">מ׳ במ׳</span> if one throws from mound on mound (to make them even); <span class=\"citation\">M. Kat. 10ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"מוּלְיָיתָא\">מוּלְיָיתָא</a>. <span class=\"citation\">Erub. 56ᵇ</span>, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a>—V. <a href=\"#\" data-headword=\"מַלְיְתָא\">מִלֵּיתָא</a>.—[For pr. n. pl. with <a href=\"#\" data-headword=\"מוּלְיָא\">מוליא</a> or <span dir=\"rtl\">מליתא</span>, <span dir=\"rtl\">מלתא</span>, v. respective determinants.]</div>","alt":[]},"17474":{"h":"מוּלְיָאר","r":"M00498","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (miliarium, μιλιάριον) <i>a large vessel to boil water in, caldron</i>. <span class=\"citation\">Sabb. III, 4</span> מ׳ הגרוף <i>a miliarium</i> from under which the coals have been removed; Y. ib. III, 6ᵃ bot.</div>","alt":["מוּלְיָיר"]},"17475":{"h":"מוֹלֵיד","r":"M00499","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹלֵד\">מוֹלֵד</a>.—<span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">מולידיהן</span>, v. <a href=\"#\" data-headword=\"מוֹלָד\">מוֹלָד</a>.</div>","alt":[]},"17476":{"h":"מוֹלִידָא","r":"M00500","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָלַד\">יְלַד</a>) <i>parent</i>.—Pl. <span dir=\"rtl\">מוֹלִידִין</span>. Cant. R. introd.; <span class=\"citation\">Yalk. Sam. 134</span>, v. <a href=\"#\" data-headword=\"דִּכְוָת־\">דִּכְוָת־</a>.</div>","alt":[]},"17477":{"h":"מוּלְיוֹן","r":"M00501","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (mulio) <i>muleteer</i>, a figure in a Roman play; cmp. <a href=\"#\" data-headword=\"בּוּקְיוֹן\">בּוּקְיוֹן</a>. <span class=\"citation\">Tosef. Ab. Zar. II, 6</span>; <span class=\"citation\">Yalk. Ps. 613</span>.—[<span class=\"citation\">Y. Ber. VIII, 12ᵇ</span>, v. <a href=\"#\" data-headword=\"מוּלְתָא\">מוּלְתָא</a>.]</div>","alt":[]},"17478":{"h":"מוּלְיֵי","r":"M00502","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>) <i>filling</i>. <span class=\"citation\">Y. Bets. II, 61ᶜ</span> top; <span class=\"citation\">Y. Maas. Sh. V, 56ᶜ</span> top; <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> bot., v. <a href=\"#\" data-headword=\"*בִּשְׂרוּתָה\">בִּשְׂרוּתָא</a>. [Ḥiddushé Meïri to <span class=\"citation\">Bets. 20ᵃ</span> quotes: <span dir=\"rtl\">כשורתא בעיא מלאי</span> a joist (to be felled) requires the (wooden) <i>handle</i> (of an axe), i.e. the teacher is beaten by his own pupil.]</div>","alt":[]},"17479":{"h":"מוּלָּיָיאתָא","r":"M00503","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַמּוּלָּאֵי\">מַמּוּלָאֵי</a></div>","alt":[]},"17480":{"h":"מוּלְיָיר","r":"M00504","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּלְיָאר\">מוּלְיָאר</a></div>","alt":[]},"17481":{"h":"מוּלְיְיתָא","r":"M00505","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>) <i>stuffing, stuffed meat</i>. <span class=\"citation\">Pes. 74ᵃ</span> <span dir=\"rtl\">האי מ׳</span> (Ms. M. 2 <a href=\"#\" data-headword=\"מַלְיְתָא\">מַלְיְתָא</a>, v. Rabb. D. S. a. l. note 50) a roasted lamb stuffed with raw and unsalted meat; <span class=\"citation\">ib.ᵇ</span></div>","alt":[]},"17482":{"h":"מוּלְיָיתָא","r":"M00506","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"מוּלְיָא\">מוּלְיָא</a> a. of <a href=\"#\" data-headword=\"מוּלְתָא\">מוּלְתא</a>.</div>","alt":[]},"17483":{"h":"מוּלָּיָיתָא","r":"M00507","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַמּוּלָּאֵי\">מַמּוּלָאֵי</a></div>","alt":[]},"17484":{"h":"מולישות","r":"M00508","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מלישות\">מלישות</a></div>","alt":[]},"17485":{"h":"מוּלִיתָא","r":"M00509","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּלְתָא\">מוּלְתָא</a></div>","alt":["מוּלְיָתָא"]},"17486":{"h":"מוּלָּיָתָא","r":"M00510","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַמּוּלָּאֵי\">מַמּוּלָאֵי</a></div>","alt":[]},"17487":{"h":"מוֹלֶךְ","r":"M00511","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Molekh</i>, the fire-god of the Canaanites and others. <span class=\"citation\">Snh. VII, 7</span> <span dir=\"rtl\">למ׳ … עד שימסור למ׳ וכ׳</span> he who dedicates a child to M., is not punishable until he surrenders it to M. and passes it through fire. <span class=\"citation\">Ib. 64ᵃ</span> <span dir=\"rtl\">קתני עכו&quot;ם וקתני מ׳</span> the Mishnah speaks first of idolatry (in general) and then of M.; <span dir=\"rtl\">מ׳ לאו עכו&quot;ם היא</span> (sub. <span dir=\"rtl\">עבודת</span>) the Molekh worship is not included in general idolatry. Tosef. ib. X, 5 <span dir=\"rtl\">אחד מ׳ ואחד וכ׳</span> whether he passes his son through fire for M. or for any other idol, he is equally punishable; Snh. l. c. Ib. <span dir=\"rtl\">מפני מה … מ׳ כל שהמליכוהו עליהם וכ׳</span> why does the Torah use the expression Molekh (when meaning any idol)? Whatever people make their ruler <a href=\"#\" data-headword=\"מֶלֶךְ\">(מֶלֶךְ</a>); Y. ib. VII, 25ᶜ top. Bab. ib. l. c. <span dir=\"rtl\">מ׳ עראי</span> an improvised object of worship (a stone, piece of wood &amp;c.); a. fr.</div>","alt":[]},"17488":{"h":"מוֹלְכָנָא","r":"M00512","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלַךְ\">מְלַךְ</a>) <i>counsel</i>. <span class=\"citation\">Targ. Y. I Num. XXI, 29</span>.  v. <a href=\"#\" data-headword=\"מִלְכָנָא\">מִלְכָּנָא</a>.</div>","alt":[]},"17489":{"h":"מוֹלְלָא","r":"M00513","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִלְלָא\">מִלְלָא</a></div>","alt":[]},"17490":{"h":"מוּלְתָא","r":"M00514","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מוּלָא II\"><span dir=\"rtl\">מוּלָא</span> II</a>) <i>mule</i>. <span class=\"citation\">Targ. II Chr. XXXIII, 13</span>.—<span class=\"citation\">Ib. 11</span> <a href=\"#\" data-headword=\"מוּלְוַות\">מוּלְוַות</a> (<i>pl.</i> constr., used as sing.).—<span class=\"citation\">Targ. Y. Ex. XIV, 7</span> מוּלִיתָא <i>team of mules</i>.—<i>Pl.</i> <a href=\"#\" data-headword=\"מוּלְיָיתָא\">מוּלְיָיתָא</a>, <a href=\"#\" data-headword=\"מוּלִיתָא\">מוּלְיָתָא</a>. <span class=\"citation\">Targ. Y. II ib. 25</span> (ed. Amst. <a href=\"#\" data-headword=\"מוּלִי\">מוּלִי׳</a>, v. supra; ib. <a href=\"#\" data-headword=\"מזלותא\">מזלותא</a>, corr. acc.).—<span dir=\"rtl\">מוּלָוָון</span>, <span dir=\"rtl\">מוּלָוָותָא</span>. Y. Ber. VIII, 12ᵇ ed. Lehm. (ed. <a href=\"#\" data-headword=\"מוּלְיוֹן\">מוליון</a>, corr. acc.). <span class=\"citation\">Y. Taan. III, 66ᶜ</span> top.</div>","alt":[]},"17491":{"h":"מוּם","r":"M00515","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.; = <a href=\"#\" data-headword=\"מאום\">מְאוּם</a>; v. <a href=\"#\" data-headword=\"מָה\">מָה</a>, </div><div class=\"sense\"><b>1)</b> <i>something, anything</i>. <span class=\"citation\">Ned. 66ᵇ</span>, v. <a href=\"#\" data-headword=\"יָפֶה\">יָפֶה</a>.—<span class=\"citation\">Y. Kidd. III, 64ᶜ</span> bot. <span dir=\"rtl\">מהו ממזר מום זר</span> what is <i>mamzer</i> (<a href=\"#\" data-headword=\"מַמְזֵר\">מַמְזֵר</a>)? Something repulsive; <span class=\"citation\">Yeb. 76ᵇ</span> <span dir=\"rtl\">ממזר כתיב מ׳ זר</span> the Law says <i>mamzer</i> which means anything repulsive (male or female); <span class=\"citation\">Sifré Deut. 248</span> <span dir=\"rtl\">כל שהוא מומזר</span> (corr. acc.) whatever is in any way repulsive.</div><div class=\"sense\"><b>—2)</b> <i>blemish</i>. <span class=\"citation\">Bekh. V, 5</span>, a. fr. <span dir=\"rtl\">בעל מ׳</span> having a blemish (unfit for the altar, for priestly service &amp;c.). <span class=\"citation\">Ib. VI, 9</span>, a. fr. <span dir=\"rtl\">הרי זה מ׳</span> this is a legal blemish; <span dir=\"rtl\">אינה מ׳</span> this is not &amp;c.—<span class=\"citation\">Meg. 29ᵃ</span>, v. <a href=\"#\" data-headword=\"יָהִיר\">יָהִיר</a>. <span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">מ׳ שבך וכ׳</span> do not reproach thy neighbor with a fault which is also thine own; a. fr.—Pl. <span dir=\"rtl\">מוּמִין</span>. <span class=\"citation\">Bekh. VI, 1</span> <span dir=\"rtl\">על אלו מ׳ וכ׳</span> these are the blemishes in consequence of which a first-born animal may be slaughtered (after the destruction of the Temple). <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">אין מ׳ בלבן</span> a blemish in the white of the eye is no blemish in the sense of the law. <span class=\"citation\">Ib. VII, 1</span> <span dir=\"rtl\">מ׳ אלו … פוסלין וכ׳</span> the above named blemishes, whether permanent or transitory, make also human beings unfit (for priesthood &amp;c.); a. fr.—Denom. <a href=\"#\" data-headword=\"הוּמָם\">הוּמָם</a> <i>to become blemished, defective</i>. <span class=\"citation\">Y. Shek. IV, 48ᵇ</span> <span dir=\"rtl\">שפודין תמימין והוּמְמוּ</span> they had redeemed them when they were without blemish, and they became blemished. <span class=\"citation\">Num. R. s. 12</span>, end; <span class=\"citation\">Cant. R. to VI, 4</span> <span dir=\"rtl\">ולא הוממו וכ׳</span> and they have not become unfit for sacrifices on account of blemishes or old age &amp;c., v. <a href=\"#\" data-headword=\"זָהַם\">זָהַם</a>.—<span class=\"citation\">Y. Yoma II, 39ᵈ</span> <span dir=\"rtl\">קטורת שכבת הוּמָמָה</span> frankincense which was extinguished is unfit for the altar.</div>","alt":[]},"17492":{"h":"מוּם ²","r":"M00516","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XI, 15</span>. <span class=\"citation\">Targ. Lev. XXI, 17</span>; a. fr.—<span class=\"citation\">Bekh. 35ᵃ</span> <span dir=\"rtl\">הוי מ׳</span> is a blemish in the sense of the law. <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">דלדידן הוי מ׳ וכ׳</span> which according to our (Jewish) laws is a blemish (unfitting for the altar), but is not so according to their (Roman) ritual; a. fr.—Pl. <span dir=\"rtl\">מוּמִין</span>, <a href=\"#\" data-headword=\"מוֹמֵי\">מוּמֵי</a>. <span class=\"citation\">Snh. 5ᵇ</span>, v. <a href=\"#\" data-headword=\"בְּקִיעַ II\"><span dir=\"rtl\">בְּקִיעַ</span> II</a>. <span class=\"citation\">Bekh. 36ᵇ</span>; a. fr.</div>","alt":["מוּמָא"]},"17493":{"h":"מוּמוֹס","r":"M00517","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μῖμος) <i>mimic actor, mime</i>. <span class=\"citation\">Lam. R. to III, 13</span> <span dir=\"rtl\">מכניסים את המ׳ וכ׳</span> (Ar. <a href=\"#\" data-headword=\"מיאמוס\">מיאמוס</a>, read <a href=\"#\" data-headword=\"מִימוֹס\">מִימוֹס</a>) they bring a mime on the stage, his head shaved &amp;c.; ib. introd. (R. Abbahu 6) <span dir=\"rtl\">המתים</span> (corr. acc.).—Pl. <a href=\"#\" data-headword=\"מוּמְסִין\">מוּמְסִין</a>. <span class=\"citation\">Gen. R. s. 80</span>, beg.—<span class=\"citation\">Cant. R. to VII, 9</span> <span dir=\"rtl\">תפתיא מימרס</span> (read: <span dir=\"rtl\">מִימוֹסִין</span>) <i>tiftayé</i> (<span class=\"citation\">Dan. III, 2</span>) means the actors.</div>","alt":[]},"17494":{"h":"מומזר","r":"M00518","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּם\">מוּם</a> h.</div>","alt":[]},"17495":{"h":"מוּמְחָא","r":"M00519","html":"<div class=\"sense\">, v. next w.—[<span class=\"citation\">Sabb. 58ᵃ</span>, v. <a href=\"#\" data-headword=\"מָחֵי\">מָחֵי</a>.]</div>","alt":[]},"17496":{"h":"מוּמְחֶה","r":"M00520","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָחָה\">מָחָה</a>; cmp. τρίβων, Lat. tritus) <i>tried, skilled, expert, practical</i>. <span class=\"citation\">Snh. 5ᵃ</span>; <span class=\"citation\">R. Hash. 25ᵇ</span> <span dir=\"rtl\">מ׳ לרבים</span> recognized by the public as an experienced judge. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין לך מ׳ וכ׳</span> there can be no expert more popular than Moses was. <span class=\"citation\">Bekh. IV, 4</span> (<span class=\"citation\">28ᵇ</span>) <span dir=\"rtl\">מ׳ לב&quot;ד</span> a lawyer approved by a court. <span class=\"citation\">Ab. Zar. 27ᵃ</span> top <span dir=\"rtl\">רופא מ׳</span> a practical physician (that has a reputation at stake). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אם היה מ׳ לרבים</span> if he is a recognized practitioner. <span class=\"citation\">Sabb. VI, 2</span> <span dir=\"rtl\">קמיע שאינו מן המ׳</span> an amulet which is not issued by an approved person; <span class=\"citation\">ib. 53ᵇ</span> <span dir=\"rtl\">קמיע שאינו מ׳</span> an unapproved amulet; <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">V), 10</span> <a href=\"#\" data-headword=\"מוּמְחָא\">מוּמְחָא</a>. Sabb. l. c. <span dir=\"rtl\">מ׳ לאדם</span> of approved effect on human beings. Y. ib. VI, 8ᵇ top <span dir=\"rtl\">קמיע זה מ׳</span> this amulet is approved.—<span class=\"citation\">Erub. V, 5</span> (<span class=\"citation\">58ᵇ</span>) <span dir=\"rtl\">אלא מן המ׳</span> (Ms. O. <span dir=\"rtl\">אלא מ׳</span>, v. Rashi a. l.) only one of the best of the expert class; (oth. opin. v. Bart. a. l.).—<span class=\"citation\">Gen. R. s. 30</span> <span dir=\"rtl\">צדיק ומ׳</span> a righteous man and at the same time a practical man; a. fr.—Pl. <span dir=\"rtl\">מוּמְחִים</span>, <span dir=\"rtl\">מוּמְחִין</span>. <span class=\"citation\">Snh. III, 1</span> (<span class=\"citation\">23ᵃ</span>) <span dir=\"rtl\">כשרים</span> (<a href=\"#\" data-headword=\"אוֹ I\">או</a>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a> (Bab. a. Y. ed. <span dir=\"rtl\">מ׳ מפי ב&quot;ד</span>, v. Rabb. D. S. a. l. note 1) men otherwise qualified and (or) authorized by the court; expl. ib. 23ᵃ <span dir=\"rtl\">אם היו כשרין נעשו כמ׳</span> if not disqualified (on account of kinship or bad conduct) they are to be considered as if they were authorized judges; a. e.—[<a href=\"#\" data-headword=\"מוּמְחֶה\">מומחה</a>, <a href=\"#\" data-headword=\"מוּמְחָא\">מומחא</a>, <span class=\"citation\">Sabb. 58ᵃ</span>, v. <a href=\"#\" data-headword=\"מָחֵי\">מָחֵי</a>.]</div>","alt":[]},"17497":{"h":"מוֹמֵי","r":"M00521","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְמֵי\">יְמָא</a>) <i>oath; imprecation, curse</i>. <span class=\"citation\">Targ. O. Num. V, 21</span> (Y. <a href=\"#\" data-headword=\"מְמוֹמֵי\">מְמוֹמֵי</a>). <span class=\"citation\">Targ. O. Lev. V, 1</span>. <span class=\"citation\">Targ. I Kings VIII, 31</span> (not <a href=\"#\" data-headword=\"מִתְנָא\">מוּ׳</a>); a. fr.—<span class=\"citation\">B. Mets. 85ᵃ</span> מ׳ עזובה דא I swear, this (my desire) has been abandoned. <span class=\"citation\">Lev. R. s. 6</span> (prov.) <span dir=\"rtl\">בין זכאי … לידי מ׳ תעול</span> right or wrong, do not run the risk of an oath. Y. Ned. I, 37ᵃ top, v. <a href=\"#\" data-headword=\"מוֹהֶה\">מוֹהֶה</a>; a. e.</div>","alt":[]},"17498":{"h":"מוּמְיָיקָה","r":"M00522","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(a corrupt. of <a href=\"#\" data-headword=\"מוּנְיָיק\">מוּנְיָיק</a>) <i>necklace, official badge</i>, v. <a href=\"#\" data-headword=\"הַמְנִיכָא\">הַמְנִיכָא</a>. <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> top.</div>","alt":[]},"17499":{"h":"*מומיתא","r":"M00523","html":"<div class=\"sense\"> (prob. to be read <a href=\"#\" data-headword=\"סְמָמִיתָא\">סְמוּמִיתָא</a>, or <span dir=\"rtl\">שְׁמ׳</span>) f. (v. <a href=\"#\" data-headword=\"סְמָמִיתָא\">סְמָמִיתָא</a>) <i>a mite</i>. <span class=\"citation\">Y. Sabb. I, 3ᵇ</span> <span dir=\"rtl\">מ׳ דרישא</span> head-mite, <span dir=\"rtl\">דמניא</span> clothes-mite.</div>","alt":[]},"17500":{"h":"מוּמְסִין","r":"M00524","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"מוּמוֹס\">מוּמוֹס</a>.</div>","alt":[]},"17501":{"h":"מוּמָר","r":"M00525","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (part. <i>Hof</i>. of <a href=\"#\" data-headword=\"מוּר\">מוּר</a>) </div><div class=\"sense\"><b>1)</b> <i>exchanged</i>, v. <a href=\"#\" data-headword=\"מוּר\">מוּר</a>.</div><div class=\"sense\"><b>—2)</b> <i>converted, apostate</i>, esp. <i>mumar, an open opponent of Jewish law, non-conformist</i>. [Our w. interchanges with <a href=\"#\" data-headword=\"מְשׁוּמָּד\">מְשׁוּמָּד</a> in eds. a. mss.] <span class=\"citation\">Ḥull. 4ᵇ</span> <span dir=\"rtl\">אפי׳ ישראל מ׳</span> even a non-observant Israelite; <span class=\"citation\">Tosef. ib. I, 1</span> <a href=\"#\" data-headword=\"מְשׁוּמָּד\">משומד</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"מ׳\">מ׳</a>). Ḥull. l. c. <span dir=\"rtl\">מ׳ לערלות</span> opposed to circumcision; <span dir=\"rtl\">מ׳ לאותו דבר</span> opposed to this one practice (of slaughtering according to ritual); ib. <span dir=\"rtl\">הוי מ׳ לכל התורה כולה</span> is considered as a rebel against the entire Law; ib. <span dir=\"rtl\">מ׳ לע&quot;א</span> accused of idolatry. Ib. 5ᵃ <span dir=\"rtl\">המ׳ ומנסך וכ׳</span>, expl. ib. <span dir=\"rtl\">מ׳ לנסך וכ׳</span> one accused of idolatrous libation &amp;c. <span class=\"citation\">Erub. 69ᵃ</span>, v. <a href=\"#\" data-headword=\"גִּילּוּי\">גִּילּוּי</a>. <span class=\"citation\">Ab. Zar. 26ᵇ</span> <span dir=\"rtl\">לתיאבון מ׳ להכעיס וכ׳</span> if eating unslaughtered flesh (<span dir=\"rtl\">נבילות</span>) to gratify his appetite, he is called a <i>mumar</i>; if he does it in a spirit of defiance, he is called a <i>min</i> (heretic). <span class=\"citation\">Ib.</span> (oth. opin.) <span dir=\"rtl\">אפי׳ להכעיס נמי מ׳</span> even if in defiance, he is only a <i>mumar</i>; <span class=\"citation\">Hor. 11ᵃ</span>; a. v. fr.—Pl. <span dir=\"rtl\">מוּמָרִים</span>. <span class=\"citation\">Yalk. Lev. 434</span>, quoted fr. Sifra Vayikra, N’dabah, ch. II, s. 2 (ed. <span dir=\"rtl\">משומדים</span>).</div>","alt":[]},"17502":{"h":"מוּמָרָא","r":"M00526","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">מוּמְרַיָּא</span>. <span class=\"citation\">Targ. Y. Lev. I, 2</span>.</div>","alt":[]},"17503":{"h":"מוֹמָתָא","r":"M00527","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְמֵי\">יְמָא</a>, v. <a href=\"#\" data-headword=\"מוֹמֵי\">מוּמֵי</a>; as to <a href=\"#\" data-headword=\"מוֹמָתָא\">מוֹתָא</a> cmp. <a href=\"#\" data-headword=\"דַּעְתָּא\">דַּעְתָּא</a> fr. <a href=\"#\" data-headword=\"יְדַע\">יְדַע</a>) <i>oath, imprecation, curse</i>. <span class=\"citation\">Targ. Job XXXI, 30</span> <span dir=\"rtl\">מומ׳</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"מוֹמָתָא\">מותא</a>). <span class=\"citation\">Targ. Ps. XXXVII, 22</span> מוֹמָתֵיה Ms. (ed. <a href=\"#\" data-headword=\"מוֹמָתָא\">מותא</a>). <span class=\"citation\">Targ. O. Num. V, 21</span> (ed. Amst. <a href=\"#\" data-headword=\"מוֹתָנָא\">מוֹתָנָא</a>). <span class=\"citation\">Targ. Ex. XXII, 10</span>; a. fr.—<span class=\"citation\">B. Kam. 114ᵃ</span> <span dir=\"rtl\">אינהו נמי חד אמ׳ שדו ליה</span> they (the gentile courts), too, in the case of there being only one witness, administer an oath to him (the claimant). <span class=\"citation\">Pes. 113ᵇ</span> <span dir=\"rtl\">ומוֹמָתַיְּיהוּ הכי</span> (Ms. M. <span dir=\"rtl\">ומומי קרו להון</span> incorr.; Ms. M. 2 <span dir=\"rtl\">וכי מיימן מיימן הכי</span>, v. Rabb. D. S. a. l. note) and thus they swear.—[<span class=\"citation\">Ned. I, 2</span> <a href=\"#\" data-headword=\"בָּמוֹתָא\">במותא</a>, v. <a href=\"#\" data-headword=\"מוֹהֶה\">מוֹהֶה</a>.]</div>","alt":["(מוֹתָא)"]},"17504":{"h":"מוּן","r":"M00528","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">מִי־הוֹן</span>) <i>who?</i> Targ. II Esth. VII, 5 <span dir=\"rtl\">בר מ׳</span> (ed. Amst. <a href=\"#\" data-headword=\"מַן\">מַן</a>) whose son?</div>","alt":[]},"17505":{"h":"מוֹנָא","r":"M00529","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mona;</i> v. <a href=\"#\" data-headword=\"מָנָא III\"><span dir=\"rtl\">מָנָא</span> III</a>.</div>","alt":[]},"17506":{"h":"מוּנְבָּז","r":"M00530","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Μονόβαζος) <i>Munbaz</i>, </div><div class=\"sense\"><b>1)</b>  name of a King of Adiabene, and of one of his sons who embraced the Jewish faith (v. Jos. Ant. XX, 2, 1 sq.; B. J. II, 19, 2). <span class=\"citation\">Gen. R. s. 46</span>.—<span class=\"citation\">Tosef. Peah IV, 18</span>; Y. ib. I, 15ᵇ bot.; <span class=\"citation\">B. Bath. 11ᵃ</span>. <span class=\"citation\">Yoma III, 10</span> (Ar. <a href=\"#\" data-headword=\"מוּלְבָּז\">מוּלְבָּז</a>). <span class=\"citation\">Men. 32ᵇ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  name of a scholar. <span class=\"citation\">Tosef. Sabb. VIII</span> (<span class=\"citation\">IX), 5</span>; <span class=\"citation\">Sabb. 68ᵇ</span>; <span class=\"citation\">Yalk. Num. 749</span>.</div>","alt":[]},"17507":{"h":"מוֹנְגִּינוֹס","r":"M00531","html":"<div class=\"sense\"> (corr. <span dir=\"rtl\">מוֹנוֹגִינֵיס</span>) m. (μονογενής) <i>only child</i>. <span class=\"citation\">Pesik. R. s. 10</span>.</div>","alt":[]},"17508":{"h":"מוּנְדְּרוֹן","r":"M00532","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַדְרוֹן\">מַדְרוֹן</a></div>","alt":[]},"17509":{"h":"מונהי","r":"M00533","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מונחי\">מונחי</a></div>","alt":[]},"17510":{"h":"מוֹנוֹמָכוֹס","r":"M00534","html":"<div class=\"sense\"> (<span dir=\"rtl\">מנומ׳</span>) m. (μονομάχος) <i>gladiator</i>. Y’lamd. to Gen. XLIX, 1, quot. in Ar. <span dir=\"rtl\">אין מ׳ עושה דייתיקי</span> a gladiator makes no will (has nothing to dispose of; <span class=\"citation\">Yalk. Gen. 157</span> <a href=\"#\" data-headword=\"עֲבַד I\">עבד</a>; Gen. R., addit., ed. Wil. p. 376, Var. <a href=\"#\" data-headword=\"לוּדָר\">לוּדָר</a>).</div>","alt":[]},"17511":{"h":"מונחי","r":"M00535","html":"<div class=\"sense\">, <span class=\"citation\">Lam. R. to I, 13</span>, prob. to be read: <span dir=\"rtl\">מוּמְחִין</span>, v. <a href=\"#\" data-headword=\"מוּמְחֶה\">מוּמְחֶה</a>; v. <a href=\"#\" data-headword=\"בַּבְלִי\">בַּבְלִי</a>.</div>","alt":["מונהי"]},"17512":{"h":"מונטיא","r":"M00536","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 44</span> some ed., v. <a href=\"#\" data-headword=\"*מִלְכָי\">מִלְכָי</a></div>","alt":[]},"17513":{"h":"מוֹנִיטָא","r":"M00537","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (moneta) <i>mint</i>; <i>coin, coinage</i>. <span class=\"citation\">Ex. R. s. 5</span>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"עוּר I\">העיר</a>) <span dir=\"rtl\">חמי הדא מ׳</span></span> look at this coin. Esth. R. end <span dir=\"rtl\">מה המלך מ׳ שלו הולכת … כך מרדכי מ׳ וכ׳</span> as the King’s coinage passed all over the country, so did his (Mordecai’s) coinage &amp;c.; <span dir=\"rtl\">ומה מ׳ שלו</span> and what was the legend of his coinage? <span class=\"citation\">Y. Snh. II, 20ᵇ</span> top <span dir=\"rtl\">עדיין מ׳ … קיים</span> (<i>masc</i>.) our lord Saul’s coinage still exists (he is yet king; Midr. Sam. ch. XXIII <a href=\"#\" data-headword=\"מַטְבֵּיעַ\">מטבע</a>). <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">מ׳ של אלהיכם בטלה ושלכם קיימת</span> the coinage of your gods is abolished (the Egyptian gods are defeated), and shall your coinage remain (shall you continue to beget)?—<span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">כל מ׳ של מצרים אינה אלא בים וכ׳</span> every stamp (names of the descendants) of Mitsrayim is marked with <a href=\"#\" data-headword=\"יָם\">ים</a> (the sea in which they were destined to perish): <i>Ludim</i> (as though) <i>Lude-yam</i> &amp;c.; Yalk. Chr. 1073; a. fr.—Pl. <span dir=\"rtl\">מוֹנִיטִין</span>. <span class=\"citation\">Yalk. Gen. 62</span> [read:] <span dir=\"rtl\">כל מ׳ … אינן אלא פסולין</span>, v. <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a>. <span class=\"citation\">Gen. R. s. 39</span>; <span class=\"citation\">Yalk. Josh. 17</span> [read:] <span dir=\"rtl\">יצאו להם מ׳</span> (not <a href=\"#\" data-headword=\"מוניטון\">מוניטון</a>) their coins (medals in their memory) were issued; a. e.—[<span dir=\"rtl\">מוניטא מן כדו</span>, <span class=\"citation\">Gen. R. s. 44</span>, v. <a href=\"#\" data-headword=\"*מִלְכָי\">מִלְכָי</a>.]</div>","alt":["מוֹנִיטָה"]},"17514":{"h":"מוניטון","r":"M00538","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹנִיטָא\">preced.</a></div>","alt":[]},"17515":{"h":"מוּנְיָיק","r":"M00539","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μανιάκης, v. <a href=\"#\" data-headword=\"הַמְנִיכָא\">הַמְנִיכָא</a>) <i>necklace</i>. <span class=\"citation\">Deut. R. s. 4</span> [read:] <span dir=\"rtl\">הרי מ׳ והרי כבלים אם עשית רצוני הרי מ׳ של זהב ואם לאו וכ׳</span> (v. <span class=\"citation\">Yalk. Is. 256</span>) here is a necklace and here are chains; if thou doest my will, here is a golden necklace for thee; if not &amp;c. <span class=\"citation\">Pesik. R. s. 29-30</span>.—Pl. <span dir=\"rtl\">מוּנְיָיקוֹת</span>. <span class=\"citation\">Ib.</span> (ref. to <span dir=\"rtl\">ענקים</span>, <span class=\"citation\">Prov. I, 9</span>) <span dir=\"rtl\">עשה הקב&quot;ה … כמ׳ וכ׳</span> (not … <span dir=\"rtl\">קית</span></div>","alt":["מָנְ׳"]},"17516":{"h":"מוֹנִינֵי","r":"M00540","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (a comp. of <a href=\"#\" data-headword=\"מוֹי\">מוֹי</a> a. <a href=\"#\" data-headword=\"נוּן\">נוּנָא</a>; Versions vary, betw. <span dir=\"rtl\">מוני׳</span>, <span dir=\"rtl\">מֵינוּ׳</span> a. <span dir=\"rtl\">מֵנוּ׳</span>) <i>fish-brine, small fish in brine</i>; in gen. <i>brine</i>. <span class=\"citation\">Keth. 60ᵇ</span> <span dir=\"rtl\">דאכלה מ׳ וכ׳</span> a woman that eats <i>moniné</i> (during pregnancy) will &amp;c. <span class=\"citation\">Snh. 49ᵃ</span> <span dir=\"rtl\">אפי׳ מ׳ וצחנתא וכ׳</span> (<span class=\"citation\">Yalk. Kings 172</span> <span dir=\"rtl\">מ׳ דצ׳</span>) even brine and (Yalk.; brine of) hashed fish he used to taste and give to the poor. <span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">מ׳ דקמצי</span> brine of locusts. <span class=\"citation\">Ab. Zar. 29ᵃ</span> <span dir=\"rtl\">מ׳ לתעניתא</span> (Ms. M. <span dir=\"rtl\">נוניני</span>) <i>m</i>. is good to eat after fasting. <span class=\"citation\">Gitt. 69ᵇ</span></div>","alt":[]},"17517":{"h":"מוסטף","r":"M00541","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָטַף\">סָטַף</a></div>","alt":[]},"17518":{"h":"מוּסְיָא","r":"M00542","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Mysia</i>, a district of Asia Minor. <span class=\"citation\">Targ. Y. Gen. X, 2</span> Ar. (for h. text <a href=\"#\" data-headword=\"מֶשֶׁךְ\">מֶשֶׁךְ</a>; ed. <a href=\"#\" data-headword=\"אוסיא\">אוסיא</a> q. v.); <span class=\"citation\">Targ. I Chr. I, 5</span> ed. Rahmer (ed. Lag. <a href=\"#\" data-headword=\"אוסיא\">אוסיא</a>); <span class=\"citation\">Yoma 10ᵃ</span>; <span class=\"citation\">Y. Meg. I, 71ᵇ</span> bot. <a href=\"#\" data-headword=\"מוּסְיָא\">מוּסְיָיא</a>.</div>","alt":[]},"17519":{"h":"מוסיף","r":"M00543","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּסָף\">מוּסָף</a></div>","alt":[]},"17520":{"h":"מוֹסֵירָה","r":"M00544","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹסֵרָה\">מוֹסֵרָה</a></div>","alt":[]},"17521":{"h":"מוּסְכִּין","r":"M00545","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (μόσχος, muscus) the animal perfume <i>musk</i>. <span class=\"citation\">Y. Ber. VI, end, 10ᵈ</span> (Ar. <span dir=\"rtl\">מוּסְקִין</span>), v. <a href=\"#\" data-headword=\"מוֹשְׁקְ\">מוֹשְׁקְ</a>. <span class=\"citation\">Keth. 75ᵃ</span> מוּשְׁקִין Ar. (missing in ed.), v. <a href=\"#\" data-headword=\"מוֹר ²\">מוּרָא</a>.</div>","alt":[]},"17522":{"h":"מוּסמִיס","r":"M00546","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְסִימִיס\">מְסִימיס</a></div>","alt":[]},"17523":{"h":"מוּסְמָס","r":"M00547","html":"<div class=\"sense\"> = <span dir=\"rtl\">מְמוּסְמָס</span>, v. <a href=\"#\" data-headword=\"מִסְמֵס I\">מִסְמֵס</a></div>","alt":[]},"17524":{"h":"מוּסָף","r":"M00548","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָסַף\">יָסַף</a>) [<i>addition</i>,] </div><div class=\"sense\"><b>1)</b> <i>attachment, rim</i> (cmp. <a href=\"#\" data-headword=\"אִסְטַגְיוֹת\">אִסְטַגְיוֹת</a>). <span class=\"citation\">Kel. V, 5</span> <span dir=\"rtl\">מוּסַף התנור</span> a chimney-piece; <span dir=\"rtl\">מ׳ היורה</span> the rim around a boiler in the ground. Ib. 11 <span dir=\"rtl\">מ׳ של טיט</span> a moulding of clay around the stove; <span class=\"citation\">Tosef. Kel. B. Kam. IV, 18</span>. <span class=\"citation\">Tosef. Par. XII</span> (<span class=\"citation\">XI), 10</span> <span dir=\"rtl\">מ׳ יורה</span>, v. supra. Ib. <span dir=\"rtl\">המוסיף</span> (corr. acc.); a. fr.</div><div class=\"sense\"><b>—2)</b>  (sub. <a href=\"#\" data-headword=\"תְּפִלָּא\">תְּפִלַּת</a>, <a href=\"#\" data-headword=\"קָרְבַּן\">קָרְבַּן</a>) <i>Musaf, additional offering, additional prayer</i> on Sabbaths and festive (and fast-) days. <span class=\"citation\">Tosef. Ber. III, 10</span> <span dir=\"rtl\">כל שאין בו מ׳</span> a half-festival on which there is no Musaf (prayer or offering); <span dir=\"rtl\">וכל שיש בו מ׳</span> and one on which there is a Musaf; <span class=\"citation\">Sabb. 24ᵃ</span> <span dir=\"rtl\">ימים שיש בהן קרבן מ׳</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כיון דלית ביה מ׳</span> since there is no Musaf appointed for it; a. fr.—<i>Pl.</i> (with sing. sense) <span dir=\"rtl\">מוּסָפִין</span>. Ib. <span class=\"citation\">Ber. IV, 1</span>. <span class=\"citation\">Ib. 28ᵃ</span>; a. fr.</div>","alt":[]},"17525":{"h":"מוּסָפָא","r":"M00549","html":"<div class=\"sense\">, <i>Musaf</i>. <span class=\"citation\">Y. Yoma VI, 43ᵈ</span> <span dir=\"rtl\">כד מפני מ׳</span> when he had finished the Musaf (on a fast day).—Pl. <span dir=\"rtl\">מוּסְפַיָּא</span>, <span dir=\"rtl\">מוּסָפִין</span>, <span dir=\"rtl\">מוּסָפֵי</span>. <span class=\"citation\">Targ. II Chr. VIII, 13</span>; a. e.—<span class=\"citation\">Ab. Zar. 14ᵇ</span>. <span class=\"citation\">Ber. 28ᵇ</span>; a. e.</div>","alt":[]},"17526":{"h":"מוּסָר","r":"M00550","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>discipline, morality, conduct</i>. <span class=\"citation\">Midr. Prov. to I, 2</span> <span dir=\"rtl\">אם יש … למד מ׳</span> if a man has wisdom, he can learn good conduct; <span class=\"citation\">ib. to I, 7</span>; <span class=\"citation\">Yalk. ib. 929</span>; a. e.</div>","alt":[]},"17527":{"h":"מוֹסֵר","r":"M00551","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">מוֹסֵרוֹת</span> (b. h.; <i>bands, fetters, restrictions</i>. <span class=\"citation\">Yeb. 77ᵃ</span> (ref. to <span class=\"citation\">Ps. CXVI, 16</span>; cmp. <a href=\"#\" data-headword=\"אִיסּוּר I\">אִיסּוּר</a>) <span dir=\"rtl\">שני מ׳ שהיו עלי פְּתַחְתָּם וכ׳</span> two restrictions which were against me thou hast untied (permitted) (by confining the prohibition of intermarriage to male Moabites and Ammonites), v. <a href=\"#\" data-headword=\"מוֹאָבִי\">מוֹאָבִי</a>.</div>","alt":[]},"17528":{"h":"מוֹסֵרָא","r":"M00552","html":"<div class=\"sense\"> ch. = <a href=\"#\" data-headword=\"מוֹסֵרָה\">next w.</a>, v. <a href=\"#\" data-headword=\"מֵצַר\">מֵצַר</a> h.</div>","alt":[]},"17529":{"h":"מוֹסֵרָה","r":"M00553","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוֹסֵרָא\">preced. art.</a>) <i>reins</i>. <span class=\"citation\">B. Mets. 8ᵇ</span> <span dir=\"rtl\">יושב לא תפוס במ׳ וכ׳</span> (not <span dir=\"rtl\">תפיס</span>) he who sits in the wagon has not taken hold of the reins, while he who rides holds the reins (and leads the heterogeneous animals, v. <a href=\"#\" data-headword=\"נָהַג\">נָהַג</a>).—Esp. (sub. <a href=\"#\" data-headword=\"אָחַז\">אחז</a> or <span dir=\"rtl\">תפס</span>; cmp. <a href=\"#\" data-headword=\"אַפְסָר\">אַפְסָר</a>) <i>taking hold of the reins as a form of taking possession</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ אינה קונה במציאה</span> Rashi a. Ms. R. 2 (v. Rabb. D. S. a. l. note 30) taking hold of the reins does not give possession to the finder. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ מחבירו קנה</span> getting the reins from a fellowman (the owner) means possession. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי לשון מ׳</span> what is the expression (the etymology of) <i>moserah?</i> (Answ.: from <a href=\"#\" data-headword=\"מָסַר\">מָסַר</a>).—<span class=\"citation\">Kidd. I, 4</span> quot. in Rashi to B. Mets. l. c. <span dir=\"rtl\">נקנית במו׳</span> (ed. <span dir=\"rtl\">במְסִירָה</span>) is taken possession of by seizing the reins (or chain). <span class=\"citation\">B. Kam. IV, 9</span> <span dir=\"rtl\">קשרו … במ׳</span> if the ownertied the animal (to a fence &amp;c.) by the reins. <span class=\"citation\">Par. II, 3</span> <span dir=\"rtl\">קיפל עליה את המ׳</span> if he threw the reins over her back. <span class=\"citation\">Y. Kidd. I, 60ᵃ</span> bot. <span dir=\"rtl\">מסר לו מ׳ של וכ׳</span> if he handed him the reins of one of the camels; a. fr.</div>","alt":["מוֹסֵירָה"]},"17530":{"h":"מוסרין","r":"M00554","html":"<div class=\"sense\">, Y. Sabb. VIII, 10ᵇ bot. <span dir=\"rtl\">שרי מ׳</span>, read: <a href=\"#\" data-headword=\"מִשְׁנִים\">מִשְׁרִין</a>; v. <a href=\"#\" data-headword=\"*בילוס\">בילוס</a></div>","alt":[]},"17531":{"h":"*מוּסְתְּקֵי","r":"M00555","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (redupl. of <span dir=\"rtl\">מסק</span>) <i>olive barrels</i>, consisting of loosely joined splices lined with pitch. <span class=\"citation\">Bets. 33ᵇ</span></div>","alt":[]},"17532":{"h":"מוּעָד","r":"M00556","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עוּד\">עוּד</a>) <i>forewarned</i>, esp. (law) <i>Muʿad</i> (v. <span class=\"citation\">Ex. XXI, 29</span>), <i>an animal whose owner stands forewarned</i> on account of three successive injuries; <i>liable to full indemnity</i>, contrad. to <a href=\"#\" data-headword=\"תָּם I\">תָּם</a>. <span class=\"citation\">B. Kam. I, 4</span> <span dir=\"rtl\">שור המ׳</span> an ox that has done damage three times. Ib. <span dir=\"rtl\">השן מ׳ לאכול וכ׳</span> the tooth of an animal is considered a <i>muʿad</i> with reference to eating such things as are fit to be eaten by it, i.e. damages for eating must be paid in full without previous forewarning. Ib. <span dir=\"rtl\">הרגל מ׳ לשבר וכ׳</span> the foot is a <i>muʿad</i> &amp;c., i.e. what an animal treads upon on its way must be paid for in full without forewarning. Ib. <span dir=\"rtl\">הנחש מ׳ לעולם</span> the serpent is always a <i>muʿad</i> (even when tamed). Ib. <span dir=\"rtl\">מ׳ משלם נזק שלם וכ׳</span> the <i>muʿad</i> pays full damage, collectible from the owner’s best property. Ib. II, 4 <span dir=\"rtl\">מ׳ כל שהעידו וכ׳</span> a <i>muʿad</i> is an animal against which three warnings on three days have been given; (another opin.) <span dir=\"rtl\">מ׳ שהעידו … פעמים</span> against which three warnings have been given (even in one day). Ib. 5 <span dir=\"rtl\">אדם מ׳ לעולם</span> damage done by a human being must under all circumstances be restored in full. Ib. 17ᵇ <span dir=\"rtl\">(<a href=\"#\" data-headword=\"הִידּוּס\">הידוס</a>) <span dir=\"rtl\">הרי זה מ׳</span></span> damage done by chickens must be restored in full; <span dir=\"rtl\">אינו מ׳</span> must not &amp;c.; a. v. fr.—Trnsf. <span dir=\"rtl\">מ׳ לעבירה</span> a <i>muʿad</i> for sin, i.e. <i>likely to sin again</i>. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">כיון שנשתלש בחטא נעשה מ׳ לע׳</span> having sinned three times, he has become a <i>muʿad</i> for sin.—Pl. <span dir=\"rtl\">מוּעָדִים</span>, <span dir=\"rtl\">מוּעָדִין</span>. <span class=\"citation\">B. Kam. I, 4</span>; <span class=\"citation\">Tosef. ib. I, 4</span> <span dir=\"rtl\">חמשה מ׳</span> there are five kinds of <i>muʿads</i>. <span class=\"citation\">B. Kam. 16ᵃ</span>; a. fr.</div>","alt":["מוּעֶדֶת"]},"17533":{"h":"מוֹעֵד","r":"M00557","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>appointed time, appointment</i>. <span class=\"citation\">Pes. I, 3</span> (<span class=\"citation\">10ᵇ</span>) <span dir=\"rtl\">בתוך המ׳</span> within the time appointed for the removal of leavened matter (up to the sixth hour of the day); <span dir=\"rtl\">אחר המ׳</span> after the time (until nightfall), Rashi; (oth. interpret., v. infra).—Pl. <span dir=\"rtl\">מוֹעֲדִים</span>. <span class=\"citation\">Erub. 54ᵇ</span> <span dir=\"rtl\">עשה מ׳ לתורה</span> have fixed times for the study of the Law, v. <a href=\"#\" data-headword=\"מוֹדִיעַ\">מוֹדִיעַ</a>.</div><div class=\"sense\"><b>—2)</b> <i>festive season, festival</i>, esp. = <span dir=\"rtl\">חוֹל הַמּ׳</span>, <i>the week-days intervening between the first and the last days of Passover and of Succoth</i>. <span class=\"citation\">M. Kat. I, 1</span>; a. fr.—Pes. l. c. <span dir=\"rtl\">בתוך המ׳</span> during the festive week of Passover; <span dir=\"rtl\">לאחר המ׳</span> after Passover, Tosaf.; (oth. interpret., v. supra).—Pl. <span dir=\"rtl\">מוֹעֲדִים</span>, <span dir=\"rtl\">מוֹעֲדוֹת</span>. <span class=\"citation\">Pes. X, 6</span> <span dir=\"rtl\">מ׳ ורגלים אחרים</span> other seasons and festivals. <span class=\"citation\">Sabb. 145ᵇ</span> <span dir=\"rtl\">מ׳ שבבל שמחים</span> the festivals in Babylonia are joyously celebrated; a. fr.—מ׳ קטן <i>Moʿed Katon</i>, (<i>half-festival</i>) name of a treatise of the Mishnah, Tosefta, Talmud Babli and Y’rushalmi, of the Order of Moʿed.—סדר מ׳ <i>the Order of Moʿed</i>, name of the second order of the Mishnah, Tosefta and Talmud Babli and Y’rushalmi.</div>","alt":[]},"17534":{"h":"מוֹעֵד ²","r":"M00558","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Sam. I, 3</span>; <span class=\"citation\">4</span>.—<span class=\"citation\">M. Kat. 18ᵇ</span> <span dir=\"rtl\">חולא דמ׳</span> = <span dir=\"rtl\">חוֹל הַמּוֹעֵד</span>, v. <a href=\"#\" data-headword=\"מוֹעֵד\">preced.</a> <span class=\"citation\">Y. Ab. Zar. I, 39ᵇ</span> bot. <span dir=\"rtl\">בריה דמ׳</span> the day or days after a (gentile) festival.—Pl. <span dir=\"rtl\">מוֹעֲדִין</span>, <span dir=\"rtl\">מוֹעֲדַיָּא</span>. <span class=\"citation\">Targ. Lev. XXIII, 2</span>. <span class=\"citation\">Targ. Hos. II, 13</span>; a. fr.</div>","alt":["מוֹעֲדָא"]},"17535":{"h":"*מוּעֲדָא","r":"M00559","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>liable to do damage</i>. <span class=\"citation\">Targ. Prov. XXV, 19</span> <span dir=\"rtl\">רגלא מ׳</span> (h. text <span dir=\"rtl\">מועדת</span>, v. <span class=\"citation\">B. Kam. I, 4</span>; Ms. <span dir=\"rtl\">מְזָעֲתָא</span>, v. <a href=\"#\" data-headword=\"זוּעַ\">זוּעַ</a>; cmp. Lam. R. introd., R. Ḥănina 2, v. <a href=\"#\" data-headword=\"רָפַס\">רָפַס</a> a. <a href=\"#\" data-headword=\"מִטְמֵט\">מִטְמֵט</a>).</div>","alt":[]},"17536":{"h":"מוּעֶדת","r":"M00560","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּעָד\">מוּעָד</a></div>","alt":[]},"17537":{"h":"מוּעָט","r":"M00561","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">מְמ׳</span>; <a href=\"#\" data-headword=\"מָעַט\">מָעַט</a>) <i>small, minute, sparse</i>. <span dir=\"rtl\">דבר מ׳</span> <i>a little</i>; <i>small</i> (<i>spot</i> &amp;c.). <span class=\"citation\">Tosef. Sot. XV, 12</span>, sq.; <span class=\"citation\">Tosef. B. Bath. II, 17</span> <span dir=\"rtl\">משייר בה ד׳ מ׳</span> leaves a little portion (of the wall) unfinished in remembrance of the destruction of Jerusalem; <span dir=\"rtl\">משיירת ד׳ מ׳</span> leaves off a little portion of her toilet. <span class=\"citation\">Ḥag. I, 5</span> <span dir=\"rtl\">זה וזה מ׳</span> if he has little of both. <span class=\"citation\">Ib. 8</span> <span dir=\"rtl\">שהן מקרא מ׳</span> the Biblical text for these laws is sparse. <span class=\"citation\">Gitt. 14ᵃ</span> <span dir=\"rtl\">מתנה מ׳</span> a small gift. Sifra Tsav, ch. XV, Par. 11 <span dir=\"rtl\">סמיכה מ׳</span> the putting on of hands which is rarer (than waving, being confined only to live sacrifices); <span dir=\"rtl\">תנופה מ׳</span> waving which is rarer (being performed by one person only, while putting hands on is done by all sharers in the sacrifice); a. fr.—Pl. <span dir=\"rtl\">מוּעָטִים</span>, <span dir=\"rtl\">מוּעָטִין</span>; <span dir=\"rtl\">מוּעָטוֹת</span>. Ḥag. l. c. <span dir=\"rtl\">אוכלים מרובים ונכסים מ׳</span> many eaters (members of the household partaking of the peace-offering) and small wealth. Ib. <span dir=\"rtl\">עולות מ׳</span> less burnt-offerings (than peace-offerings). Ib. 11ᵃ <span dir=\"rtl\">מקרא … והלכות מ׳</span> the Rabbinical laws sparse in comparison to the profuse Bible text on the subject. <span class=\"citation\">Arakh. 30ᵇ</span> <span dir=\"rtl\">וכי יש … שנים מ׳</span> are there longer and shorter years?; a. fr.—Esp. <a href=\"#\" data-headword=\"מוּעָט\">מוּעָט</a>, <span dir=\"rtl\">מְמוּעָט</span> <i>the smaller thing, the lesser sphere</i>. <span class=\"citation\">R. Hash. 4ᵇ</span>, a. fr. <span dir=\"rtl\">תפסת מרובה לא תפסת תפסת מ׳ תפסת</span> if you take hold of the larger thing, you may lose your hold, if of the smaller, you will hold it, i.e. where the interpretation is doubtful, select the smaller number; <span class=\"citation\">Y. Yoma II, end, 40ᵃ</span> <span dir=\"rtl\">הממ׳</span>. Sifra Vayikra, N’dab., ch. XIII, <span class=\"citation\">Par. XII</span> <span dir=\"rtl\">הממ׳</span> the least portion thereof. <span class=\"citation\">Y. Keth. III, 27ᵈ</span> bot. <span dir=\"rtl\">בושת הקטן ממ׳</span> the disgrace of a minor is the less grave thing; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ונזקי ממ׳</span> and the indemnity he gets, is smaller; a. fr.</div>","alt":["מוּעֶטֶת"]},"17538":{"h":"מוֹעִיל","r":"M00562","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*יָעַל\">יָעַל</a>.—[<span class=\"citation\">Meïl. 14ᵇ</span> <span dir=\"rtl\">דקא מועיל</span>, v. <a href=\"#\" data-headword=\"מְעַל\">מְעַל</a>.]</div>","alt":[]},"17539":{"h":"מופיון","r":"M00563","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ab. Zar. I, 40ᵃ</span>, v. <a href=\"#\" data-headword=\"בּוּקְיוֹן\">בּוּקְיוֹן</a></div>","alt":[]},"17540":{"h":"מוּפְלָא","r":"M00564","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּלָא\">פָּלָא</a>) </div><div class=\"sense\"><b>1)</b> <i>concealed, hidden</i>; <i>miraculous</i>. <span class=\"citation\">Ḥag. 13ᵃ</span> (quot. fr. Ben Sira) <span dir=\"rtl\">במ׳ ממך וכ׳</span> search not into that which is concealed from thee (mysteries of theosophy); <span class=\"citation\">Gen. R. s. 8</span> (v. <a href=\"#\" data-headword=\"פְּלִיאָה\">פְּלִיאָה</a>). <span class=\"citation\">Midr. Till. to Ps. III</span>; a. e.—Pl. <span dir=\"rtl\">מוּפְלָאִים</span>, <span dir=\"rtl\">מוּפְלָאִין</span>. <span class=\"citation\">Snh. 16ᵇ</span> (play on <a href=\"#\" data-headword=\"פְּלֵתִי\">פלתי</a>) <span dir=\"rtl\">שמ׳ מעשיהן</span> for their proceedings are wonderful; <span class=\"citation\">Ber. 4ᵃ</span> <span dir=\"rtl\">שמ׳ ברבריהם</span>.—Trnsf. (in the phrase <span dir=\"rtl\">מ׳ סמוך לאיש</span>, arisen from <span dir=\"rtl\">איש כי יפלא</span>, <span class=\"citation\">Lev. XXVII, 2</span>) <i>a child whose power of discrimination is uncertain</i>. <span class=\"citation\">Tem. 2ᵇ</span> לרבות מ׳ הסמוך לאיש <i>ish</i> (Lev. l. c.) is used in connection with vows (<span dir=\"rtl\">ערכיו</span>) in order to include ‘a doubtful person next to a man’, i.e. a boy near the age of religious majority; <span class=\"citation\">Num. R. s. 10</span>; <span class=\"citation\">Naz. 62ᵃ</span>; a. e.—<span class=\"citation\">Ib. 29ᵇ</span> <span dir=\"rtl\">מ׳ סמוך לאיש דרבנן</span> the rule that the vow of a boy of twelve years of age is valid is merely a rabbinical enactment.—2) <i>distinguished</i>, esp. <i>mufla</i>, a special expert assessor at court to whom questions of law are referred, <i>instructing judge</i>. <span class=\"citation\">Hor. I, 4</span> (if a court gave a wrong decision) <span dir=\"rtl\">לא היה מ׳ של ב&quot;ד שם</span> in the absence of the <i>mufla</i>. <span class=\"citation\">Ib. 4ᵇ</span> <span dir=\"rtl\">לא היה מ׳ … נמי פטורין וכ׳</span> so also, if the <i>mufla</i> was absent, they cannot be made responsible for their decision, because they ought to have informed themselves and did not do so (therefore their judgment was not a legal act at all). <span class=\"citation\">Y. Snh. I, 19ᶜ</span> top <span dir=\"rtl\">היה הוא ומ׳ שלהן וכ׳</span> he (the questioner) and the <i>mufla</i> of the court (to whom the question had been referred) went to &amp;c.; <span class=\"citation\">Tosef. Snh. VII, 1</span>; <span class=\"citation\">Tosef. Ḥag. II, 9</span> <a href=\"#\" data-headword=\"מוּפְלָג\">מופלג</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"מוּפְלָא\">מופלא</a>). <span class=\"citation\">Sifré Deut. 152</span> (ref. to <span dir=\"rtl\">יפלא</span>, <span class=\"citation\">Deut. XVII, 8</span>) <span dir=\"rtl\">מלמד שבמ׳ הכתוב מדבר</span> this intimates that the text speaks of the <i>mufla;</i> <span class=\"citation\">Snh. 87ᵃ</span> top (Rashi: = <a href=\"#\" data-headword=\"מוּמְחֶה\">מומחה</a>). <span class=\"citation\">Cant. R. to III, 7</span>; <span class=\"citation\">Num. R. s. 11</span> (ref. to <a href=\"#\" data-headword=\"סָרִיס\">סריס</a>, <span class=\"citation\">II Kings XXV, 19</span>) <span dir=\"rtl\">זה מ׳ של ב&quot;ד וכ׳</span> the <i>saris</i> means the <i>mufla</i> of the court, who is called <i>saris</i> (mediator) &amp;c., v. <a href=\"#\" data-headword=\"סָרַס II\"><span dir=\"rtl\">סָרַס</span> II</a>.—Pl. <span dir=\"rtl\">מוּפְלָאִין</span>. <span class=\"citation\">Hor. 7ᵃ</span> Ms. M. a. Rashi (ed. <span dir=\"rtl\">מוּפְלִין</span>). Midr. Till. to Ps. l. c. <span dir=\"rtl\">מוּפְלָאֵי ב&quot;ד</span>.</div>","alt":[]},"17541":{"h":"מוּפְלָג","r":"M00565","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פָּלַג\">פָּלַג</a>. [<span class=\"citation\">Tosef. Ḥag. II, 9</span>, v. preced.]</div>","alt":[]},"17542":{"h":"מוֹפֵת","r":"M00566","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יֶפֶת\">יפת</a>, cmp. <a href=\"#\" data-headword=\"יָפֶה\">יָפֶּה</a>) <i>confirmation, evidence</i>; <i>miracle</i>. <span class=\"citation\">Sifré Deut. 83</span> אות בשמים … מ׳ בארץ <i>oth</i> (sign) refers to a phenomenon in the heavens, … <i>mofeth</i> to one on earth. <span class=\"citation\">Snh. 93ᵃ</span> <span dir=\"rtl\">אנשים שנעשה להם מ׳</span> men in whose behalf a miracle was effected. Y. ib. XI, end, 30ᶜ; a. fr.—<span class=\"citation\">Ḥull. 103ᵇ</span> <span dir=\"rtl\">מ׳ הדור</span> thou prodigy of the generation!—Pl. <span dir=\"rtl\">מוֹפְתִים</span>, <span dir=\"rtl\">מוֹפְתִין</span>. Tanḥ. Sh’moth 23.</div>","alt":[]},"17543":{"h":"מוֹפֵת ²","r":"M00567","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XIII, 2</span>; a. e.—Pl. <span dir=\"rtl\">מוֹפְתִין</span>, <span dir=\"rtl\">מוֹפְתַיָּא</span>. Ib. <span class=\"citation\">Deut. VI, 22</span>. <span class=\"citation\">Targ. O. Ex. IV, 21</span>; a. fr.</div>","alt":["מוֹפְתָא"]},"17544":{"h":"מוּץ","r":"M00568","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">מצץ</span>) <i>to suck</i>.—Part. <span dir=\"rtl\">מָיֵיץ</span>. <span class=\"citation\">Sabb. 134ᵃ</span> <span dir=\"rtl\">האי ינוקא דלא מ׳</span> an infant that does not suck. <span class=\"citation\">Ib. 133ᵇ</span> <span dir=\"rtl\">אומנא דלא מ׳</span> a surgeon (circumciser) that fails to suck the blood out of the wound.—<span class=\"citation\">Ab. Zar. 32ᵃ</span> <span dir=\"rtl\">ומָיְיצֵי להו וכ׳</span> and they (the earthen vessels) resorb the wine (Ms. M. <span dir=\"rtl\">עד דמצי וכ׳</span>, v. <a href=\"#\" data-headword=\"מְצִי I\">מְצֵי</a>).</div>","alt":[]},"17545":{"h":"מוֹץ","r":"M00569","html":"<div class=\"sense\">, imper. of <a href=\"#\" data-headword=\"מָצַץ\">מָצַץ</a>.</div>","alt":[]},"17546":{"h":"מוֹץ ²","r":"M00570","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>sucked out, dry</i>,] <i>chaff</i>. <span class=\"citation\">Midr. Till. to Ps. I, 4</span> <span dir=\"rtl\">אם תאמר כמ׳ שבבקעה וכ׳</span> you might think ‘like the chaff’ in the valley in which there is yet some moisture &amp;c. <span class=\"citation\">Gen. R. s. 83</span>, end <span dir=\"rtl\">התבן והקש והמ׳ וכ׳</span> the straw, the stubble and the chaff were disputing with one another. <span class=\"citation\">Midr. Till. to Ps. II</span>; a. e.—[<span class=\"citation\">Tosef. Ter. III, 17</span> <span dir=\"rtl\">מן המ׳</span> ed. Zuck. from the <i>grain before it is threshed;</i> v., however, <a href=\"#\" data-headword=\"עֲרֵימָה\">עֲרֵימָה</a>.]</div>","alt":[]},"17547":{"h":"מוֹץ ³","r":"M00571","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXIX, 5</span> (ed. Lag. <a href=\"#\" data-headword=\"מֹץ\">מֹץ</a>). <span class=\"citation\">Targ. Hos. XIII, 3</span>; a. fr.—[<span class=\"citation\">Targ. Ps. LXIX, 21</span> <a href=\"#\" data-headword=\"מוֹץ ³\">מוצא</a>, some ed., read: <span dir=\"rtl\">מרעא</span>, v. <a href=\"#\" data-headword=\"מְרַע II\"><span dir=\"rtl\">מְרַע</span> II</a>.]—<span class=\"citation\">Y. Snh. X, 27ᵈ</span> bot. <span dir=\"rtl\">אהן מ׳ דבגויה וכ׳</span> the chaff which remains there (after the straw is removed) undermines the walls.</div>","alt":["מוֹצָא I"]},"17548":{"h":"מוֹצָא II","r":"M00572","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Motsa</i>, near Jerusalem (also named <i>Colonia</i>). <span class=\"citation\">Succ. IV, 5</span>. Y. ib. 54ᵇ bot. <span dir=\"rtl\">מהו מ׳ ממצייא וכ׳</span> what is Motsa? <i>Mamtsia</i> … named Colonia; Bab. <span class=\"citation\">ib. 45ᵃ</span> <span dir=\"rtl\">מקום קלניא … קרי ליה מ׳ וכ׳</span> the place was named Colonia, but why does our Tanna call it Motsa? (Answ.: as if <span dir=\"rtl\">מוֹצִיא</span>) <span dir=\"rtl\">איידי דמיפק וכ׳</span> because its inhabitants are exempt from royal taxes, he calls it <i>M</i>. (v. Sm. Ant. s. v. Colonia).</div>","alt":[]},"17549":{"h":"מוֹצָא III","r":"M00573","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. constr. <span dir=\"rtl\">מוֹצָאֵי</span> (b. h.; <i>exit</i>; <span dir=\"rtl\">מ׳ שבת</span> (abbrev. <span dir=\"rtl\">מו&quot;ש</span>, <span dir=\"rtl\">מוצ&quot;ש</span>) the night following the Sabbath; <span dir=\"rtl\">מ׳ יו&quot;ט</span> the night following a Holy Day. <span class=\"citation\">Tosef. Sabb. III, 5</span>; <span class=\"citation\">Ḥull. 15ᵃ</span>, a. e. <span dir=\"rtl\">יאכל במו&quot;ש</span> (or <span dir=\"rtl\">למו&quot;ש</span>) may be eaten after the Sabbath is past. <span class=\"citation\">Bets. 30ᵇ</span>; <span class=\"citation\">Sabb. 45ᵃ</span> <span dir=\"rtl\">עד מ׳ יו&quot;ט האחרון וכ׳</span> not before the end of the last day of the (Succoth) festival; a. v. fr.—<span dir=\"rtl\">מ׳ שביעית</span> the period beginning with the end of the Sabbatical year. <span class=\"citation\">Shebi. IV, 2</span>. <span class=\"citation\">R. Hash. 9ᵃ</span>; a. fr.</div>","alt":[]},"17550":{"h":"מוּצְהָב","r":"M00574","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֻצְהָב\">מֻצְהָב</a></div>","alt":[]},"17551":{"h":"מוצטבה","r":"M00575","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְטִיכִי\">מַסְטִיכִי</a></div>","alt":[]},"17552":{"h":"מוצינא","r":"M00576","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to IV, 1</span>, read: <a href=\"#\" data-headword=\"בּוּצִין\">בּוּצִינָא</a>, v. <a href=\"#\" data-headword=\"*גַּלְשָׁא\">גַּלְשָׁא</a></div>","alt":[]},"17553":{"h":"מוּצְעָר","r":"M00577","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צַעַר ²\">צְעַר</a>) <i>small, lesser</i>.—Pl. <span dir=\"rtl\">מוּצְעָרִין</span>. <span class=\"citation\">Sabb. 10ᵇ</span> <span dir=\"rtl\">מתוך … עונותיה מ׳</span> because its (Zoar’s) settlement was more recent, its sins were less (<span class=\"citation\">Yalk. Gen. 84</span> <span dir=\"rtl\">מועטין</span>).</div>","alt":[]},"17554":{"h":"מוּק","r":"M00578","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a> a. <span dir=\"rtl\">מקק</span>) <i>to be crushed, stamped upon; to be soft;</i> v. <a href=\"#\" data-headword=\"מוֹק\">next w.</a></div><div class=\"sense\"><b>Pa. מַיֵּיק  מַיֵּק</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בָּסַר I\"><span dir=\"rtl\">בָּסַר</span> I</a>; b. h. <i>Hif.</i>) <i>to talk contemptuously, sneer, mock</i>. <span class=\"citation\">Targ. Prov. XIX, 28</span> (Ms. corruptly <span dir=\"rtl\">ממריק</span>, for <span dir=\"rtl\">מְמַיֵּיק</span>). <span class=\"citation\">Ib. III, 11</span> <span dir=\"rtl\">תמריק</span> (read: <span dir=\"rtl\">תְמַיֵּיק</span>).</div></div><div class=\"sense\"><b>Af. אָמֵיק</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מוּצְעָר\">same</a>. Ib. IX, 12 (some ed. <span dir=\"rtl\">מֵמִיךְ</span>, v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>).—<span class=\"citation\">Targ. Is. XXXVII, 22</span> <span dir=\"rtl\">ממיקא</span> ed. Lag. (oth. ed. <span dir=\"rtl\">מעי׳</span>); <span class=\"citation\">Targ. II Kings XIX, 21</span> ממי׳ Bxt. (ed. Lag. <span dir=\"rtl\">מעי׳</span>).</div></div>","alt":[]},"17555":{"h":"מוֹק","r":"M00579","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּק\">preced.</a>) [<i>a soft hackled substance</i> (cmp. <a href=\"#\" data-headword=\"מוֹךְ\">מוֹךְ</a>),] <i>felt-sock</i> or <i>stocking</i>. <span class=\"citation\">Tosef. Yeb. XII, 10</span> (Ms. Erf. <span dir=\"rtl\">מוך</span>, marginal correction <span dir=\"rtl\">מוק</span>); <span class=\"citation\">Yeb. 102ᵇ</span> bot.</div>","alt":[]},"17556":{"h":"מוֹקָא","r":"M00580","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"מוֹקִי\">מוֹקֵי</a>. <span class=\"citation\">Targ. Esth. VIII, 15</span>, v. <a href=\"#\" data-headword=\"פַּרְתִּיאִין\">פַּרְתִּיאִין</a>.—<span class=\"citation\">Yeb. 102ᵇ</span> top <span dir=\"rtl\">חמשא זוזי מ׳</span> (Ar. <span dir=\"rtl\">זוגי נרמקי</span>, corr. acc.) five pairs of socks. <span class=\"citation\">Gitt. 68ᵇ</span> <span dir=\"rtl\">במ׳ קאתי</span> he (Solomon) comes to us with socks on his feet; <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 45</span>.—[<span class=\"citation\">Snh. 95ᵃ</span> מוקיה Ar., read: <span dir=\"rtl\">מוֹחֵיה</span> or <span dir=\"rtl\">מוֹקְדֵיה</span>, v. <a href=\"#\" data-headword=\"מוֹקְדָא II\"><span dir=\"rtl\">מוֹקְדָא</span> II</a>.]</div>","alt":[]},"17557":{"h":"מוֹקֵד","r":"M00581","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>fire-place, hearth where fire is maintained</i>.—<span dir=\"rtl\">בית המ׳</span> the room (in the Temple) in which fire is perpetually maintained. <span class=\"citation\">Tam. I, 1</span>; <span class=\"citation\">Midd. I, 1</span>; a. fr.—<span class=\"citation\">Sabb. I, 11</span> (<span class=\"citation\">19ᵇ</span>) <span dir=\"rtl\">מדורת בית מ׳</span> the pile in the fire-room (in the Temple or in private houses).</div>","alt":[]},"17558":{"h":"מוֹקֵד ²","r":"M00582","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Chr. II, 54</span>.—<span class=\"citation\">Snh. 33ᵇ</span> <span dir=\"rtl\"><span dir=\"rtl\">אדמוֹקְדָךְ יקיד</span> (<a href=\"#\" data-headword=\"זִיל\">זיל</a>) <span dir=\"rtl\">קוץ וכ׳</span></span> (not <a href=\"#\" data-headword=\"*יְקוֹד\">יקוד</a>; v. Rabb. D. S. a. l. note; Rashi: <span dir=\"rtl\">עד דמ׳</span>) while thy fire is burning, (go) cut thy gourd and roast it, i.e. when listening to your teacher give him your full attention, and you need ask no questions.—<span dir=\"rtl\">מ׳ דטבריה</span> (<span dir=\"rtl\">בית</span>, <span dir=\"rtl\">בי</span>) <i>the hot spring of Tiberias</i>. <span class=\"citation\">Esth. R. to I, 9</span> <span dir=\"rtl\">מוי דמ׳ דט׳</span> the waters of the hot spring &amp;c.; <span class=\"citation\">Yalk. Gen. 133</span> <span dir=\"rtl\">בניי דבי מ׳</span>; <span class=\"citation\">Gen. R. s. 79</span> <span dir=\"rtl\">בי בני דבית מ׳</span> the baths of &amp;c.; Pesik. B’shall. p. 89ᵇ <span dir=\"rtl\">הדין מקור</span> (corr. acc.).</div>","alt":["מוֹקְדָא I"]},"17559":{"h":"מוֹקְדָא II","r":"M00583","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"קָדְקֹד\">קָדְקֹד</a>) <i>top, crown of the head</i> (differ. fr. <a href=\"#\" data-headword=\"מוֹקֵד ²\">מוֹקְדָא</a>). <span class=\"citation\">Targ. Job II, 7</span> (ed. Lag. <span dir=\"rtl\">מוקר׳</span>, Var. <span dir=\"rtl\">מוקד׳</span>). <span class=\"citation\">Targ. Y. Deut. XXVIII, 35</span>. [<span class=\"citation\">Ib. 28</span> read: <a href=\"#\" data-headword=\"מוֹקְרָא I\">מוקרא</a>.] <span class=\"citation\">Targ. Ps. VII, 17</span> (ed. Lag. <a href=\"#\" data-headword=\"ר\">ר</a>, Var. <a href=\"#\" data-headword=\"ד\">ד</a>).</div>","alt":[]},"17560":{"h":"מוּקְדּוֹן","r":"M00584","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Μακεδών) <i>Macedonian</i>. <span class=\"citation\">Targ. I Chr. I, 7</span> (h. text <span dir=\"rtl\">יון</span>, v. <a href=\"#\" data-headword=\"מוּקְדּוֹנְיָא\">מוּקְדּוֹנְיָא</a>).—Esp. <span dir=\"rtl\">אלכסנדרוס מ׳</span> Alexander the Macedonian (Alex. the Great), v. <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרוֹס\">אֲלֶכְסַנְדְּרוֹס</a>. [Mekh. Yithro, Baḥod. s. 9 <a href=\"#\" data-headword=\"מ׳\">מ׳</a>, read with ed. Weiss <a href=\"#\" data-headword=\"רְבִיעִית\">רביעית</a> or <span dir=\"rtl\">אדום</span> = Rome.]—Pl. <span dir=\"rtl\">מוּקְדּוֹנִין</span>, <a href=\"#\" data-headword=\"מוּקְדּוֹנְיָא\">מַקְ׳</a>. <span class=\"citation\">Targ. Esth. VIII, 15</span> מ׳ דדהבא Macedonian gilt shoes.</div>","alt":["מַקְדּוֹן"]},"17561":{"h":"*מוּקְדּוֹנָא","r":"M00585","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"מוּקְדּוֹן\">same</a>. <span class=\"citation\">Targ. Esth. VIII, 15</span> <span dir=\"rtl\">כלילא … דדהבא מ׳</span> the great Macedonian gold crown; Targ. II Esth. VI, 10 <span dir=\"rtl\">כלילא … מוקדוניא</span>.</div>","alt":[]},"17562":{"h":"מוּקְדּוֹנְיָא","r":"M00586","html":"<div class=\"sense\"> (Μακεδωνία) <i>Macedonia</i>, esp. the Greek empire founded by Alexander the Great and his successors. <span class=\"citation\">Targ. Y. Gen. X, 2</span>; <span class=\"citation\">Targ. I Chr. I, 5</span> (h. text <span dir=\"rtl\">יון</span>); <span class=\"citation\">Gen. R. s. 37</span>, beg.; <span class=\"citation\">Yoma 10ᵃ</span> [read:] <span dir=\"rtl\">מדי כמשמעו יון זו מ׳</span>; v. <a href=\"#\" data-headword=\"אוֹבִיסוֹס\">אוֹבִיסוֹס</a>.</div>","alt":["מַקְ׳"]},"17563":{"h":"מוּקְדָּשׁ","r":"M00587","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַקְדַּשׁ\">מַקְדַּשׁ</a></div>","alt":["מוּקְדְּשָׁא"]},"17564":{"h":"מוֹקִי","r":"M00588","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"מוֹקִי\">מוֹקִים</a> v. <a href=\"#\" data-headword=\"קוּם\">קוּם</a></div>","alt":[]},"17565":{"h":"מוּקְיוֹן","r":"M00589","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Maccus, adapted to <a href=\"#\" data-headword=\"בּוּקְיוֹן\">בּוּקְיוֹן</a>) <i>Maccus</i> or <i>Macchus</i>, a buffoon in Roman farces. <span class=\"citation\">Ab. Zar. 18ᵇ</span>, a. e.; v. <a href=\"#\" data-headword=\"בּוּקְיוֹן\">בּוּקְיוֹן</a>.</div>","alt":[]},"17566":{"h":"מוקירוס","r":"M00590","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מַקְרִין I\"><span dir=\"rtl\">מַקְרִין</span> I</a></div>","alt":[]},"17567":{"h":"מוֹקְמָא","r":"M00591","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קוּם\">קוּם</a>) </div><div class=\"sense\"><b>1)</b> <i>stand</i>; with suffix <a href=\"#\" data-headword=\"מוֹקְמַת־\">מוֹקְמַת־</a>. <span class=\"citation\">Targ. II Chr. XXXV, 15</span> <span dir=\"rtl\">על אתר מ׳</span> ed. Lag. (ed. Beck <span dir=\"rtl\">על מ׳</span>; h. text <a href=\"#\" data-headword=\"מַעֲמָד\">מַעֲמָד</a>). </div><div class=\"sense\"><b>*2)</b> <i>place of combats, arena</i>. <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">שנים שירדו למ׳ וכ׳</span> (some ed. a. Matt. K. <a href=\"#\" data-headword=\"מְקָם\">מקמא</a>) two entered the arena (for a combat), one a professional, the other a private (amateur).—V. <a href=\"#\" data-headword=\"קוּם\">קוּם</a> ch.</div>","alt":[]},"17568":{"h":"מוֹקְמָנָא","r":"M00592","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוֹקְמָא\">preced.</a>) <i>standing by, attendance</i>. <span class=\"citation\">Targ. II Chr. IX, 4</span>; v. <a href=\"#\" data-headword=\"מְקָם\">מְקָם</a>.</div>","alt":[]},"17569":{"h":"מוֹקְמַת־","r":"M00593","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹקְמָא\">מוֹקְמָא</a> a. <a href=\"#\" data-headword=\"מְקָם\"><a href=\"#\" data-headword=\"מְקָם\">מְקָמָא</a>.</a></div>","alt":[]},"17570":{"h":"מוּקְסִין","r":"M00594","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">קסי</span>; cmp. <a href=\"#\" data-headword=\"קִסְוָה\">קִסְוָה</a> a. <a href=\"#\" data-headword=\"מָאן\">מָנָא</a>) a sort of <i>state garments</i>. <span class=\"citation\">Gen. R. s. 36</span>; <span class=\"citation\">Cant. R. to VII, 9</span>; <span class=\"citation\">Esth. R. to I, 12</span> (expl. <span dir=\"rtl\">סרבל־</span>, <span class=\"citation\">Dan. III, 21</span>) <span dir=\"rtl\">במוּקְסֵיהוֹן</span>; cmp. <a href=\"#\" data-headword=\"גֹּולְתָא\">גּוֹלְתָא</a>.</div>","alt":[]},"17571":{"h":"מוּקָּף","r":"M00595","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָקַף I\"><span dir=\"rtl\">נָקַף</span> I</a> a. II.</div>","alt":[]},"17572":{"h":"מוּקְצֶה","r":"M00596","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Part. Hof. of <a href=\"#\" data-headword=\"קָצָה\">קָצָה</a>) [<i>cut off, set aside, stored away</i>,] </div><div class=\"sense\"><b>1)</b> <i>a space back of the dwelling</i>, containing stored up wood, cattle in sheds &amp;c. <span class=\"citation\">Erub. II, 3</span>; <span class=\"citation\">ib. 22ᵃ</span>. <span class=\"citation\">Ib. X, 8</span>. <span class=\"citation\">Bets. IV, 1</span> <span dir=\"rtl\">עצים שבמ׳</span> wood in the <i>muktseh</i> (stored for the winter); a. e.</div><div class=\"sense\"><b>—2)</b> <i>store of fruits.</i> <span class=\"citation\">Maasr. III, 2</span>. <span class=\"citation\">Ib. I, 5</span> <span dir=\"rtl\">עד שיעשה מ׳</span> until the melon is stored away. <span class=\"citation\">Y. Ter. II, 41ᵈ</span> top <span dir=\"rtl\">היה נוטל … מן המ׳ על וכ׳</span> he took ten dry figs from the storage as tithes for ninety in the basket (designated for immediate use, v. <a href=\"#\" data-headword=\"כַּלְכָּלָה\">כַּלְכָּלָה</a>); (<span class=\"citation\">Men. 54ᵇ</span>; <span class=\"citation\">55ᵃ</span> <span dir=\"rtl\">מקצוע</span>).</div><div class=\"sense\"><b>—3)</b>  (sub. <a href=\"#\" data-headword=\"כלי\">כלי</a>) <i>the tool specially intended</i> (<i>for cutting figs</i>). <span class=\"citation\">Shebi. VIII, 6</span>, v. <a href=\"#\" data-headword=\"חַרְבָּה\">חַרְבָּה</a>; [Maim. <i>the shed where figs are spread for drying</i>.].</div><div class=\"sense\"><b>—4)</b> <i>an animal set aside</i> (<i>in a shed</i>) <i>for a sacrifice</i>. <span class=\"citation\">Tem. 28ᵇ</span> <span dir=\"rtl\">מ׳ לשבע שנים</span> set aside until it would be seven years old. <span class=\"citation\">Ib. 29ᵃ</span> <span dir=\"rtl\">מניין למ׳ מן התורה</span> where in the Torah is <i>muktseh</i> intimated? (misunderstood by Abbaye as meaning, ‘where is it intimated that an animal must be kept in an enclosed space for some time before it can be offered on the altar?’—and corrected as meaning, ‘where is it intimated that an animal designated for idolatry is forbidden for the Jewish altar?’).—<span class=\"citation\">Tosef. Ab. Zar. V</span> (<span class=\"citation\">VI), 10</span> <span dir=\"rtl\">איזה מ׳ מ׳ לע&quot;ז וכ׳</span> what is meant by <i>m</i>. (as forbidden for the altar)? That which has been set aside (in a special place designated for the purpose) for idolatrous use, but if one merely devoted it by word of mouth &amp;c. <span class=\"citation\">Tem. VI, 1</span>. Tosef. l. c. 9 <span dir=\"rtl\">מאימתי נקרא מ׳ משנעשה וכ׳</span> when is an animal called <i>m</i>. (for idolatry)? From the time that an act (of dedication) has been done with it; <span class=\"citation\">Tem. 29ᵃ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בּוֹ\">בו</a>) <span dir=\"rtl\">אין מ׳ אסור אלא עד שיעבדו</span></span> (v. Rashi’s first interpret.; second interpret.:) a <i>m</i>. remains forbidden only until it has been used for some work (whereby its designation for the idolatrous altar is annulled). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין מ׳ אסור … מעשה</span> a <i>m</i>. remains forbidden only until some act (as shearing its wool or some work) has been done with it; a. e.—4) (Sabbath law) <i>muktseh, that which is not counted on for use on the Sabbath or Holy Day</i> (v. <a href=\"#\" data-headword=\"מוּכָן\">מוּכָן</a> s. v. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>, a. <a href=\"#\" data-headword=\"הַזְמָנָה\">הַזְמָנָה</a>); <i>forbidden for use</i> or <i>handling</i>. <span class=\"citation\">Bets. 2ᵃ</span> <span dir=\"rtl\">מאי טעמייהו דב&quot;ש מ׳ הוא</span> what reason had Beth Shammai (to permit the egg laid on the Holy Day by a hen which is kept for laying eggs and can, therefore, not be used for consumption on that day)? Is it not <i>muktseh?</i> <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דאית ליה מ׳ אית ליה נולד</span> he who forbids <i>m</i>. forbids also <i>nolad</i> (v. <a href=\"#\" data-headword=\"יָלַד\">יָלַד</a>). <span class=\"citation\">Sabb. 44ᵃ</span> <span dir=\"rtl\">מ׳ מחמת מיאוס</span> not counted on (and therefore forbidden to handle) on account of its repulsiveness (e. g. an old clay candlestick); <span dir=\"rtl\">מ׳ מחמת איסור</span> <i>m</i>. in consequence of a ritual prohibition (e. g. a candlestick which on the entrance of the Sabbath could not be moved because a light was burning on it). Ib. 157ᵃ <span dir=\"rtl\">מ׳ מחמת חסרון כיס</span> not counted on for use on the Sabbath because the object is too expensive for a use for which it is not originally made; a. fr.—<i>Pl.</i> <span dir=\"rtl\">מוּקְצִים</span>, <span dir=\"rtl\">מוּקְצִין</span> <i>set apart, chosen</i>. <span class=\"citation\">Sifré Num. 85</span> (ref. to <span dir=\"rtl\">בקצה</span>, <span class=\"citation\">Num. XI, 1</span>) <span dir=\"rtl\">במ׳ שבהם</span> the fire seized the distinguished among them (with ref. to <a href=\"#\" data-headword=\"קָצִין\">קצין</a>, <span class=\"citation\">Jud. XI, 11</span>; <span class=\"citation\">Yalk. Num. 732</span> <span dir=\"rtl\">בקצינים</span>).—<i>Fem</i>. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצָה</a>, pl. <span dir=\"rtl\">מוּקְצוֹת</span>. <span class=\"citation\">Sabb. 43ᵇ</span> <span dir=\"rtl\">והא מ׳ נינהו</span> are they not <i>muktseh</i> (because they are not intended for human food)?</div>","alt":[]},"17573":{"h":"מוקצע","r":"M00597","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִקְצוֹעַ\">מִקְצוֹעַ</a></div>","alt":[]},"17574":{"h":"מוֹקְרָא I","r":"M00598","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְקַר\">יְקַר</a>) <i>honor</i>. <span class=\"citation\">Koh. R. to II, 20</span>; <span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">כל הדין מ׳ תיקריניה וכ׳</span> so much honor do you show to this old Jew?—<span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">כסא דמ׳</span>, v. <a href=\"#\" data-headword=\"יְקָר ²\">יְקָרָא</a>.</div>","alt":[]},"17575":{"h":"מוֹקְרָא II","r":"M00599","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נְקַר I, cmp. <a href=\"#\" data-headword=\"קוֹר I\"><span dir=\"rtl\">קוֹר</span> I</a>) [<i>pickings</i>,] <i>marrow, brain</i> (v. <a href=\"#\" data-headword=\"מוֹחַ ²\">מוֹחָא</a>). <span class=\"citation\">Targ. Job XXI, 24</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 28</span> <span dir=\"rtl\">דמטפשא מ׳</span> (not <a href=\"#\" data-headword=\"מוֹקֵד ²\">מוקדא</a>) which makes the brain fat (dulls man’s reason, v. <a href=\"#\" data-headword=\"טָפַשׁ\">טְפַשׁ</a>).—<span class=\"citation\">Ḥull. 93ᵃ</span> <span dir=\"rtl\">דביעי ודמ׳</span> the membrane covering the testicles and that covering the brain.—<span class=\"citation\">Yalk. Gen. 111</span>, end; <span class=\"citation\">Gen. R. s. 64</span>, end <span dir=\"rtl\">מוקריה</span> some ed., v. <a href=\"#\" data-headword=\"מַקּוֹרָא\">מַקּוֹרָא</a>.]—V. <a href=\"#\" data-headword=\"מוֹקְדָא II\"><span dir=\"rtl\">מוֹקְדָא</span> II</a>.</div>","alt":[]},"17576":{"h":"מוּקָּשׁ","r":"M00600","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>compared</i>, v. <a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>.</div>","alt":[]},"17577":{"h":"מוּקְשֶׁה","r":"M00601","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מִקְשָׁה\">מִקְשָׁה</a>) <i>a cucumber bed</i>. <span class=\"citation\">Y. Kil. III, 28ᶜ</span> bot.; a. e.—Pl. (fr. <span dir=\"rtl\">מוּקְשָׁא</span>) <span dir=\"rtl\">מוּקְשָׁיוֹת</span> (Y. dial. for <span dir=\"rtl\">מוקשאות</span>). Ib.ᵈ <span dir=\"rtl\">מוקשה בין המ׳</span> (not <a href=\"#\" data-headword=\"גֵּין\">גין</a>) a cucumber bed between cucumber beds.</div>","alt":[]},"17578":{"h":"מוּר","r":"M00602","html":"<div class=\"sense\">, <i>Hif.</i> <span dir=\"rtl\">הֵמִיר</span> (b. h.; </div><div class=\"sense\"><b>1)</b> <i>to exchange</i>. <span class=\"citation\">Snh. 56ᵇ</span> אלהים אני לא תְמִירוּנִי I am God, you shall not exchange me (for another god); a. e.—Esp. (with ref. to <span class=\"citation\">Lev. XXVII, 33</span>) <i>to substitute a dedicated sacrifice</i> (by which both become sacred property). <span class=\"citation\">Tem. I, 1</span> <span dir=\"rtl\">הכל מְמִירִים</span> (Bab. ed. <span dir=\"rtl\">מְמִירִין</span>) all persons have power to exchange; <span dir=\"rtl\">לא שאדם רשאי להָמִיר … המיר מוּמָר</span> which means not that one is permitted to exchange, but that if one did, the substitute is sacred. Ib. 2ᵃ <span dir=\"rtl\">יורש אינו מֵמִיר</span> an heir cannot exchange his father’s dedication. Ib. 3ᵃ, a. fr. <a href=\"#\" data-headword=\"מֵימַר\">מְיַמֵּר</a> (Pi. of <a href=\"#\" data-headword=\"יָמַר\">יָמַר</a>). Ib. I, 1 (7ᵇ) <span dir=\"rtl\">ממירים את שלהם</span> (Talm. ed. <span dir=\"rtl\">בשלהם</span>) can exchange what belongs to them. Ib. <span dir=\"rtl\">הבכור לא יְמִירֶנּוּ בו</span> (Talm. ed. <span dir=\"rtl\">אין ממירין בו</span>) he (the priest) cannot exchange the first-born animal (although it is his as the priest’s share). Ib. 2 <span dir=\"rtl\">ממירים מן הצאן על וכ׳</span> you can substitute small cattle for large; a. fr.—V. <a href=\"#\" data-headword=\"אֵימוּרִים ²\"><span dir=\"rtl\">אֵימוּרִים</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>to convert</i>. <span class=\"citation\">Yalk. Gen. 136</span> אני מֵמִיר אתכם I shall force you to abjure your religion (<span class=\"citation\">Gen. R. s. 82</span> <span dir=\"rtl\">משמיד</span>); v. <a href=\"#\" data-headword=\"מוּמָר\">מוּמָר</a>.</div><div class=\"sense\"><b>Hof. הוּמָר</b> <div class=\"sense\"><i>to be exchanged, to become sacred</i> (<i>without redeeming the original</i>). Part. <a href=\"#\" data-headword=\"מוּמָר\">מוּמָר</a>. <span class=\"citation\">Tem. I, 1</span>; a. fr., v. supra.</div></div>","alt":[]},"17579":{"h":"מוּר I","r":"M00603","html":"<div class=\"sense\"><i>Af</i>. <a href=\"#\" data-headword=\"אָמִיר\">אָמֵיר</a> (<i>Pa</i>. <a href=\"#\" data-headword=\"יָמַר\">יַמֵּר</a>) same. <span class=\"citation\">Tem. 2ᵇ</span> <span dir=\"rtl\">אֲמוּרֵי נמי מֵמִיר</span> he has also the power to exchange (v. <a href=\"#\" data-headword=\"מוּר\">preced.</a>). <span class=\"citation\">Ib. 10ᵇ</span> <span dir=\"rtl\">אֵימוּרֵי הוא דלא מְיַמֵּר וכ׳</span> (Rashi <a href=\"#\" data-headword=\"אֱמוֹרִי\">אמורי</a>) he has no power to exchange, but to dedicate he has. [<span class=\"citation\">B. Mets. 77ᵃ</span> <span dir=\"rtl\">אימר</span>. <a href=\"#\" data-headword=\"אִימַר\">אימרו</a>, v. <a href=\"#\" data-headword=\"מרי I\">מְרִי</a>.—[V. <a href=\"#\" data-headword=\"*אֲמוּרְיָא\">אֲמוּרְיָא</a>.]</div>","alt":[]},"17580":{"h":"מוּר II","r":"M00604","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אֲמַר\">אֲמַר</a>. <span class=\"citation\">Y. Ber. II, 5ᵇ</span> top <span dir=\"rtl\">נפיק ומור</span> he went out and said. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומוֹר דבתריה</span> (ed. Lehm. <span dir=\"rtl\">ואמור</span>) but say also what follows it.</div>","alt":[]},"17581":{"h":"מוֹר","r":"M00605","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>myrrh</i>. <span class=\"citation\">Ker. 6ᵃ</span>; <span class=\"citation\">Y. Yoma IV, 41ᵈ</span> (an ingredient of frankincense). <span class=\"citation\">Gen. R. s. 91</span>, end; <span class=\"citation\">Yalk. ib. 149</span> (not <a href=\"#\" data-headword=\"מורי\">מורי</a>), v. <a href=\"#\" data-headword=\"אֵיגוֹרִי\">אֵיגוֹרִי</a>. <span class=\"citation\">Mikv. IX, 5</span> <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> (Var. <a href=\"#\" data-headword=\"חֲמָר\">חֵמָר</a>); <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 16</span> <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> the myrrh-gum. <span class=\"citation\">Cant. R. to V, 16</span>; a. fr.—<span class=\"citation\">Ib. 13</span>; <span class=\"citation\">Sabb. 30ᵇ</span>, v. <a href=\"#\" data-headword=\"מַר II\"><span dir=\"rtl\">מַר</span> II</a>.—Pl. <span dir=\"rtl\">מוּרוֹת</span> <i>lumps of gum</i>. <span class=\"citation\">Lam. R. to I, 20</span> (play on <span dir=\"rtl\">חמרמרו</span> ib., as if fr. <a href=\"#\" data-headword=\"חֲמָר\">חֵמָר</a>) <span dir=\"rtl\">עשאן מ׳ מ׳</span>, v. <a href=\"#\" data-headword=\"גּוּשׁ II\"><span dir=\"rtl\">גּוּשׁ</span> II</a>.</div>","alt":["מֹר"]},"17582":{"h":"מוֹר ²","r":"M00606","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. XXX, 23</span> (Var. <a href=\"#\" data-headword=\"מֻרָּא\">מֻרָּא</a>, <a href=\"#\" data-headword=\"מוֹר ²\">מוּרָּא</a>, <a href=\"#\" data-headword=\"מֵירָא\">מֵירָא</a>, v. Berl. Targ. O. II, p. 29). <span class=\"citation\">Targ. Prov. VII, 17</span>. <span class=\"citation\">Targ. Ps. XLV, 9</span> <span dir=\"rtl\">מי׳</span>. Targ. II Esth. II, 5 (play on <span dir=\"rtl\">מ̇ר̇ד̇כ̇י̇</span>) <span dir=\"rtl\">מ̇ר̇א ד̇כ̇י̇א</span> ed. Lag. (oth. ed. <span dir=\"rtl\">מי׳</span>).—<span class=\"citation\">Ḥull. 139ᵇ</span> (translating <span dir=\"rtl\">מר דרור</span>, Ex. l. c.) <span dir=\"rtl\">מירא דכיא</span> clear (liquid) myrrh; <span class=\"citation\">Meg. 10ᵇ</span> <span dir=\"rtl\">מרי דכי</span> (Ms. O. a. L. <span dir=\"rtl\">מירא דכיא</span>, v. Rabb. D. S. a. l. note 20).—<span class=\"citation\">Keth. 75ᵃ</span> מוּרָה ומושקין Ar. (missing in ed.) myrrh and musk, v. <a href=\"#\" data-headword=\"קִיּוּהָא\">קִיּוּהָא</a>.</div>","alt":["מוּרָא","(מֵירָא)"]},"17583":{"h":"מוֹרָא I","r":"M00607","html":"<div class=\"sense\"> c. (b. h.; <i>fear, reverence.</i> <span class=\"citation\">Ab. I, 3</span>, a. fr. <span dir=\"rtl\">מ׳ שמים</span> the fear of the Lord. <span class=\"citation\">Ber. 28ᵇ</span> <span dir=\"rtl\">שתהא מ׳ שמים עליכם כמ׳ ב&quot;וד</span> (Ms. M. <span dir=\"rtl\">שיהא</span>) that your fear of the Lord be as great as the fear of man (before whom you hide yourselves when you want to do wrong). <span class=\"citation\">Kidd. 31ᵃ</span> <span dir=\"rtl\">הקדים הקב&quot;ה מ׳ האם למ׳ האב</span> the Lord (the Bible text) places the reverence due to the mother before that due to the father (<span class=\"citation\">Lev. XIX, 3</span>). Ib.ᵇ <span dir=\"rtl\">איזהו מ׳</span> whereby is filial reverence shown?; Sifra K’dosh., beg. <span dir=\"rtl\">איזו היא מ׳</span>. <span class=\"citation\">Ab. III, 2</span> <span dir=\"rtl\">שאלמלא מוֹרָאָהּ וכ׳</span> but for the fear of it (the secular government) &amp;c.; a. fr.—Fem. form <a href=\"#\" data-headword=\"מוֹרְאָה\">מוֹרְאָה</a>, constr. <a href=\"#\" data-headword=\"מוֹרְאָה\">מוֹרְאַת</a>. <span class=\"citation\">Kidd. 30ᵇ</span>. <span class=\"citation\">Num. R. s. 15</span> <span dir=\"rtl\">מורא זו … מ׳ הרב</span> this ‘fear’ (<span class=\"citation\">Koh. VIII, 13</span>), we know not what it refers to; but on reading … (<span class=\"citation\">Lev. XIX, 32</span>) we learn that it means the reverence due to one’s teacher. Ib. <span dir=\"rtl\">הרי מ׳ רבית ומ׳ משקלות</span> there is also the warning to fear the Lord attached to the prohibition of usury (<span class=\"citation\">Lev. XXV, 36</span>) and of false weights (ib. XIX, 36).—<span class=\"citation\">Naz. IX, 5</span>, v. <a href=\"#\" data-headword=\"מוֹרָה II\"><span dir=\"rtl\">מוֹרָה</span> II</a>.—[<span class=\"citation\">Yalk. Sam. 78</span> <span dir=\"rtl\">מה הדין מ׳ … הדין מ׳</span>, read: <span dir=\"rtl\">סירא … סערא</span>, v. Midr. Sam. ch. II.]</div>","alt":[]},"17584":{"h":"מוֹרָא II","r":"M00608","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (μωρά) <i>stupid, foolish</i>. Lam. R. introd. (R. Simeon) (play on <span dir=\"rtl\">מוראה</span>, <span class=\"citation\">Zeph. III, 1</span>) [read:] <span dir=\"rtl\">ל&quot;י הוא שכן בל&quot;י קורין לשוטיתא מ׳</span> it is a Greek expression, for in Greek they call a foolish woman <i>mora</i>; Yalk. Zeph. 567 <a href=\"#\" data-headword=\"מירה\">מירה</a> (corr. acc.). <span class=\"citation\">Midr. Till. to Ps. IX, 21</span> (play on <span dir=\"rtl\">מורה</span>, ib.) <span dir=\"rtl\">הכנס בהן … שכן בל&quot;י … מ׳</span> let folly enter into their hearts, for in Greek they call a fool <i>mora</i> (= <a href=\"#\" data-headword=\"מוֹרוֹס\">מוֹרוֹס</a>).</div>","alt":["מוֹרָה"]},"17585":{"h":"מוֹרְאָה","r":"M00609","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"מוֹרְאָה\">מוֹרְאַת</a>, v. <a href=\"#\" data-headword=\"מוֹרָא I\"><span dir=\"rtl\">מוֹרָא</span> I</a></div>","alt":[]},"17586":{"h":"מוּרְאָה","r":"M00610","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מֻרְאָה\">מֻרְאָה</a>; v. <a href=\"#\" data-headword=\"מָרָא\">מָרָא</a><i>Hif.</i>) <i>crop</i> of birds. <span class=\"citation\">Zeb. VI, 5</span>, sq. <span class=\"citation\">Yoma 21ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">מוּרְאוֹת</span>. <span class=\"citation\">Tam. I, 4</span>; Sifra Vayikra, N’dab., Par. 7, ch. IX.</div>","alt":[]},"17587":{"h":"מוּרָאנָה","r":"M00611","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרָנָא\">מוּרָנָא</a></div>","alt":[]},"17588":{"h":"מורביה","r":"M00612","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹרְכִיוָותָא\">מוֹרְכִיוָותָא</a></div>","alt":["מורביוותא","מורביות"]},"17589":{"h":"מוּרְבִּית I","r":"M00613","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבָה\">רָבָה</a>) <i>young tree</i> or <i>bough</i>.—Pl. <a href=\"#\" data-headword=\"מורביה\">מוּרְבִּיּוֹת</a>. <span class=\"citation\">Succ. IV, 5</span> (<span class=\"citation\">45ᵃ</span>) <span dir=\"rtl\">מ׳ של ערבה</span> (Mish. a. Ms. M. <a href=\"#\" data-headword=\"מַרְכְּבָא\">מַרְ׳</a>) young willows; <span class=\"citation\">Yalk. Ps. 876</span>. <span class=\"citation\">Tam. II, 3</span> <span dir=\"rtl\">מר׳</span>.</div>","alt":[]},"17590":{"h":"מוּרְבִּית II","r":"M00614","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"מורביה\">מוּרְבִּיּוֹת</a> (= <a href=\"#\" data-headword=\"מַרְבִּיעָה\">מוּרְבִּיעוֹת</a>, v. <a href=\"#\" data-headword=\"רְבִיעָה\">רְבִיעָה</a>) </div><div class=\"sense\"><b>1)</b> <i>watering times</i>. <span class=\"citation\">Y. Shebi. II, 34ᵃ</span> <span dir=\"rtl\">מנע ממנו שלש מ׳</span> (sub. <a href=\"#\" data-headword=\"מַיִם\">מים</a>) he omitted to water it for three periods (Mish. <span class=\"citation\">ib. 9</span> <span dir=\"rtl\">עונות</span>); Tosef. ib. II, 4 <a href=\"#\" data-headword=\"מְרֵיעוּת\">מריעות</a> ed. Zuck. (read: <a href=\"#\" data-headword=\"מַרְבִּיעָה\">מַרְבִּיעוֹת</a>; Var. <a href=\"#\" data-headword=\"מִרְבָּעָה\">מִרְבָּעוֹת</a>).</div><div class=\"sense\"><b>—2)</b> <i>layers, piles of hewn stones</i>. Ib. III, 1; <span class=\"citation\">Shebi. III, 5</span>.</div>","alt":[]},"17591":{"h":"מוֹרָג","r":"M00615","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹרִיג\">מוֹרִיג</a>, <a href=\"#\" data-headword=\"מוֹרִיגָא\"><a href=\"#\" data-headword=\"מוֹרִיגָא\">מוֹרִיגָא</a>.</a></div>","alt":["מוֹרֵג","מוֹרְגָא"]},"17592":{"h":"מורגוון","r":"M00616","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Lev. XIX, 36</span> some ed., v. <a href=\"#\" data-headword=\"מוֹדָנָא\">מוֹדָנָא</a>.</div>","alt":[]},"17593":{"h":"מוּרְגָּשָׁה","r":"M00617","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָגַשׁ\">רָגַשׁ</a>) <i>perception</i>.—Pl. <span dir=\"rtl\">מוּרְגָּשׁוֹת</span>. <span class=\"citation\">Num. R. s. 14</span> (some ed. <span dir=\"rtl\">מֻרְגָּשׁ׳</span>), v. <a href=\"#\" data-headword=\"הַרְגָּשָׁה\">הַרְגָּשָׁה</a>.</div>","alt":[]},"17594":{"h":"מוֹרֶד","r":"M00618","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֶרֶד I\"><span dir=\"rtl\">מֶרֶד</span> I</a></div>","alt":[]},"17595":{"h":"מוֹרִד","r":"M00619","html":"<div class=\"sense\"> m., <span dir=\"rtl\">מוֹרֶדֶת</span> f., v. <a href=\"#\" data-headword=\"מָרַד I\">מָרַד</a></div>","alt":[]},"17596":{"h":"מוֹרָד I","r":"M00620","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>descent</i>.—Pl. <span dir=\"rtl\">מוֹרָדוֹת</span>. <span class=\"citation\">Erub. 56ᵃ</span></div>","alt":[]},"17597":{"h":"מוֹרָד II","r":"M00621","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"מוֹרָד I\">מוֹרֵד</a>) m. name of a species of <i>locusts</i>. <span class=\"citation\">Tosef. Ḥull. III, 25</span>.</div>","alt":[]},"17598":{"h":"מוּרְדְּוָתָא","r":"M00622","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (רדי <i>to plough</i>) <i>furrows</i>. <span class=\"citation\">Targ. Ps. CXXIX, 3</span> <span dir=\"rtl\">מוּרְדְוָתְהוֹן</span> ed. Lag. (Regia <span dir=\"rtl\">מוּרְדְּיָת־</span>; ed. Wil. <span dir=\"rtl\">מוּרְדָּנִית־</span>; ed. Ven. <a href=\"#\" data-headword=\"מוֹרָנִית\">מורנית־</a>, corr. acc.).</div>","alt":[]},"17599":{"h":"מוּרְדְּיָא","r":"M00623","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּרְדְּוָתָא\">preced.</a>; cmp. <span dir=\"rtl\">חתר</span>, <span class=\"citation\">Jon. I, 13</span>) <i>rudder</i>. <span class=\"citation\">B. Mets. 87ᵃ</span>; <span class=\"citation\">Meg. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"*לִבְרוּת\">לִבְרוּת</a>.</div>","alt":[]}};
